window.__HRC_SHARD({"shard":"toe-drc-2018","builtAt":"2026-10-23T22:07:26+00:00","documents":[{"rec_id":"recenyyVjQEwTjwtP","doc_id":"TOE DRC (2018) - Official report - 18.08.2022","symbol":"A/HRC/51/60","title":"Report of the team of international experts on the Democratic Republic of the Congo","type":"Official report","date":"2022-08-18","year":2022,"bodies":["TOE DRC (2018)"],"paragraphCount":109,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/TOE DRC (2017) - 18-08-2022 - Official document - A_HRC_51_60 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recFcelLCcNFThdpq","doc_id":"TOE DRC (2018) - Official report - 10.08.2023","symbol":"A/HRC/54/76","title":"Assistance technique et renforcement des capacités dans le domaine des droits de l’homme en République démocratique du Congo — Rapport de l’Équipe d’experts internationaux en République démocratique du Congo","type":"Official report","date":"2023-08-10","year":2023,"bodies":["TOE DRC (2018)"],"paragraphCount":141,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/TOE DRC (2017) - Official document - A_HRC_54_76 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recRKoUWhEAMnMLuM","doc_id":"TOE DRC (2018) - Official report - 16.08.2024","symbol":"A/HRC/57/81","title":"Report of the team of international experts on the Democratic Republic of the Congo (final report)","type":"Official report","date":"2024-08-16","year":2024,"bodies":["TOE DRC (2018)"],"paragraphCount":133,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/TOE DRC (2017) - 16-08-2024 - Official report - A_HRC_57_81 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"reczKpHBpllGVhs0C","doc_id":"TOE DRC (2018) - Official report - 20.08.2025","symbol":"A/HRC/60/83","title":"Technical assistance and capacity-building in the field of human rights in the Democratic Republic of the Congo - final report of the Team of International Experts","type":"Official report","date":"2025-08-20","year":2025,"bodies":["TOE DRC (2018)"],"paragraphCount":149,"unnumbered":false,"gaps":[],"misprints":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/TOE DRC (2017) - 20-08-2025 - Official report - A_HRC_60_83 - EN.md","extractor":"pdftotext -layout"}],"paragraphs":[{"id":"a-hrc-51-60-u0000","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":null,"seq":0,"section":null,"text":"United Nations                                                                                 A/HRC/51/60\nGeneral Assembly                                                            Distr.: General\n18 August 2022\nEnglish\nOriginal: French","unnumbered":true},{"id":"a-hrc-51-60-u0001","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":null,"seq":1,"section":null,"text":"Summary\nThe present report is submitted pursuant to Human Rights Council resolution 48/20\nof 11 October 2021, which renewed the mandate of the team of international experts on the\nsituation in Kasai and extended it to cover the entire territory of the Democratic Republic of\nthe Congo. The Council requested the team of international experts to submit its final report\nto the Council, in the framework of an interactive dialogue, at its fifty-first session and to\npresent it with an oral update at its forty-ninth session. The implementation of this expanded\nmandate comes as the United Nations Organization Stabilization Mission in the Democratic\nRepublic of the Congo is gradually withdrawing from Tanganyika Province after having\nwithdrawn from the provinces of Kasai and Kasai Central.\nUnder its expanded mandate, the team of international experts conducted four field\nvisits and organized a workshop on the status and prospects of transitional justice in the\nDemocratic Republic of the Congo, in collaboration with the Ministry of Human Rights and\nthe United Nations Joint Human Rights Office in the Democratic Republic of the Congo.\nThe visits and the workshop allowed the team of international experts to develop a clearer\nunderstanding of the challenges and opportunities arising from the introduction of a system\nof transitional justice that will facilitate a break with past cycles of conflict, reconciliation\namong different population groups and observance of the rule of law, as a means of\nprotecting the gains to be made under the planned reforms.\nThese challenges include the cross-border nature of conflicts, insecurity and illegal\nresource exploitation. Moreover, long-standing intercommunal conflicts have been reignited,\noften as a smokescreen to draw attention away from the unlawful exploitation of the\ncountry’s agricultural, mining and land resources by armed groups. The country is\nexperiencing conflicts of an exceptionally violent nature, involving instances of rape and\nsexual violence, while the State is struggling to provide all citizens with the protection to\nwhich they are entitled. These conflicts are fuelled by hate speech and calls for violence and\ndiscrimination. Combined with widespread poverty, a high level of youth unemployment and\na lack of jobs and economic opportunities, the conflicts have led to an increase in crime and\nexposed young people to exploitation by armed groups and militias, including groups\naffiliated with political parties. These circumstances are a ticking time bomb, especially\nduring election periods.","unnumbered":true},{"id":"a-hrc-51-60-u0002","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":null,"seq":2,"section":null,"text":"Although sincere, the Government’s efforts and initiatives to promote disarmament,\ncommunity reintegration, reparation for victims, the fight against impunity and security and\njustice sector reforms require enhanced coordination with adequate communication and\ngreater national funding, with support from foreign partners, if they are to achieve their stated\nobjectives.\nImpunity for the violations of human rights and international humanitarian law\ndocumented in the report on the mapping exercise and in subsequent reports of the United\nNations Joint Human Rights Office and of Human Rights Council experts, the resumption of\nattacks by the Mouvement du 23 mars (M23) and the beginning of the Nairobi process\nfacilitated by the States members of the East African Community have demonstrated that it\nis essential to take account of the cross-border aspects of the conflicts and of transitional\njustice.\nTo promote dialogue and reflection on how the Democratic Republic of the Congo\ncan meet this set of challenges, the team of international experts organized, together with the\nMinistry of Human Rights and the United Nations Joint Human Rights Office, a workshop\non transitional justice, the outcomes of which will be taken into account by an expanded\nscientific committee that will be set up to propose a paper on the national transitional justice\npolicy.\nLastly, the team of international experts offers its conclusions and makes\nrecommendations with a view to strengthening current and future activities.","unnumbered":true},{"id":"a-hrc-51-60-p0001","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"1","seq":3,"section":"I. Introduction","text":"In its resolution 48/20 of 11 October 2021, the Human Rights Council renewed the\nmandate of the team of international experts on the situation in Kasai and extended it to cover\nthe entire territory of the Democratic Republic of the Congo in order to assist the country in\nits efforts to implement its transitional justice policy and to assess the follow-up given to\njudicial cases, particularly cases deemed a priority in the fight against impunity. The Human\nRights Council requested the team of international experts to submit its final report to the\nCouncil, in the framework of an interactive dialogue, at its fifty-first session and to present it\nwith an oral update at its forty-ninth session."},{"id":"a-hrc-51-60-p0002","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"2","seq":4,"section":"I. Introduction","text":"In resolution 48/20, the Human Rights Council reiterated its request to the Office of\nthe United Nations High Commissioner for Human Rights (OHCHR) to provide technical\nassistance, including forensic expertise, to the Government of the Democratic Republic of\nthe Congo in order to support the judicial authorities in their investigations into allegations\nof human rights violations and abuses, with a view to bringing those responsible to justice,\nand technical assistance to support the development of a transitional justice mechanism in\nthe Democratic Republic of the Congo."},{"id":"a-hrc-51-60-p0003","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"3","seq":5,"section":"I. Introduction","text":"The international experts Bacre Waly Ndiaye (Senegal), Chair of the team, and Marie\nThérèse Keita-Bocoum (Côte d’Ivoire), a team member, were appointed by the United\nNations High Commissioner for Human Rights on 11 November 2021 at the request of the\nHuman Rights Council. In the performance of its mandate, the team of international experts\nis supported by a coordinator and a human rights officer specializing in transitional justice.\nThe team of international experts drew up a plan of activities and conducted four field visits\nto the Democratic Republic of the Congo, from 1 to 12 December 2021, 1 to 15 March 2022,\n13 to 27 May 2022 and 13 to 26 July 2022."},{"id":"a-hrc-51-60-p0004","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"4","seq":6,"section":"I. Introduction","text":"During its first two visits, the team of international experts visited Kinshasa, Kalemie\nin Tanganyika Province, Goma in North Kivu and Bukavu in South Kivu to meet with\nmembers of the Government of the Democratic Republic of the Congo, provincial authorities,\ncivilian and military judicial authorities, the Special Representative of the Secretary-General\nin the Democratic Republic of the Congo and Head of the United Nations Organization\nStabilization Mission in the Democratic Republic of the Congo (MONUSCO),\nrepresentatives of all United Nations agencies, the diplomatic corps, provincial authorities,\nrepresentatives of the different communities and religious denominations and the President\nof the Panzi Foundation, as well as civil society and the press. In Kalemie, the team of\ninternational experts participated in the opening ceremony of the public consultations\norganized by the Government with the support of the United Nations Joint Human Rights\nOffice in the Democratic Republic of the Congo and the financial support of Belgium and\nthe United Nations Peacebuilding Fund."},{"id":"a-hrc-51-60-p0005","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"5","seq":7,"section":"I. Introduction","text":"On 7 December 2021, in Goma, the team of international experts participated in a\ntraining seminar on transitional justice for civilian and military judges from the provinces of\nNorth Kivu and South Kivu; on this occasion, the Chair of the team of international experts\ndelivered a statement on the transitional justice process in Grand Kasai. On 2 March 2022,\nthe team of international experts met with representatives of the Twa and Bantu communities."},{"id":"a-hrc-51-60-p0006","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"6","seq":8,"section":"I. Introduction","text":"During its third and fourth visits, the team of international experts met with the\nCoordinator of the Disarmament, Demobilization, Community Recovery and Stabilization\nProgramme, the Chair of the Standing Committee on Human Rights of the National\nAssembly, the President of the National Assembly and the members of the Joint Steering\nCommission on Transitional Justice, as well as the Chief Military Prosecutor at the Military\nHigh Court and the President of the Military High Court. During the second leg of its third\nmission, the team of international experts conducted a field visit to Lubumbashi, in Haut-\nKatanga Province, through which it learned about the factors at play in the conflict between\nthe Katangese and Kasai communities, including the Katangese community’s fear that the\ninflux of persons arriving from Kasai would alter the electoral majority; the activities of\nmilitias associated with political parties and of the Bakata Katanga armed group; and the\nimpact of hate speech in the Province."},{"id":"a-hrc-51-60-p0007","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"7","seq":9,"section":"I. Introduction","text":"From 19 to 21 July 2022, in Kinshasa, the team of international experts organized, in\ncollaboration with the Ministry of Human Rights and the United Nations Joint Human Rights\nOffice, a workshop on the status and prospects of transitional justice in the Democratic\nRepublic of the Congo."},{"id":"a-hrc-51-60-p0008","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"8","seq":10,"section":"I. Introduction","text":"In March 2022, in Geneva, the team of international experts presented its oral report\non the situation in the Democratic Republic of the Congo during an interactive dialogue at\nthe forty-ninth session of the Human Rights Council."},{"id":"a-hrc-51-60-p0009","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"9","seq":11,"section":"I. Introduction","text":"The present report is submitted in accordance with Human Rights Council resolution\n48/20. It highlights the various activities undertaken by the team of international experts in\nthe performance of its mandate."},{"id":"a-hrc-51-60-p0010","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"10","seq":12,"section":"II. Mandate","text":"The team of international experts adopted a two-pronged methodology: following up\non judicial cases, particularly cases deemed a priority in the fight against impunity, and\nmonitoring and supporting the authorities of the Democratic Republic of the Congo in the\ndevelopment and implementation of the transitional justice policy."},{"id":"a-hrc-51-60-p0011","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"11","seq":13,"section":"II. Mandate","text":"The implementation of the team’s expanded mandate comes at a time when\nMONUSCO is gradually withdrawing from Tanganyika Province, after its withdrawal from\nthe provinces of Kasai and Kasai-Central, a state of siege has been declared in the provinces\nof North Kivu and Ituri, conflicts between the Mouvement du 23 mars (M23) and the Armed\nForces of the Democratic Republic of the Congo have resumed in the eastern part of the\ncountry, violence has erupted between the Twa and Bantu communities in Tanganyika\nProvince, and the Katangese community has expressed hostility towards the Kasai\ncommunity in Haut-Katanga."},{"id":"a-hrc-51-60-p0012","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"12","seq":14,"section":"II. Mandate","text":"At the same time, the efforts of OHCHR and United Nations agencies to maintain a\npresence in those areas from which MONUSCO has withdrawn are worthy of note."},{"id":"a-hrc-51-60-p0013","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"13","seq":15,"section":"II. Mandate","text":"Despite the situation described above, the team of international experts made every\neffort to carry out its four field visits as planned and to take steps to support the Government."},{"id":"a-hrc-51-60-p0014","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"14","seq":16,"section":"III. Cooperation between the team of international experts and","text":"The team’s performance of its mandate requires genuine collaboration and effective\ncooperation with the Congolese authorities. The team was able to carry out its work without\nhindrance and enjoyed the continuous cooperation and openness of its Congolese\ninterlocutors."},{"id":"a-hrc-51-60-p0015","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"15","seq":17,"section":"III. Cooperation between the team of international experts and","text":"That open-mindedness was made apparent by the renewal and extension of the team’s\nmandate to the entire country at the request of the Government. The team welcomes the\nconstructive cooperation of the authorities of the Democratic Republic of the Congo in\nfacilitating its visits to the country."},{"id":"a-hrc-51-60-p0016","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"16","seq":18,"section":"IV. Current situation in the Democratic Republic of the Congo","text":"The four field visits allowed the team of international experts to assess the security,\npolitical, judicial, social and humanitarian situation."},{"id":"a-hrc-51-60-p0017","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"17","seq":19,"section":"IV. Current situation in the Democratic Republic of the Congo","text":"The team of international experts is concerned about the alarming security situation\nin the eastern provinces of the Democratic Republic of the Congo, particularly North Kivu\nand Ituri. It notes that since November 2021, M23 has resumed its attacks on the Armed\nForces of the Democratic Republic of the Congo and MONUSCO peacekeepers in North\nKivu. In February 2022, M23 destroyed a MONUSCO helicopter, killing eight\npeacekeepers.1 In addition, according to the United Nations Joint Human Rights Office, at\nleast 34 people, including 2 children, were killed when a rocket struck a school.2"},{"id":"a-hrc-51-60-p0018","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"18","seq":20,"section":"IV. Current situation in the Democratic Republic of the Congo","text":"The team of international experts also notes that the border town of Bunagana3 has\npassed into the hands of M23 and regrets the many human rights abuses that this occupation\nentails. The situation in the eastern part of the country has resulted in the mass displacement\nof more than 170,000 people4 to Uganda and neighbouring territories, leading to the further\ndeterioration of the humanitarian situation, particularly for women, children and other\nvulnerable people."},{"id":"a-hrc-51-60-p0019","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"19","seq":21,"section":"IV. Current situation in the Democratic Republic of the Congo","text":"The team of international experts further notes that the level of trust between different\npopulation groups has deteriorated considerably. Moreover, the authorities of the Democratic\nRepublic of the Congo and a large part of the national population accuse Rwanda of\nsupporting M23. This widespread suspicion has led to hate speech and to calls for violence\nand discrimination against population groups who speak Kinyarwanda. Despite the\nGovernment’s condemnation of this hate speech and the measures it has taken to stop it, it\nhas resulted in victims."},{"id":"a-hrc-51-60-p0020","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"20","seq":22,"section":"IV. Current situation in the Democratic Republic of the Congo","text":"On the diplomatic and military fronts, the Heads of State of the East African\nCommunity have taken measures to restore peace and end the conflict. Talks between the\nGovernment of the Democratic Republic of the Congo and several armed groups were held\nin Nairobi in April 2022, with the aim of bringing peace to the eastern part of the country."},{"id":"a-hrc-51-60-p0021","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"21","seq":23,"section":"IV. Current situation in the Democratic Republic of the Congo","text":"On the judicial front, the team of international experts remains concerned about the\nsevere lack of adequate human and material resources devoted to the administration of justice\nin the Democratic Republic of the Congo. The team of international experts notes the efforts\ndeployed by the Ministry of Justice to restore the civilian justice system in provinces where\na state of siege has been declared. In this context, an ordinance has been issued removing\nfrom the jurisdiction of the military courts all cases falling under the ordinary jurisdiction of\nthe civilian courts."},{"id":"a-hrc-51-60-p0022","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"22","seq":24,"section":"IV. Current situation in the Democratic Republic of the Congo","text":"On the social and humanitarian front, the team of international experts is concerned\nabout the persistence and occasional exacerbation of inter-community tensions and conflicts\nin the provinces of Ituri, North Kivu and South Kivu, which have resulted in the emergence\nof new armed groups and a resurgence in the forced recruitment of children into their ranks. 5\nThese groups claim to be engaged in the self-defence of their communities but their real\nmotive is to control resources and territory. Multiple attacks on defence and security forces,\nas well as incursions into villages involving abuses against civilians, have led to mass\ndisplacement towards the country’s interior and to neighbouring countries. Camps for\ndisplaced persons have also been the target of deadly attacks. The delivery of humanitarian\naid, the assessment of needs and the evaluation of strategies for the protection of civilians are\nseverely hampered by the difficulty of gaining access to affected areas."},{"id":"a-hrc-51-60-p0023","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"23","seq":25,"section":"IV. Current situation in the Democratic Republic of the Congo","text":"On 25 and 26 July 2022, at the end of its fourth visit, the team of international experts\nwas informed of violent demonstrations in the provinces of North Kivu and Ituri intended to\nforce the withdrawal of MONUSCO.\n1 Statement delivered by the spokesperson for the Military Governor of North Kivu on 29 March 2022.\n2 United Nations Joint Human Rights Office in the Democratic Republic of the Congo, biannual report,\nJanuary–June 2022.\n3 A town in North Kivu on the border with Uganda that is a geostrategically important cross-border\ntrade centre.\n4 United Nations Joint Human Rights Office in the Democratic Republic of the Congo, biannual report,\nJanuary–June 2022.\n5 Protection Cluster, Democratic Republic of the Congo, “Analyse de protection − provinces de l’Ituri\n& du Nord Kivu : focus sur 3 facteurs de dégradation de la situation humanitaire et de protection”\n(November and December 2021)."},{"id":"a-hrc-51-60-p0024","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"24","seq":26,"section":"V. Implementation of the expanded mandate of the team of","text":"Under its expanded mandate covering the entire territory of the Democratic Republic\nof the Congo, the team of international experts organized four visits to the country during\nwhich it met with Congolese authorities, civil society and international partners. Combating\nimpunity and promoting reconciliation and transitional justice were the main objectives of\nthese visits."},{"id":"a-hrc-51-60-p0025","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"25","seq":27,"section":"A. Combating impunity","text":"The fight against impunity was examined from three angles: its context, the follow-\nup given to judicial cases and the situation of victims."},{"id":"a-hrc-51-60-p0026","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"26","seq":28,"section":"1. Context","text":"With respect to the administration of justice in the Democratic Republic of the Congo,\nthe general context remains unchanged, despite the efforts deployed in that regard, which\nnonetheless deserve to be highlighted. The glaring lack of human, financial and material\nresources continues to be the main challenge in this respect."},{"id":"a-hrc-51-60-p0027","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"27","seq":29,"section":"1. Context","text":"The lack of judges significantly undermines the fight against impunity. According to\nthe Chief Military Prosecutor, in Ituri Province, for example, the cases of more than 2,000\ndetainees are being handled by a mere 10 judges.6"},{"id":"a-hrc-51-60-p0028","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"28","seq":30,"section":"1. Context","text":"Many judges assigned to certain parts of the country are unable to report to their place\nof assignment because of a lack of infrastructure, housing or means of travel, or even, in\nsome places, the absence of a courthouse. The team of international experts notes that this\nsituation exacerbates the difficulties faced by the general public in gaining access to justice.\nThe Ministry of Justice is considering granting so-called “bush bonuses” to judges who are\nforced to leave their families behind upon relocation from their usual place of residence. A\njudicial infrastructure development programme is being implemented with the support of the\nEuropean Union to mitigate this problem."},{"id":"a-hrc-51-60-p0029","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"29","seq":31,"section":"1. Context","text":"Measures such as those described above, as well as measures to protect judges and\ntheir workplaces in the current extremely volatile security context, must be supported and\nsignificantly strengthened."},{"id":"a-hrc-51-60-p0030","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"30","seq":32,"section":"1. Context","text":"The team of international experts notes a correlation between the absence of the\njudicial system and the State, on the one hand, and the proliferation of armed groups and\nincreased violence, on the other."},{"id":"a-hrc-51-60-p0031","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"31","seq":33,"section":"1. Context","text":"Civilian judges interviewed by the team of international experts in Bukavu, in South\nKivu Province, explained that, owing to the difficulties of working in the current security\ncontext, no cases of crimes against humanity had been referred to the Court of Appeal.7 Such\ncrimes were brought before the military courts because military judges enjoyed army\nprotection when travelling and were considered to be more efficient, to the extent that even\nsimple cases related to the payment of rent were referred to them. The judges also complained\nof the absence of the State outside of urban centres. According to them, most cases of human\nrights violations were documented only by non-governmental organizations (NGOs) and the\nUnited Nations Joint Human Rights Office."},{"id":"a-hrc-51-60-p0032","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"32","seq":34,"section":"1. Context","text":"Representatives of civil society in Bukavu echoed these judges’ concerns, pointing\nout that insecurity is an obstacle to legal proceedings."},{"id":"a-hrc-51-60-p0033","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"33","seq":35,"section":"1. Context","text":"The team of international experts notes that not a single new judge has been recruited\nfor over 11 years. According to the Chief Military Prosecutor at the Military High Court,\nthere are currently 214 military prosecutors and 114 military court judges.8 The recruitment\nof 500 new military judges envisaged within the framework of the ongoing recruitment of\n2,000 judges by the Ministry of Justice will double the capacity of the military justice system."},{"id":"a-hrc-51-60-p0034","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"34","seq":36,"section":"1. Context","text":"Moreover, the reinstatement of judges who had been unfairly removed from office\nwill reinforce the impact of the planned recruitment drive. The implementation of these two\nmeasures should help to alleviate problems associated with the lack of human resources."},{"id":"a-hrc-51-60-p0035","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"35","seq":37,"section":"1. Context","text":"The team of international experts welcomed these measures and encouraged the\nGovernment to take due account of the need to increase the number of female judges through\nthe planned recruitment process; this would facilitate, inter alia, the processing of the many\ncases of sexual violence regularly recorded in the country’s provinces."},{"id":"a-hrc-51-60-p0036","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"36","seq":38,"section":"1. Context","text":"Moreover, this mass recruitment drive must be accompanied by adequate and\nsustained initial training in order to ensure the required level of professional competence,\nwithout which it would be ineffective."},{"id":"a-hrc-51-60-p0037","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"37","seq":39,"section":"1. Context","text":"However, it is important to emphasize that the operation of the judicial system\ndepends primarily on support from the international partners of the Democratic Republic of\nthe Congo. The team of international experts is of the view that a significant increase in the\nportion of the national budget set aside for the administration of justice is essential to ensure\nthe sustainability of efforts to rehabilitate the judicial system.\n(b)        Administration of justice in provinces where a state of siege has been declared"},{"id":"a-hrc-51-60-p0038","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"38","seq":40,"section":"1. Context","text":"The team of international experts notes that the security situation is clearly a major\nobstacle to combating impunity, particularly in the east of the country, where human rights\nviolations are frequent."},{"id":"a-hrc-51-60-p0039","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"39","seq":41,"section":"1. Context","text":"Article 6 of Order No. 21/016 of 3 May 2021 provides that, for the duration of the\nstate of siege, the criminal law jurisdiction normally vested in the civilian courts is transferred\nto the military courts. However, given the influx of civilian cases referred to the already\noverburdened military courts, Order No. 22/024 of 18 March 2022 restricted the jurisdiction\nof the military courts to a limited number of criminal offences, while at the same time re-\nestablishing the regular jurisdiction of the civilian courts."},{"id":"a-hrc-51-60-p0040","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"40","seq":42,"section":"1. Context","text":"The team of international experts is of the view that the presence of the military justice\nsystem needs to be strengthened significantly in the provinces that are under a state of siege,\nwhere the military courts are struggling to cope with the increasingly heavy burden of\neradicating armed groups, protecting the civilian population and strengthening discipline in\nthe army."},{"id":"a-hrc-51-60-p0041","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"41","seq":43,"section":"2. Follow-up to judicial cases","text":"The team of international experts used each of its four visits to follow up on the\njudicial cases opened in the wake of the Kamuina Nsapu militia crisis. It remains concerned,\nhowever, about the slow pace of the implementation of the recommendations made in its\nprevious reports10 regarding the fight against impunity."},{"id":"a-hrc-51-60-p0042","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"42","seq":44,"section":"2. Follow-up to judicial cases","text":"The team of international experts notes that of the 16 priority cases identified since\n2019, only one, the Mulombodi case, has reached the stage of completion of preliminary\n8  Interview with the Chief Military Prosecutor on 3 December 2021, during the first visit of the team of\ninternational experts.\n9 A/HRC/48/82.\n10 A/HRC/41/31, A/HRC/45/50 and A/HRC/48/82.\nproceedings and referral to the Military High Court for trial. The team notes that, in this case,\nas well as in the Nganza and Tshisuku cases, the accused generals are protected by immunity.\nThe team of international experts supports the requests for waiver of immunity made by the\nOffice of the Chief Military Prosecutor and hopes that these requests will be looked upon\nfavourably, so that the process of military justice can overcome the obstacle of impunity."},{"id":"a-hrc-51-60-p0043","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"43","seq":45,"section":"2. Follow-up to judicial cases","text":"The team of international experts is disappointed that the case of the women enslaved\nby the Bana Mura militia, which was raised many years ago, remains unresolved."},{"id":"a-hrc-51-60-p0044","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"44","seq":46,"section":"2. Follow-up to judicial cases","text":"The team of international experts welcomes the fact that the case of the murder of\nZaida Catalán and Michael Sharp, members of the Group of Experts on the Democratic\nRepublic of the Congo, which was attached to a committee of the Security Council, has\nfinally come to trial. Death sentences were handed down to the perpetrators and their\naccomplices, which triggered an automatic appeal by the military prosecution service. The\nteam of international experts hopes that the Military High Court will sit within a reasonable\ntime to rule on the appeal filed by the Office of the Chief Military Prosecutor and the\ndefendants against the ruling of the Kananga Military Court. It notes with concern that the\ncase of the victims’ four Congolese colleagues is still pending."},{"id":"a-hrc-51-60-p0045","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"45","seq":47,"section":"2. Follow-up to judicial cases","text":"The team of international experts welcomes the ruling handed down on the appeal\nfiled by the Military High Court in the case of the murder of Floribert Chebeya Bahizire and\nFidèle Bazana Edadi. It notes that the defendants have been ordered to pay damages to the\nwidows and orphans of the two victims in solidum with the Democratic Republic of the\nCongo. The team urges the Democratic Republic of the Congo to ensure the prompt execution\nof this ruling."},{"id":"a-hrc-51-60-p0046","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"46","seq":48,"section":"2. Follow-up to judicial cases","text":"The team of international experts welcomes the continued forensic support provided\nto the Congolese justice system by the technical assistance team deployed by OHCHR.\n(b)     National prosecution strategy"},{"id":"a-hrc-51-60-p0047","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"47","seq":49,"section":"2. Follow-up to judicial cases","text":"The team of international experts welcomes the development by the Democratic\nRepublic of the Congo of a national strategy for targeted prosecutions that will optimize the\nuse of available resources on a province-by-province basis and pave the way for transitional\njustice."},{"id":"a-hrc-51-60-p0048","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"48","seq":50,"section":"3. Situation of victims","text":"The team of international experts notes that the lack of justice leads to a feeling of\nabandonment and a loss of trust in the judicial system among victims. As a result, some\nvictims’ associations and NGOs, such as Dr. Denis Mukwege’s Panzi Foundation, have\ncalled for the establishment of an international court with jurisdiction over the Democratic\nRepublic of the Congo or of hybrid courts. In addition, the Grand Kasai victims’ association\nhas filed a complaint with the International Criminal Court against former President Joseph\nKabila and certain political and military officials, including generals."},{"id":"a-hrc-51-60-p0049","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"49","seq":51,"section":"3. Situation of victims","text":"The team of international experts maintains that justice for the Congolese people can\nbe achieved in the Democratic Republic of the Congo by Congolese judges, provided that\nadequate resources are made available to them. The military courts and tribunals, which hear\nmost cases involving serious crimes, crimes against humanity and war crimes, have the\nprofessional tools they need to carry out their mandates effectively."},{"id":"a-hrc-51-60-p0050","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"50","seq":52,"section":"3. Situation of victims","text":"The need to urgently provide the justice system with sufficient means to accomplish\nits mission is imperative in the current context of war in the east of the country, with human\nrights violations on the rise and victims still awaiting the implementation of the conclusions\nof the report on the mapping exercise. The absence of the State is detrimental to this situation\nand is particularly noticeable in the context of the gradual disengagement of MONUSCO.\n(b)         Victims’ concerns"},{"id":"a-hrc-51-60-p0051","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"51","seq":53,"section":"3. Situation of victims","text":"The team of international experts notes that the Grand Kasai victims’ association\noccasionally organizes public demonstrations to demand justice for victims and the\nprosecution of alleged perpetrators of serious human rights violations."},{"id":"a-hrc-51-60-p0052","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"52","seq":54,"section":"B. Reconciliation and implementation of the transitional justice process","text":"In its previous report, the team of international experts commended the considerable\nprogress made in the field of transitional justice in Kasai Central Province thanks to the\nimplementation of the peace, justice, reconciliation and reconstruction project and the\nspontaneous surrender project in Kasai and Tanganyika. It urged the Government of the\nDemocratic Republic of the Congo and its development partners to support the effective\nimplementation of the Commission on Truth, Justice and Reconciliation of Kasai Central\nProvince in accordance with international standards and called for the mobilization of the\nresources necessary for it to operate.11"},{"id":"a-hrc-51-60-p0053","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"53","seq":55,"section":"B. Reconciliation and implementation of the transitional justice process","text":"Despite support from Belgium and the United Nations Peacebuilding Fund in funding\nthe transitional justice process throughout the country, as well as technical support from the\nUnited Nations Joint Human Rights Office, the funding gap at the provincial level remains a\nconcern. The team of international experts is concerned about the lack of donor interest in\nfunding the transitional justice process in Kasai and the lack of interest that the provincial\nauthorities have shown in the operation of the provincial Commission on Truth, Justice and\nReconciliation, which has been allocated a paltry budget of only $500. This situation is\nexacerbated by the closure of the peace, justice, reconciliation and reconstruction project in\nApril 2022."},{"id":"a-hrc-51-60-p0054","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"54","seq":56,"section":"B. Reconciliation and implementation of the transitional justice process","text":"Regarding efforts to facilitate the work of the provincial Commission on Truth, Justice\nand Reconciliation, the team of international experts welcomes the steps taken by the newly\nelected provincial authorities with the support of the United Nations Joint Human Rights\nOffice. These steps include the designation of the Commission’s headquarters, the\ndevelopment of a road map for its effective establishment in Kasai Central, the development\nof a code on the organization and functioning of the joint committee in charge of selecting\ncommissioners,12 and the order of the provincial minister of 17 December 2021 appointing\nthe members of the joint committee in charge of selecting candidate commissioners. In\naddition, the team of international experts welcomes the confirmation, by order of the new\nprovincial executive, of the appointment of the elected commissioners to lead the\nCommission in Kasai Central Province and the authorities’ willingness to ensure that\nadequate funding is provided."},{"id":"a-hrc-51-60-p0055","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"55","seq":57,"section":"B. Reconciliation and implementation of the transitional justice process","text":"The team of international experts emphasizes the need to train the elected\ncommissioners and their staff in the areas of transitional justice, human rights and\ninternational humanitarian law, and suggests that they also receive initial training on their\nmandate."},{"id":"a-hrc-51-60-p0056","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"56","seq":58,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts notes that two structures have been established at\nthe national level, namely the Joint Steering Commission on Transitional Justice and the\nDisarmament, Demobilization, Community Recovery and Stabilization Programme.\nStructures for implementing the transitional justice process"},{"id":"a-hrc-51-60-p0057","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"57","seq":59,"section":"2. Implementation of the transitional justice process at the national level","text":"With regard to the Joint Steering Commission on Transitional Justice, the team of\ninternational experts commends the Congolese Government’s initiative to establish, with the\n11   A/HRC/48/82, paras. 50, 51 and 55.\n12   The code was developed in November 2021 with the support of the United Nations Joint Human\nRights Office, OHCHR and the team of international experts.\nsupport of the United Nations Joint Human Rights Office, a framework for reflection that\ninvolves all key institutions and actors in order to consider different forms of transitional\njustice and develop a national policy in that regard. The team of international experts is also\npleased that this discussion platform, which was launched by the Office of the President and\nis coordinated by the Ministry of Human Rights and the Ministry of Justice, has been able to\nbring together other important bodies, such as the National Human Rights Commission, the\nNational Assembly’s Standing Committee on Human Rights, civil society and the United\nNations Joint Human Rights Office."},{"id":"a-hrc-51-60-p0058","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"58","seq":60,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts also welcomes the development by the Joint Steering\nCommission on Transitional Justice of a specific road map identifying activities to be carried\nout, specific objectives and results to be achieved and an implementation strategy. It notes\nthat the activities planned with a view to initiating the transitional justice process at the\nnational level have been entrusted to specialized subcommissions, namely the\nSubcommission on Truth and the Subcommission on Reparations, which are led by the\nMinistry of Human Rights, and the Subcommission on Justice and the Subcommission on\nGuarantees of Non-Recurrence, which are led by the Ministry of Justice."},{"id":"a-hrc-51-60-p0059","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"59","seq":61,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts was invited by the Ministry of Human Rights to\nparticipate in the opening ceremony of the public consultations held in March 2022 in\nKalemie, Tanganyika Province. Four provinces are concerned in the initial phase of these\nconsultations, namely North Kivu (Goma), Kasai (Tshikapa), Kongo Central (Matadi) and\nTanganyika."},{"id":"a-hrc-51-60-p0060","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"60","seq":62,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts invites the Congolese authorities to carry out more\nnational and subregional initiatives to promote a return to peace in conflict zones and to allow\ncommunities that have expressed a desire to resort to transitional justice mechanisms to\nexpress their needs in terms of truth, reparations, justice and reform through public\nconsultations."},{"id":"a-hrc-51-60-p0061","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"61","seq":63,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts also notes the Government’s efforts to promote\npeace and restore the authority of the State through the implementation of the Disarmament,\nDemobilization, Community Recovery and Stabilization Programme. The development and\nadoption of the national implementation strategy for the Programme places emphasis on an\ninclusive community-based approach and on transitional justice as mechanisms for conflict\nresolution, reconciliation and reparation."},{"id":"a-hrc-51-60-p0062","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"62","seq":64,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts notes with concern that the Programme’s\noperationalization has been delayed and that it is limited to low-impact outreach activities\ndespite the current security context, which is marked by renewed clashes between M23 and\nthe Armed Forces of the Democratic Republic of the Congo in the country’s eastern\nprovinces. The team of international experts therefore urges the authorities of the Democratic\nRepublic of the Congo to expedite the effective implementation of the Disarmament,\nDemobilization, Community Recovery and Stabilization Programme and encourages the\ncountry’s partners, in particular MONUSCO, to develop transitional initiatives to hasten the\nProgramme’s implementation.\n3.     Challenges in the implementation of the transitional justice process in the Democratic\nRepublic of the Congo"},{"id":"a-hrc-51-60-p0063","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"63","seq":65,"section":"2. Implementation of the transitional justice process at the national level","text":"The various trips made by the team of international experts to the provinces of North\nKivu, South Kivu, Tanganyika, Ituri and Haut-Katanga have allowed it to identify challenges\nin the implementation of the transitional justice process in the Democratic Republic of the\nCongo. These challenges include: coordination of and adequate communication between the\ndifferent processes under way within the general transitional justice framework, and their\nharmonious implementation; funding of the transitional justice process; consideration of the\ncross-border dimension of conflicts; the question of reparations; and the difficulty of applying\ntransitional justice in a context of insecurity and inter-community conflicts.\n(a)    Coordination of and adequate communication between the different processes under way\nwithin the general transitional justice framework, and their harmonious implementation"},{"id":"a-hrc-51-60-p0064","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"64","seq":66,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts welcomes the Government’s transitional justice\ninitiatives. However, it remains concerned about the coordination, articulation and funding\nof these initiatives, as well as the communication between the persons running them. During\na workshop with the coordinator of the Disarmament, Demobilization, Community Recovery\nand Stabilization Programme on 16 March 2022, the team identified a need for more effective\ncoordination between the various institutions responsible for transitional justice."},{"id":"a-hrc-51-60-p0065","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"65","seq":67,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts found that the only forum for consultation between\nthe Disarmament, Demobilization, Community Recovery and Stabilization Programme and\nthe Ministry of Human Rights is the steering committee, which is a managerial body attached\nspecifically to the Disarmament, Demobilization, Community Recovery and Stabilization\nProgramme and which the Minister of Human Rights or his representative attends as an\nobserver. As a result, there is a risk of overlapping activities, a lack of coherence between\nactivities and confusion among the general public with regard to the roles and responsibilities\nof the various actors."},{"id":"a-hrc-51-60-p0066","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"66","seq":68,"section":"2. Implementation of the transitional justice process at the national level","text":"During a meeting between the team of international experts and the Joint Steering\nCommission on Transitional Justice, the members of the Commission complained about the\nabsence of an appropriate legal framework and the lack of independent funding for its\nactivities. Moreover, from a methodological standpoint, the work of the Commission was\nsuspended pending the results of the public consultations, whereas an evaluation of the\ninitiatives that had already taken place in the country, including the work done prior to the\nconsultations, could have been undertaken in parallel.\n(b)    Funding of the transitional justice process"},{"id":"a-hrc-51-60-p0067","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"67","seq":69,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts is concerned that the transitional justice process is\nlargely dependent on external funding. It strongly emphasizes the need for national funding,\nwhich is the only way to ensure credibility, coherence and sustainability.\n(c)   Consideration of the cross-border dimension of conflicts"},{"id":"a-hrc-51-60-p0068","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"68","seq":70,"section":"2. Implementation of the transitional justice process at the national level","text":"The cross-border aspect of current conflicts and the need to take these aspects into\naccount in the transitional justice process in the Democratic Republic of the Congo were\npreviously illustrated by the report on the mapping exercise and are currently reflected in the\nNairobi process. The various field visits that the team of international experts made,\nparticularly to the provinces of North Kivu, South Kivu and Ituri, helped it to come to a better\nunderstanding of the dynamics of the conflicts, in which the parties are located on both sides\nof the borders of the Democratic Republic of the Congo."},{"id":"a-hrc-51-60-p0069","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"69","seq":71,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts learned from various interlocutors that the growing\nthreat represented by armed groups is the result of competition for the country’s agricultural,\npastoral, mining and land resources, its porous borders and a lack of State authority, and that\nthese armed groups are proliferating, often in collusion with foreign armed groups linked to\nnational or international interest groups in neighbouring countries or further afield."},{"id":"a-hrc-51-60-p0070","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"70","seq":72,"section":"2. Implementation of the transitional justice process at the national level","text":"In addition, other factors, such as the disintegration of the social fabric, the declining\ninfluence of traditional authorities, the greed of professional or opportunistic businessmen,\nboth national and foreign, and the general impoverishment of the population, contribute to\nthe proliferation of all sorts of actors in the Democratic Republic of the Congo.\n(d)    The question of reparations"},{"id":"a-hrc-51-60-p0071","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"71","seq":73,"section":"2. Implementation of the transitional justice process at the national level","text":"The workshop on transitional justice allowed the team of international experts to better\nunderstand the challenges faced by victims in terms of reparation. The right to reparation for\nvictims is primarily addressed at the judicial level, particularly by the military courts.\nHowever, for the military courts, the issue of reparation is an accessory one, especially since\nit cannot be raised by victims in the context of direct summons proceedings. Moreover, a\ntendency to grant victims uniform reparation for harm caused, without individualization, has\nbeen observed. This standardization reduces reparations to the level of compensation. Lastly,\nin most cases, in the event of a conviction, payment of compensation is significantly delayed,\nand is sometimes hampered by the insolvency of the perpetrators. 13"},{"id":"a-hrc-51-60-p0072","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"72","seq":74,"section":"2. Implementation of the transitional justice process at the national level","text":"In a judgment of 9 February 2022, the International Court of Justice, to which the\nDemocratic Republic of the Congo had filed a complaint against Rwanda and Uganda after\ntheir armies clashed in Kisangani from 5 to 10 June 2000, causing numerous casualties and\nsignificant material damage, ordered Uganda to pay $325 million in reparations to the\nDemocratic Republic of the Congo.14 The question of the shares of this sum to be distributed\nto individual victims remains to be clarified.15"},{"id":"a-hrc-51-60-p0073","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"73","seq":75,"section":"2. Implementation of the transitional justice process at the national level","text":"With regard to non-judicial reparations, it is important to note that collective\nreparations are not the most appropriate means of addressing the multiple harms suffered by\nvictims of mass crimes."},{"id":"a-hrc-51-60-p0074","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"74","seq":76,"section":"2. Implementation of the transitional justice process at the national level","text":"In contrast, the Panzi Foundation and the Global Survivors Fund have adopted a\ncomprehensive approach to non-judicial reparations for victims by combining clinical\nmeasures, psychotherapeutic methods and social reintegration."},{"id":"a-hrc-51-60-p0075","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"75","seq":77,"section":"2. Implementation of the transitional justice process at the national level","text":"Lastly, the prospect of a national reparations fund is taking shape in the form of a\nspecial bill, including a funding proposal, to develop and implement a national reparations\npolicy."},{"id":"a-hrc-51-60-p0076","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"76","seq":78,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts hopes that the discussion concerning this bill will\ntake due account, on the one hand, of the uniqueness of the problems posed by the question\nof providing reparations for the harm suffered by the millions of victims of the\nmultigenerational and multidimensional conflicts that have ravaged the Democratic Republic\nof the Congo in the absence of a strong State and, on the other hand, of the meagre results\nobtained so far through the international courts. The involvement of women, traditional\nleaders and researchers specializing in the history and social and cultural anthropology of the\nDemocratic Republic of the Congo will enhance the effectiveness of the process and the real\nimpact of transitional justice.\n(e)        Difficulty of applying transitional justice in a context of insecurity and inter-community\nconflicts"},{"id":"a-hrc-51-60-p0077","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"77","seq":79,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts notes that the transitional justice process is taking\nplace in a country where part of the territory is in a post-conflict situation, while in the other\nparts insecurity, violence and conflict not only continue but seem far from abating. Owing to\nthis situation, the transitional justice process in the Democratic Republic of the Congo must\ndepart from existing models and take a pragmatic approach that accommodates the diversity\nof local circumstances and the needs of the population."},{"id":"a-hrc-51-60-p0078","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"78","seq":80,"section":"2. Implementation of the transitional justice process at the national level","text":"The discussions that the team of international experts held with the authorities and\nrepresentatives of the populations of the provinces of North Kivu, South Kivu, Tanganyika\nand Ituri revealed the importance of acting without waiting for the conflicts to end. These\ndiscussions made clear the urgency of taking immediate steps towards transitional justice to\ncurb the spread of current conflicts, to stifle hate speech and calls for violence and\ndiscrimination, to develop a strategy of targeted prosecutions and to seize opportunities for\ndisarming combatants and resolving conflicts before the chance to do so is lost. An analysis\nof the causes of these conflicts is essential in order to shape the contours of sustainable\nsolutions. Immediate solutions are required, in view of the ever-increasing number of victims\nliving in untenably precarious and vulnerable situations."},{"id":"a-hrc-51-60-p0079","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"79","seq":81,"section":"2. Implementation of the transitional justice process at the national level","text":"The other essential dimension of transitional justice is the identification of the causes\nof the conflicts, the study of their impact and the analysis of the prospects for resolution\nbeyond the country’s borders, given the presence of the same communities on both sides of\nthe borders and the involvement of many neighbouring countries in the ongoing conflicts."},{"id":"a-hrc-51-60-p0080","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"80","seq":82,"section":"2. Implementation of the transitional justice process at the national level","text":"Accordingly, the team of international experts organized a workshop on transitional\njustice with the Ministry of Human Rights and the United Nations Joint Human Rights Office\nfrom 19 to 21 July 2022 to take stock of the situation and study options for developing a\nnational policy."},{"id":"a-hrc-51-60-p0081","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"81","seq":83,"section":"2. Implementation of the transitional justice process at the national level","text":"This workshop brought together members of parliament, senators, representatives of\nthe Office of the President and of the various ministries concerned, the diplomatic\ncommunity, academic figures and civil society."},{"id":"a-hrc-51-60-p0082","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"82","seq":84,"section":"2. Implementation of the transitional justice process at the national level","text":"The objective of the workshop was to facilitate the articulation, conceptualization and\ncoordination of different elements of the transitional justice policy and to work on the\ncommunication campaign that would accompany it. The following topics were discussed:\n• Consultations initiated within the framework of the transitional justice process in the\nDemocratic Republic of the Congo\n• Evaluation of Congolese criminal policy in the context of transitional justice\n• Lessons learned from the decentralized model in Kasai Central\n• Harmonization of the National Disarmament, Demobilization, Community Recovery\nand Stabilization Programme\n• Links and coordination between disarmament, demobilization and reintegration\nactivities and transitional justice\n• Strategy for harmonizing current transitional justice initiatives\n• Transitional justice in the context of justice reform\n• Forms and modalities of the victims’ right to reparation\n• Adopting a victim-centred approach in the development of a transitional justice\nstrategy\n• Transitional justice funding mechanisms\n• Reforms with a view to the non-repetition of past crimes\n• Use of forensics in the transitional justice process"},{"id":"a-hrc-51-60-p0083","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"83","seq":85,"section":"2. Implementation of the transitional justice process at the national level","text":"At the end of the workshop, the participants recommended that an expanded scientific\ncommittee be set up to draft a discussion paper on the national transitional justice policy in\nthe Democratic Republic of the Congo with a view to facilitating the development of a road\nmap that will ensure the policy’s smooth implementation."},{"id":"a-hrc-51-60-p0084","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"84","seq":86,"section":"A. Conclusions","text":"The team of international experts would not have been able to play its role in\nassessing, supporting and assisting the Democratic Republic of the Congo without the\nfull cooperation, goodwill and availability of the Congolese Government, for which it\nexpresses its thanks."},{"id":"a-hrc-51-60-p0085","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"85","seq":87,"section":"A. Conclusions","text":"In addition, the trust, openness and willingness to engage in dialogue shown by\nthe Congolese people, their traditional and religious leaders, civil society and the\ninternational community in Kinshasa, as well as the continuous support of the United\nNations Joint Human Rights Office and MONUSCO, allowed the team of international\nexperts to grasp the complexity and nuances of the situation in the Democratic Republic\nof the Congo and to use this experience to develop its recommendations."},{"id":"a-hrc-51-60-p0086","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"86","seq":88,"section":"A. Conclusions","text":"Early in the reporting period, progress in Kasai confirmed the wisdom of the\nGovernment’s decision to pursue a transitional justice process that is province-based,\ncentrally coordinated and supported by the United Nations and the international\ncommunity. In this context, public consultations were launched, a structure for\ncoordinating the various aspects of transitional justice was set up under the auspices of\nthe Office of the President and leadership of the Ministry of Human Rights, and a\nprocess of disarmament and reintegration was initiated along with a strategy of\ntargeted prosecutions."},{"id":"a-hrc-51-60-p0087","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"87","seq":89,"section":"A. Conclusions","text":"Recent attacks by M23 have highlighted the challenge posed by the long tradition\nof impunity in the Democratic Republic of the Congo, particularly for the crimes\ndocumented in the report on the mapping exercise, the centrality of the cross-border\nnature of the ongoing conflicts and insecurity, and, through the Nairobi process, the\nneed to involve the subregion in the search for lasting solutions, including the\nidentification of the root causes of the conflicts and the prevention of their recurrence,\nas well as in the transitional justice process as a whole."},{"id":"a-hrc-51-60-p0088","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"88","seq":90,"section":"A. Conclusions","text":"The current challenges are compounded by the structural weaknesses of the\nDemocratic Republic of the Congo. This general weakness extends to its administrative\nand judicial structures, the lack of a State presence and State authority over an\nimmense territory, which has a direct impact on the rule of law, and the wholly\ninadequate operation and funding of State institutions, which fail to meet the needs of\na population exposed to various forms of vulnerability and exploitation."},{"id":"a-hrc-51-60-p0089","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"89","seq":91,"section":"A. Conclusions","text":"Protecting the population will require a sustained effort to rebuild the State,\nwhich must go hand in hand with the implementation of transitional justice and the\nfight against impunity."},{"id":"a-hrc-51-60-p0090","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"90","seq":92,"section":"B. Recommendations","text":"While reiterating the need to pursue the implementation of the recommendations\nmade in its previous reports,16 the team of international experts makes the following\nadditional recommendations."},{"id":"a-hrc-51-60-p0091","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"91","seq":93,"section":"1. Conceptualization, articulation and communication strategy with regard to the","text":"With a view to improving the visibility of the Government’s efforts, promoting\ncommunication about them and fostering ownership of the transitional justice policy by\nthe population, the team of international experts stresses the importance of promptly\nadopting an appropriate communication policy on the implementation of transitional\njustice and recommends that the Government give priority to the development of such\na policy."},{"id":"a-hrc-51-60-p0092","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"92","seq":94,"section":"1. Conceptualization, articulation and communication strategy with regard to the","text":"The team of international experts recommends the prompt and efficient\nestablishment of an expanded scientific committee, as recommended by the participants\nin the workshop on transitional justice held in Kinshasa from 19 to 21 July 2022."},{"id":"a-hrc-51-60-p0093","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"93","seq":95,"section":"2. Prevention of impunity","text":"The team of international experts encourages the Government to continue\ndeveloping a policy of targeted prosecutions, province by province, as was done in Kasai\nin the context of the Kamuina Nsapu militia crisis, including in respect of the crimes\nand human rights violations documented in the report on the mapping exercise."},{"id":"a-hrc-51-60-p0094","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"94","seq":96,"section":"2. Prevention of impunity","text":"The team of international experts recommends that the Government establish a\ncentralized biometric identification system as part of the process of disarming and\ndemobilizing combatants to allow for systematic background checks, which will be\nparticularly pertinent in the context of security sector reform, the conduct of\nprosecutions and the establishment of a nationwide civil administrative system."},{"id":"a-hrc-51-60-p0095","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"95","seq":97,"section":"2. Prevention of impunity","text":"The team of international experts supports the Chief Military Prosecutor’s\nrequests for the waiver of army generals’ immunity, as well as the Congolese\nGovernment’s review of current policies on amnesty, immunity and integration of\nformer combatants (mixage and brassage), which constitute significant obstacles to\nending impunity."},{"id":"a-hrc-51-60-p0096","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"96","seq":98,"section":"2. Prevention of impunity","text":"The team of international experts recommends that the Human Rights Council\ncontinue the deployment and strengthen the capacities of the forensic technical\nassistance team by increasing the size of the team and providing it with additional\nresources, including effective tools for collecting evidence to facilitate justice and\nmemory work."},{"id":"a-hrc-51-60-p0097","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"97","seq":99,"section":"3. Consideration of victims at all stages of the process","text":"The team of international experts welcomes the Government’s decision to\nprepare a bill on a policy of reparations for victims and recommends that victims’ needs\nfor protection, immediate and other assistance, and reparation be taken into\nconsideration at all stages of the transitional justice process."},{"id":"a-hrc-51-60-p0098","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"98","seq":100,"section":"4. Conflict prevention and guarantees of non-repetition","text":"The team of international experts urges the legislature to promptly adopt and\ngive effect to the bill on the nationwide prevention and punishment of hate speech and\nof calls for violence and discrimination."},{"id":"a-hrc-51-60-p0099","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"99","seq":101,"section":"4. Conflict prevention and guarantees of non-repetition","text":"The team of international experts recommends that the Government prioritize\nthe analysis of the current conflicts and the use of factual history to help dispel the\nmyths that continue to fuel discrimination and conflict in the Democratic Republic of\nthe Congo."},{"id":"a-hrc-51-60-p0100","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"100","seq":102,"section":"4. Conflict prevention and guarantees of non-repetition","text":"The team of international experts encourages the Government to look into the\nreasons for the failure of previous reconciliation and peace negotiations and strategies,\nincluding the Addis Ababa Agreement, the Great Lakes Pact and the Nairobi process,\nand to take due account of the lessons learned from them when implementing the\ncurrent transitional justice process."},{"id":"a-hrc-51-60-p0101","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"101","seq":103,"section":"4. Conflict prevention and guarantees of non-repetition","text":"The team of international experts recommends that the Government develop a\nplan for administrative reform to complement the current security and judicial sector\nreform programmes. The three reform programmes should be implemented together\nso as to be mutually reinforcing."},{"id":"a-hrc-51-60-p0102","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"102","seq":104,"section":"4. Conflict prevention and guarantees of non-repetition","text":"The team of international experts encourages the Government to establish an\nappropriate, high-quality training programme for its senior officials, taking into\naccount the gradual withdrawal of MONUSCO and the need to ensure the\nsustainability of the planned reforms."},{"id":"a-hrc-51-60-p0103","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"103","seq":105,"section":"4. Conflict prevention and guarantees of non-repetition","text":"The team of international experts welcomes the recognition by the Nairobi\nprocess of the cross-border nature of the ongoing conflicts and insecurity and\nrecommends that the subregion become more closely involved in identifying the causes\nof conflicts and preventing their recurrence, and that it strengthen the transitional\njustice aspect of its work, rather than limiting itself to the political and military aspects."},{"id":"a-hrc-51-60-p0104","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"104","seq":106,"section":"5. Public, private and international funding of the transitional justice process","text":"The team of international experts notes with regret the inadequacy of the\nresources made available to the transitional justice process in the Kasai region and\nstresses the need for sufficient and sustainable funding for all aspects of transitional\njustice and State reform as a prerequisite for their success."},{"id":"a-hrc-51-60-p0105","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"105","seq":107,"section":"5. Public, private and international funding of the transitional justice process","text":"The team of international experts urges the Government to redouble its efforts\nto ensure that its transitional justice and State reform initiatives are funded from the\nnational budget at both the provincial and central levels. Such financial efforts will\nreinforce the political will reiterated by the Government, ensure the immediacy and\nsustainability of transitional justice projects, and encourage increased bilateral and\nmultilateral cooperation in their funding."},{"id":"a-hrc-51-60-p0106","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"106","seq":108,"section":"5. Public, private and international funding of the transitional justice process","text":"In addition, given the considerable level of funding required for the\nimplementation of transitional justice, the team of international experts recommends\nthat the Government develop a policy that would organize the contributions of national\nand multinational companies operating in the Democratic Republic of the Congo to the\nfunding of peace, reconciliation, stability and sustainable development initiatives."},{"id":"a-hrc-54-76-u0000","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":null,"seq":0,"section":null,"text":"Nations Unies                                                                                      A/HRC/54/76\nAssemblée générale                                                           Distr. générale\n10 août 2023","unnumbered":true},{"id":"a-hrc-54-76-u0001","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":null,"seq":1,"section":null,"text":"Résumé\nDans sa résolution 51/36 du 7 octobre 2022, le Conseil des droits de l’homme a\nrenouvelé le mandat de l’Équipe d’experts internationaux en République démocratique du\nCongo et lui a demandé d’apporter l’appui technique nécessaire au Gouvernement dans la\nmise en œuvre de la stratégie nationale de justice transitionnelle. Le Conseil a demandé en\noutre à l’Équipe d’experts internationaux de lui présenter son rapport final à sa\ncinquante-quatrième session, dans le cadre d’un dialogue interactif renforcé, ainsi qu’une\nmise à jour orale à sa cinquante-deuxième session.\nL’exécution de ce mandat élargi intervient dans un contexte de retrait progressif de la\nMission de l’Organisation des Nations Unies pour la stabilisation en République\ndémocratique du Congo, d’aggravation de la situation sécuritaire et de préparation\nd’échéances électorales.\nDans le cadre de son mandat élargi, l’Équipe d’experts internationaux a effectué\nquatre visites de terrain et organisé, avec le Ministère des droits humains et le Bureau\nconjoint des Nations Unies pour les droits de l’homme en République démocratique du\nCongo, deux ateliers : l’un sur l’évaluation de la mise en œuvre des différentes\nrecommandations issues de ses rapports antérieurs, et l’autre sur l’écriture du plan d’action\nstratégique du Ministère des droits humains en matière de justice transitionnelle. Elle a\nparticipé à Kananga à l’atelier de validation des textes de fonctionnement de la Commission\nprovinciale vérité, justice et réconciliation au Kasaï-Central et à la signature d’un protocole\nd’accord entre la Commission et le Bureau conjoint, qui ont été suivis du lancement officiel\ndes activités de la Commission.","unnumbered":true},{"id":"a-hrc-54-76-u0002","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":null,"seq":2,"section":null,"text":"L’exacerbation des attaques du M23 et la facilitation de la Communauté d’Afrique de\nl’Est dans le cadre du processus de Nairobi ont souligné la nécessité de la prise en compte\ndes aspects transfrontaliers des conflits et de la justice transitionnelle.\nÀ cet effet, l’Équipe d’experts internationaux a tenu une réunion virtuelle avec\nl’Envoyé spécial du Secrétaire général pour la région des Grands Lacs, sur la prise en compte\nde la justice transitionnelle dans les initiatives sous-régionales de règlement des conflits en\nRépublique démocratique du Congo.\nL’Équipe d’experts internationaux a enfin proposé des conclusions et formulé des\nrecommandations en vue de renforcer les actions en cours et à venir.","unnumbered":true},{"id":"a-hrc-54-76-p0001","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"1","seq":3,"section":"I. Introduction","text":"Dans sa résolution 51/36 du 7 octobre 2022, le Conseil des droits de l’homme a\nrenouvelé le mandat de l’Équipe d’experts internationaux en République démocratique du\nCongo et lui a demandé d’apporter l’appui technique nécessaire au Gouvernement dans la\nmise en œuvre de la stratégie nationale sur la justice transitionnelle. Le Conseil a demandé\nen outre à l’Équipe d’experts internationaux de lui présenter son rapport final à sa\ncinquante-quatrième session, dans le cadre d’un dialogue interactif renforcé, ainsi qu’une\nmise à jour orale à sa cinquante-deuxième session. Le présent rapport s’inscrit dans\nl’exécution de la résolution susmentionnée."},{"id":"a-hrc-54-76-p0002","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"2","seq":4,"section":"I. Introduction","text":"Dans la même résolution, le Conseil des droits de l’homme a demandé au\nHaut-Commissaire des Nations Unies aux droits de l’homme de continuer à fournir au\nGouvernement de la République démocratique du Congo l’assistance technique, y compris\nl’expertise médico-légale nécessaire, pour appuyer les autorités judiciaires du pays dans leurs\nenquêtes sur les allégations de violations des droits de l’homme et d’atteintes à ces droits afin\nque leurs auteurs soient traduits en justice, et de renforcer l’équipe d’assistance technique\nd’experts médico-légaux supplémentaires en lui octroyant des moyens suffisants pour qu’elle\naide le Gouvernement à se doter de capacités nationales spécialisées dans le domaine de la\nmédecine légale."},{"id":"a-hrc-54-76-p0003","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"3","seq":5,"section":"I. Introduction","text":"Le Conseil des droits de l’homme a enfin demandé au Haut-Commissaire de mettre à\nla disposition du Gouvernement de la République démocratique du Congo plus d’experts en\njustice transitionnelle dont la mission serait d’apporter une assistance technique à la rédaction\nstratégique et à l’adoption d’outils méthodologiques nécessaires au fonctionnement du fonds\nde réparation et des commissions provinciales de vérité et réconciliation, conformément aux\nnormes et aux instruments internationaux."},{"id":"a-hrc-54-76-p0004","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"4","seq":6,"section":"I. Introduction","text":"Le 29 novembre 2022, le Haut-Commissaire des Nations Unies aux droits de l’homme\na nommé Bacre Waly Ndiaye (Sénégal) Président et Marie-Thérèse Keita-Bocoum\n(Côte d’Ivoire) membre de l’Équipe d’experts internationaux. Le 30 janvier 2023, le\nHaut-Commissaire a nommé Marie-Thérèse Keita-Bocoum Présidente de l’Équipe d’experts\ninternationaux en remplacement de Bacre Waly Ndiaye (élu membre du Comité des droits\nde l’homme) et, le 9 juin 2023, a nommé Bessolé René Bagoro (Burkina Faso) membre de\nl’Équipe d’experts internationaux."},{"id":"a-hrc-54-76-p0005","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"5","seq":7,"section":"I. Introduction","text":"L’Équipe d’experts internationaux est appuyée par un secrétariat composé d’un\ncoordonnateur et d’un fonctionnaire des droits de l’homme spécialiste de la justice\ntransitionnelle. En 2023, elle a effectué quatre visites de terrain en République démocratique\ndu Congo : du 14 au 27 janvier, du 14 au 29 mai, du 21 juin au 6 juillet et, enfin, du 20 juillet\nau 5 août."},{"id":"a-hrc-54-76-p0006","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"6","seq":8,"section":"I. Introduction","text":"À l’occasion de ces visites, l’Équipe d’experts internationaux a rencontré diverses\npersonnalités, notamment le Président de l’Assemblée nationale ; le Vice-Premier Ministre\net Ministre de la défense et des anciens combattants ; le Ministre d’État, Ministre de la justice\net Garde des sceaux ; la Directrice de cabinet adjointe du Président de la République chargée\ndes questions politiques, juridiques et diplomatiques ; le Ministre des droits humains ; le\nMinistre des communications et des médias, porte-parole du Gouvernement ; le Président de\nla Commission nationale des droits de l’homme ; le Président de la Commission des droits\nde l’homme de l’Assemblée nationale ; le Secrétaire permanent du Conseil supérieur de la\nmagistrature ; l’Auditeur général des Forces armées de la République démocratique du\nCongo ; le Coordonnateur national du Programme de désarmement, de démobilisation, de\nrelèvement communautaire et de stabilisation ; le Gouverneur de la province du\nKasaï-Central ; et des membres du corps diplomatique accrédités en République\ndémocratique du Congo, y compris les ambassadeurs du Groupe africain ainsi que les\nreprésentants de l’Union africaine et de l’Union européenne."},{"id":"a-hrc-54-76-p0007","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"7","seq":9,"section":"I. Introduction","text":"Au cours de sa première visite, l’Équipe d’experts internationaux a organisé à\nKinshasa, les 25 et 26 janvier 2023, un atelier d’évaluation de la mise en œuvre des\nrecommandations issues de ses rapports publiés depuis le début de son mandat, soit de 2018\nà 2022. Elle a ensuite participé à l’atelier de formation initiale des commissaires de la\nCommission provinciale vérité, justice et réconciliation au Kasaï-Central organisé par le\nBureau conjoint des Nations Unies pour les droits de l’homme en République démocratique\ndu Congo (BCNUDH) du 23 au 27 janvier 2023."},{"id":"a-hrc-54-76-p0008","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"8","seq":10,"section":"I. Introduction","text":"Lors de sa deuxième visite, l’Équipe d’experts internationaux s’est rendue à Kinshasa\net à Kananga, dans la province du Kasaï-Central. Au cours de la mission de terrain à Kananga,\nelle a relevé les difficultés et défis relatifs au démarrage effectif de la Commission provinciale\nvérité, justice et réconciliation au Kasaï-Central. À cet effet, elle a rencontré le Gouverneur\nde la province, l’Auditeur militaire supérieur de l’ancienne province du Kasaï-Occidental,\nl’Association des victimes du grand Kasaï, le Coordonnateur provincial de l’organisation non\ngouvernementale TRIAL International, les représentants des confessions religieuses, les\nchefs coutumiers, les représentants du système des Nations Unies ainsi que les commissaires\nde la Commission provinciale vérité, justice et réconciliation au Kasaï-Central. Avec ses\ninterlocuteurs, l’Équipe d’experts internationaux a échangé sur le niveau d’engagement des\nautorités provinciales dans le cadre du soutien à la Commission, l’appui que l’Équipe\nd’experts internationaux pourrait lui apporter ainsi que les stratégies de mobilisation des\nressources financières nécessaires. Elle s’est également informée des progrès réalisés dans\nles domaines de la lutte contre l’impunité et de la mise en œuvre de la justice transitionnelle."},{"id":"a-hrc-54-76-p0009","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"9","seq":11,"section":"I. Introduction","text":"À l’occasion de sa troisième visite, l’Équipe d’experts internationaux s’est entretenue\nà Kinshasa avec des membres du Gouvernement, du corps diplomatique, du système des\nNations Unies et des organisations de la société civile, pour s’enquérir de l’état d’avancement\nde la lutte contre l’impunité et de la mise en œuvre de la justice transitionnelle."},{"id":"a-hrc-54-76-p0010","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"10","seq":12,"section":"I. Introduction","text":"Le 13 juillet 2023, l’Équipe d’experts internationaux a tenu une réunion virtuelle avec\nl’Envoyé spécial du Secrétaire général pour la région des Grands Lacs. La réunion a porté\nsur la prise en compte de la justice transitionnelle dans les initiatives sous-régionales de\nrèglement des conflits en République démocratique du Congo."},{"id":"a-hrc-54-76-p0011","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"11","seq":13,"section":"I. Introduction","text":"Durant sa quatrième visite, l’Équipe d’experts internationaux a participé à Kananga,\nles 24 et 25 juillet 2023, à l’atelier d’appropriation et de validation des textes de\nfonctionnement de la Commission provinciale vérité, justice et réconciliation au\nKasaï-Central, en l’occurrence le règlement intérieur et le manuel de procédures. En marge\nde cette activité, elle a également assisté au lancement officiel des activités de la Commission,\nprécédé de la signature de l’accord portant cadre de coopération technique entre la\nCommission et le BCNUDH."},{"id":"a-hrc-54-76-p0012","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"12","seq":14,"section":"I. Introduction","text":"Du 25 au 27 juillet 2023, à Zongo, dans la province du Kongo-Central, l’Équipe\nd’experts internationaux a coorganisé avec le Ministère des droits humains et le BCNUDH\nla retraite d’écriture du plan d’action stratégique dudit ministère en matière de justice\ntransitionnelle."},{"id":"a-hrc-54-76-p0013","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"13","seq":15,"section":"I. Introduction","text":"Conformément à la résolution 51/36 du Conseil des droits de l’homme, l’Équipe\nd’experts internationaux a présenté le 30 mars 2023 son rapport sur la situation en République\ndémocratique du Congo lors du dialogue interactif tenu dans le cadre de la\ncinquante-deuxième session du Conseil."},{"id":"a-hrc-54-76-p0014","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"14","seq":16,"section":"I. Introduction","text":"Le présent rapport est conforme aux dispositions de la résolution 51/36 du Conseil\ndes droits de l’homme. Il met en relief les différentes actions menées par l’Équipe d’experts\ninternationaux dans le cadre de l’exécution de son mandat élargi."},{"id":"a-hrc-54-76-p0015","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"15","seq":17,"section":"II. Mandat","text":"L’Équipe d’experts internationaux a organisé au début de sa mission un atelier\nd’évaluation de la mise en œuvre des différentes recommandations issues des rapports\nantérieurs1 qu’elle a présentés devant le Conseil des droits de l’homme. Cet atelier, qui a eu\nlieu les 25 et 26 janvier 2023, a regroupé des représentants des départements ministériels,\nd’ambassades, d’autorités judiciaires et de la société civile. Cette évaluation intérimaire a\npermis à l’Équipe d’experts internationaux de mesurer le niveau de progrès réalisé par la\nRépublique démocratique du Congo depuis la mise en place du mandat de l’Équipe d’experts\ninternationaux, en 2018."},{"id":"a-hrc-54-76-p0016","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"16","seq":18,"section":"II. Mandat","text":"L’exécution du mandat de l’Équipe d’experts internationaux intervient dans un\ncontexte où la République démocratique du Congo fait toujours face à une insécurité dans sa\npartie orientale, en raison de l’agression du pays par le Mouvement du 23 mars (M23) et de\nla présence de plusieurs groupes armés dans la région."},{"id":"a-hrc-54-76-p0017","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"17","seq":19,"section":"II. Mandat","text":"Hormis le contexte sécuritaire, la mise en œuvre du mandat intervient également dans\nun contexte de retrait de la Mission de l’Organisation des Nations Unies pour la stabilisation\nen République démocratique du Congo et de mise en place d’une stratégie de transition pour\nassurer la poursuite de l’appui des Nations Unies à la République démocratique du Congo."},{"id":"a-hrc-54-76-p0018","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"18","seq":20,"section":"II. Mandat","text":"Ce processus de retrait a eu un impact sur l’appui logistique indispensable à la mise\nen œuvre du mandat de l’Équipe d’experts internationaux."},{"id":"a-hrc-54-76-p0019","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"19","seq":21,"section":"II. Mandat","text":"Nonobstant la situation ainsi décrite, l’Équipe d’experts internationaux a pu effectuer\nquatre visites de terrain en République démocratique du Congo et apporter un appui\nsignificatif au Gouvernement."},{"id":"a-hrc-54-76-p0020","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"20","seq":22,"section":"III. Coopération entre l’Équipe d’experts internationaux","text":"Durant la période couverte par son mandat, l’Équipe d’experts internationaux a\nbénéficié d’une franche coopération avec les autorités de la République démocratique du\nCongo, notamment des facilités administratives pour ses visites dans le pays."},{"id":"a-hrc-54-76-p0021","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"21","seq":23,"section":"III. Coopération entre l’Équipe d’experts internationaux","text":"Lors de chacune de ses visites, l’Équipe d’experts internationaux a rencontré des\nprésidents d’institutions, des membres du Gouvernement et des autorités judiciaires du pays,\ndes membres du corps diplomatique et du système des Nations Unies, des représentants de la\nsociété civile, y compris des femmes et des jeunes, des chefs coutumiers et des autorités\nreligieuses. Cette franche coopération a constitué un atout pour la mise en œuvre du mandat\nde l’Équipe d’experts internationaux."},{"id":"a-hrc-54-76-p0022","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"22","seq":24,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux déplore la poursuite du conflit dans l’est de la\nRépublique démocratique du Congo. Exacerbée par l’attaque du M23, cette crise connaît une\nextension dans plusieurs localités de la province du Nord-Kivu, avec l’utilisation massive\nd’armes et d’explosifs. Elle entraîne par ailleurs d’importants mouvements de population."},{"id":"a-hrc-54-76-p0023","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"23","seq":25,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux note qu’après le retrait du M23 en mars 2023 de\ncertaines zones importantes, notamment le sud-ouest de Rutshuru et le nord-est de Masisi,\non assiste depuis avril 2023 à de nouveaux affrontements entre le M23 et les groupes armés\nlocaux et les Forces démocratiques de libération du Rwanda dans ces zones2."},{"id":"a-hrc-54-76-p0024","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"24","seq":26,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux est également préoccupée par la situation\nsécuritaire dans le territoire de Kabambare, dans la province du Maniema, où, selon un\nrapport du BCNUDH3, il y a eu en juillet 2023 de violents affrontements entre les groupes\narmés Maï-Maï Hercule et les groupes d’autodéfense de Masiya au chef-lieu du secteur de\nKabeya.\n2 Groupe mondial de la protection en République démocratique du Congo, « Points saillants de\nprotection − Avril-mai 2023 », p. 1.\n3 BCNUDH, « Note du BCNUDH Uvira sur la situation des droits de l’homme dans le territoire de\nKabambare (Province du Maniema), à la suite des violents affrontements du 15 juillet 2023, entre les\ngroupes armés Maï-Maï Malaika/Hercule et les autodéfenses de Masiya, au chef-lieu du Secteur des\nBabuyu (territoire de Kabambare, province du Maniema) », 17 juillet 2023."},{"id":"a-hrc-54-76-p0025","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"25","seq":27,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"La réunion virtuelle entre l’Équipe d’experts internationaux et l’Envoyé spécial du\nSecrétaire général pour la région des Grands Lacs tenue le 13 juillet 2023 a conforté l’idée\nselon laquelle le conflit dans l’est de la République démocratique du Congo est alimenté par\ndes groupes armés tant nationaux qu’étrangers. Certains groupes armés nationaux bénéficient\nde l’appui de pays étrangers."},{"id":"a-hrc-54-76-p0026","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"26","seq":28,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux est préoccupée par la lenteur de la mise en œuvre\ndes décisions et conclusions issues du processus de Nairobi, sous l’égide de la Communauté\nd’Afrique de l’Est, et de la feuille de route de Luanda. Au moment de la finalisation du\nprésent rapport, le précantonnement ou le cantonnement de plusieurs groupes armés très\nactifs dans l’est du pays n’avait toujours pas commencé. Un désarmement effectif suivi d’un\ncantonnement permettra un retour au calme et ouvrira la voie à la mise en œuvre du\nProgramme de désarmement, de démobilisation, de relèvement communautaire et de\nstabilisation. L’Équipe d’experts internationaux appelle à la mise en œuvre rapide des\ndécisions des processus de Luanda et de Nairobi, y compris le désarmement effectif de tous\nles groupes armés."},{"id":"a-hrc-54-76-p0027","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"27","seq":29,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux note avec satisfaction que, lors de l’audience lui\nayant été accordée le 22 juin 2023, le Vice-Premier Ministre et Ministre de la Défense et des\nanciens combattants a souligné la nécessité de désarmer les groupes armés et d’intégrer dans\nle Programme de désarmement, de démobilisation, de relèvement communautaire et de\nstabilisation les membres de ces groupes qui y étaient admissibles. Elle se félicite de la\ndisposition du Gouvernement de la République démocratique du Congo à poursuivre la\nconstruction des camps de cantonnement, et encourage à cet effet la communauté\ninternationale à soutenir cette initiative."},{"id":"a-hrc-54-76-p0028","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"28","seq":30,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux relève le lien évident qui existe entre l’insécurité\nqui sévit dans plusieurs localités du pays et l’absence de l’État dans ces zones. Elle prend\nnote des réformes en cours au Ministère de la défense qui visent, d’ici à la fin de l’année 2023,\nun déploiement de militaires pour renforcer leur présence sur l’ensemble du territoire\nnational."},{"id":"a-hrc-54-76-p0029","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"29","seq":31,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"Sur le plan humanitaire, l’Équipe d’experts internationaux déplore que rien qu’au\npremier trimestre de 2023, il y ait eu près de 677 000 nouvelles personnes déplacées à\nl’intérieur de leur propre pays, dont 51 % de femmes. Plus de 98 % de ces déplacements sont\ndus aux attaques et aux affrontements armés. Les principales provinces touchées sont celles\ndu Sud-Kivu, du Nord-Kivu et de l’Ituri4."},{"id":"a-hrc-54-76-p0030","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"30","seq":32,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux est préoccupée par l’augmentation des cas de\nviolations et d’abus, notamment des violences basées sur le genre et des violences sexuelles\nliées aux conflits dans les sites de personnes déplacées autour de Goma, ainsi que par la\nrecrudescence des attaques perpétrées contre des civils5."},{"id":"a-hrc-54-76-p0031","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"31","seq":33,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux déplore l’existence de « maisons de tolérance » ou\nmaisons de prostitution dans les camps de personnes déplacées où, du fait de leur\nvulnérabilité, de nombreuses femmes et filles font l’objet d’exploitation et d’abus sexuels.\nCe phénomène, qui s’amplifie, impliquerait des agents responsables de la sécurité des camps."},{"id":"a-hrc-54-76-p0032","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"32","seq":34,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux souligne que les cas de viols à l’égard des femmes\nont un impact négatif sur leur intégrité physique et morale, et déstabilisent la cohésion\nfamiliale et le tissu social. De plus, les enfants nés de ces viols, souvent abandonnés, peuvent\nêtre des proies pour les groupes armés."},{"id":"a-hrc-54-76-p0033","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"33","seq":35,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux s’inquiète de la détérioration de la situation\nhumanitaire consécutive aux conflits intercommunautaires dans le territoire de Kwamouth,\nnotamment les activités de la milice Mobondo entraînant des violences et des mouvements\nde population dans les provinces du Kwango, du Kwilu et de Mai-Ndombe ainsi que dans la\ncommune de Maluku de la province de Kinshasa."},{"id":"a-hrc-54-76-p0034","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"34","seq":36,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"Dans la province de Tanganyika, la situation est marquée par la recrudescence des\nattaques des miliciens twa et bantou contre plusieurs villages des territoires de Kalemie et de\nMoba. Il en résulte d’importants déplacements de population ainsi qu’une montée de la\ncriminalité. À cela s’ajoutent de multiples incursions des Maï-Maï Malaika à partir du sud\ndu territoire de Kabambare, dans la province du Maniema6."},{"id":"a-hrc-54-76-p0035","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"35","seq":37,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux reste préoccupée par l’augmentation des\nexpulsions des Congolais de l’Angola. Elle rappelle l’urgence de la mise en œuvre de sa\nrecommandation à cet effet7. Elle déplore en outre l’aggravation de la situation humanitaire\nen raison des conflits intercommunautaires en lien avec le pouvoir coutumier dans les\nprovinces du Kasaï."},{"id":"a-hrc-54-76-p0036","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"36","seq":38,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux est préoccupée par la dégradation de la situation\nsécuritaire à Kinshasa, marquée par des enlèvements suivis souvent de morts d’hommes, tel\nle cas de Chérubin Okende, député et ex-Ministre des transports issu du parti politique\nd’opposition Ensemble pour la République, dont le corps a été retrouvé le 13 juillet 2023.\nL’Équipe d’experts internationaux prend note de ce que le Gouvernement a condamné ce\ncrime et « décidé de la mise en place d’une commission d’enquête plus large,\npluridisciplinaire avec l’implication de tous les services et la collaboration des services\nétrangers pour faire la lumière en toute transparence sur ce cas 8 »."},{"id":"a-hrc-54-76-p0037","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"37","seq":39,"section":"V. Mise en œuvre du mandat de l’Équipe d’experts","text":"Le mandat de l’Équipe d’experts internationaux est essentiellement articulé autour de\ndeux pôles : d’une part, la lutte contre l’impunité et, d’autre part, l’appui au processus de\njustice transitionnelle."},{"id":"a-hrc-54-76-p0038","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"38","seq":40,"section":"A. Lutte contre l’impunité","text":"Dans le domaine de la lutte contre l’impunité, l’Équipe d’experts internationaux a\npoursuivi l’exécution de son mandat à travers l’analyse du contexte de l’administration de la\njustice en République démocratique du Congo et le suivi des dossiers judiciaires ouverts dans\nle cadre de la crise liée à la milice Kamuina Nsapu ainsi que d’autres cas emblématiques."},{"id":"a-hrc-54-76-p0039","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"39","seq":41,"section":"1. Administration de la justice en République démocratique du Congo","text":"L’atelier d’évaluation de la mise en œuvre des recommandations issues des différents\nrapports de l’Équipe d’experts internationaux publiés depuis la création de son mandat, soit\nde 2018 à 2022, organisé à Kinshasa les 25 et 26 janvier 2023, lui a permis de constater les\nefforts du Gouvernement pour améliorer l’administration de la justice."},{"id":"a-hrc-54-76-p0040","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"40","seq":42,"section":"1. Administration de la justice en République démocratique du Congo","text":"L’Équipe d’experts internationaux note en effet que, dans le domaine de la lutte contre\nl’impunité, le Ministère de la justice a adopté une stratégie portant sur les volets judiciaire et\npénitentiaire."},{"id":"a-hrc-54-76-p0041","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"41","seq":43,"section":"1. Administration de la justice en République démocratique du Congo","text":"Concernant le volet judiciaire, et singulièrement le renforcement quantitatif et\nqualitatif des magistrats, l’Équipe d’experts internationaux salue le recrutement de\n5 000 nouveaux magistrats, ce qui répond à l’une des recommandations qu’elle avait\nformulées dans ses précédents rapports.\n6 Ibid., p. 1 et 2.\n7 A/HRC/48/82, par. 89 et 90.\n8 Communiqué du Ministre des communications et des médias, porte-parole du Gouvernement,\nà l’issue du Conseil des ministres du 14 juillet 2023."},{"id":"a-hrc-54-76-p0042","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"42","seq":44,"section":"1. Administration de la justice en République démocratique du Congo","text":"L’Équipe d’experts internationaux encourage le Gouvernement à poursuivre ces\nrecrutements, d’autant plus que, selon le Conseil supérieur de la magistrature, la République\ndémocratique du Congo a besoin d’au moins 10 000 magistrats pour une couverture\nraisonnable de l’ensemble du territoire9."},{"id":"a-hrc-54-76-p0043","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"43","seq":45,"section":"1. Administration de la justice en République démocratique du Congo","text":"L’Équipe d’experts internationaux note que le processus de formation initiale a\ncommencé avec une première vague de 2 500 nouveaux magistrats pour une durée de trois\nmois. Elle félicite à cet égard le Gouvernement et l’encourage à mettre en place un\nprogramme de formation continue, au besoin avec l’appui des partenaires internationaux."},{"id":"a-hrc-54-76-p0044","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"44","seq":46,"section":"1. Administration de la justice en République démocratique du Congo","text":"L’Équipe d’experts internationaux souligne que l’effort considérable de renforcement\ndes ressources humaines qui est en cours doit être accompagné de l’amélioration des\nconditions de travail des magistrats, notamment l’équipement en matériel roulant et en\nmobilier de bureau. Elle relève que la bonne administration de la justice requiert également\nle renforcement des compétences des auxiliaires de justice, en particulier les greffiers, les\nofficiers de police judiciaire et les avocats."},{"id":"a-hrc-54-76-p0045","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"45","seq":47,"section":"1. Administration de la justice en République démocratique du Congo","text":"L’Équipe d’experts internationaux constate que le Ministère de la justice a engagé une\nréforme du système pénitentiaire impliquant un cadre normatif et institutionnel conforme aux\nnormes internationales."},{"id":"a-hrc-54-76-p0046","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"46","seq":48,"section":"1. Administration de la justice en République démocratique du Congo","text":"L’Équipe d’experts internationaux prend note de la signature, le 1er juin 2023, du\nMémorandum d’entente entre la République démocratique du Congo et le Bureau du\nProcureur de la Cour pénale internationale."},{"id":"a-hrc-54-76-p0047","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"47","seq":49,"section":"1. Administration de la justice en République démocratique du Congo","text":"L’Équipe d’experts internationaux se félicite de ce que ce mémorandum vise à\nrenforcer la lutte contre l’impunité en République démocratique du Congo, et prend acte de\nl’engagement de cette dernière à « assurer la protection des victimes et des témoins et à leur\napporter le soutien et l’assistance nécessaires, y compris un soutien psychologique, et à\nveiller, par le biais des autorités judiciaires compétentes, à leur familiarisation avec le\ndéroulement des procédures »10."},{"id":"a-hrc-54-76-p0048","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"48","seq":50,"section":"1. Administration de la justice en République démocratique du Congo","text":"Au cours de son entretien avec le Vice-Premier Ministre et Ministre de la défense et\ndes anciens combattants, l’Équipe d’experts internationaux a pris note avec satisfaction de\nl’engagement du Ministère à lutter contre l’impunité au sein des Forces armées de la\nRépublique démocratique du Congo. À cet effet, le Ministre a exprimé le souhait d’un\naccompagnement pour le renforcement des capacités des Forces armées dans le domaine des\ndroits de l’homme et du droit international humanitaire. L’Équipe d’experts internationaux\nprie le Haut-Commissariat des Nations Unies aux droits de l’homme de prendre en\nconsidération ce souhait."},{"id":"a-hrc-54-76-p0049","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"49","seq":51,"section":"1. Administration de la justice en République démocratique du Congo","text":"S’agissant des allégations de viols et d’abus sexuels attribuables aux membres des\nForces armées de la République démocratique du Congo sur les sites de personnes déplacées\nde Kwamouth et de Goma, l’Équipe d’experts internationaux se félicite de la mise en place,\npar le Ministère de la défense et des anciens combattants, de deux commissions d’enquête11."},{"id":"a-hrc-54-76-p0050","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"50","seq":52,"section":"2. Suivi des dossiers judiciaires","text":"Lors des visites de terrain, l’Équipe d’experts internationaux a rencontré l’Auditeur\ngénéral des Forces armées de la République démocratique du Congo et l’Auditeur militaire\nsupérieur de l’ancienne province du Kasaï-Occidental pour faire le suivi des dossiers ouverts\nà la suite de la crise liée à la milice Kamuina Nsapu."},{"id":"a-hrc-54-76-p0051","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"51","seq":53,"section":"2. Suivi des dossiers judiciaires","text":"À l’issue de ces échanges, l’Équipe d’experts internationaux a relevé que, sur les\n16 cas emblématiques ouverts à cet effet, 6 dossiers n’avaient pas encore fait l’objet d’un\ndébut d’instruction, 8 dossiers étaient en cours d’instruction, et 2 dossiers étaient en cours de\njugement, soit le dossier Mulombodi et celui de l’assassinat des deux experts des\nNations Unies, Zaida Catalán et Michael Sharp."},{"id":"a-hrc-54-76-p0052","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"52","seq":54,"section":"2. Suivi des dossiers judiciaires","text":"Dans le dossier Mulombodi, où deux officiers généraux sont poursuivis pour crimes\ncontre l’humanité pour des faits de viols, de meurtres, de traitements inhumains et dégradants\net d’emprisonnement du fait de la responsabilité du supérieur hiérarchique, l’audience est en\ncours devant la Haute Cour militaire."},{"id":"a-hrc-54-76-p0053","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"53","seq":55,"section":"2. Suivi des dossiers judiciaires","text":"L’Équipe d’experts internationaux note également que l’audience en appel se déroule\ndevant la Haute Cour militaire dans le dossier de l’assassinat des deux experts des\nNations Unies. Elle note en outre que l’instruction se poursuit dans l’affaire Moyo Musuila\nconcernant les quatre accompagnateurs des experts des Nations Unies."},{"id":"a-hrc-54-76-p0054","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"54","seq":56,"section":"2. Suivi des dossiers judiciaires","text":"L’Équipe d’experts internationaux se félicite de l’appui apporté par le\nHaut-Commissariat aux droits de l’homme aux autorités judiciaires, à travers le déploiement\nde l’équipe d’assistance technique composée de médecins légistes, de psychologues,\nd’anthropologues, et de spécialistes des questions du genre, de la protection des victimes et\nde la géolocalisation."},{"id":"a-hrc-54-76-p0055","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"55","seq":57,"section":"2. Suivi des dossiers judiciaires","text":"Cette équipe pluridisciplinaire a procédé, au cours d’une mission conjointe\nd’investigation, à l’exhumation des restes humains sur neuf nouveaux sites dans les provinces\ndu Kasaï et du Kasaï-Central. Les ossements d’au moins 52 victimes ont été collectés et ont\nfait l’objet de prélèvements et d’examens au laboratoire de criminalistique. Une autre mission\nconjointe médico-légale a été conduite à Kabalo, dans la province de Tanganyika, pour\nlocaliser, exhumer et examiner des corps de victimes appartenant à la minorité ethnique twa."},{"id":"a-hrc-54-76-p0056","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"56","seq":58,"section":"2. Suivi des dossiers judiciaires","text":"Dans le domaine du renforcement des capacités, l’équipe d’assistance technique a\norganisé, en juillet 2023, un colloque international sur les enjeux et défis de la médecine\nlégale en République démocratique du Congo. Ce colloque visait la mise en place d’une\nstratégie pour le développement et le renforcement des capacités en médecine légale, laquelle\ncontribuerait à lutter efficacement contre l’impunité et à soutenir le processus de justice\ntransitionnelle dans le pays."},{"id":"a-hrc-54-76-p0057","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"57","seq":59,"section":"2. Suivi des dossiers judiciaires","text":"L’Équipe d’experts internationaux encourage le Gouvernement à mettre en œuvre la\nfeuille de route issue des travaux de ce colloque, et invite à cet effet la communauté\ninternationale à apporter tout son soutien à la République démocratique du Congo en vue de\nla réalisation des objectifs de ce colloque."},{"id":"a-hrc-54-76-p0058","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"58","seq":60,"section":"2. Suivi des dossiers judiciaires","text":"L’Équipe d’experts internationaux salue cette coopération technique et suggère le\nrenouvellement et le renforcement en ressources humaines de l’équipe d’assistance\ntechnique, en particulier dans le domaine psychothérapeutique."},{"id":"a-hrc-54-76-p0059","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"59","seq":61,"section":"2. Suivi des dossiers judiciaires","text":"L’Équipe d’experts internationaux réaffirme que seule une justice impartiale, rendue\ndans un délai raisonnable, pourra rassurer les victimes et permettre d’entrevoir un pardon\nsincère de la part des victimes, gage d’une réconciliation véritable."},{"id":"a-hrc-54-76-p0060","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"60","seq":62,"section":"3. Situation des victimes","text":"L’Équipe d’experts internationaux note que, depuis la publication de son précédent\nrapport, les préoccupations des victimes demeurent12."},{"id":"a-hrc-54-76-p0061","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"61","seq":63,"section":"3. Situation des victimes","text":"Lors de sa visite de terrain à Kananga, le 19 mai 2023, l’Équipe d’experts\ninternationaux a rencontré l’Association des victimes du grand Kasaï. Au cours des échanges,\nle porte-parole de l’Association a renouvelé les inquiétudes des victimes face à la lenteur de\nla justice, et réitéré leur demande de voir la communauté internationale faire pression sur le\nGouvernement afin que justice leur soit rendue dans les meilleurs délais. En outre, le\nporte-parole a identifié quelques sites ayant fait l’objet d’attaques lors de la crise liée à la\nmilice Kamuina Nsapu et a souligné le besoin de construire des mémoriaux à Nganza, à\nMulombodi et à Dibaya.\n12   A/HRC/51/60, par. 48."},{"id":"a-hrc-54-76-p0062","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"62","seq":64,"section":"3. Situation des victimes","text":"Au cours d’une audience tenue le 25 juillet 2023, le Gouverneur de la province du\nKasaï-Central a informé l’Équipe d’experts internationaux, en présence du Ministre des\ndroits humains, des dispositions déjà prises pour la réalisation imminente des mémoriaux."},{"id":"a-hrc-54-76-p0063","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"63","seq":65,"section":"3. Situation des victimes","text":"L’Équipe d’experts internationaux salue la tenue de l’atelier de formation sur la justice\ntransitionnelle organisé par le BCNUDH en faveur des membres de l’Association des\nvictimes du grand Kasaï."},{"id":"a-hrc-54-76-p0064","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"64","seq":66,"section":"3. Situation des victimes","text":"L’Équipe d’experts internationaux encourage les autorités de la République\ndémocratique du Congo à mettre en œuvre sa recommandation visant à mettre en place un\nprogramme de développement au profit des victimes de la crise du Kasaï."},{"id":"a-hrc-54-76-p0065","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"65","seq":67,"section":"3. Situation des victimes","text":"L’Équipe d’experts internationaux apprécie également l’association des victimes à\nl’atelier de validation des textes de fonctionnement de la Commission provinciale vérité,\njustice et réconciliation au Kasaï-Central ainsi qu’au lancement des activités de la\nCommission, le 25 juillet 2023. Elle encourage la Commission à poursuivre et à renforcer sa\ncollaboration avec les victimes de la crise du Kasaï."},{"id":"a-hrc-54-76-p0066","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"66","seq":68,"section":"1. Suivi de la mise en œuvre du processus de justice transitionnelle","text":"Dans son précédent rapport, l’Équipe d’experts internationaux avait souligné la\nnécessité d’un accompagnement conséquent de la Commission provinciale vérité, justice et\nréconciliation au Kasaï-Central par le Gouvernement et les partenaires techniques et\nfinanciers, à travers une mobilisation des ressources essentielles à son fonctionnement13."},{"id":"a-hrc-54-76-p0067","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"67","seq":69,"section":"1. Suivi de la mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux se félicite de ce que l’intérêt pour\nl’accompagnement de la Commission provinciale vérité, justice et réconciliation au\nKasaï-Central, bien que timide, commence à se manifester. En effet, outre l’appui significatif\ndu BCNUDH, d’autres partenaires commencent à la soutenir. À ce sujet, l’Équipe d’experts\ninternationaux a été informée de la signature, en juillet 2023, d’un accord de partenariat entre\nTRIAL International et la Commission. Elle salue cette collaboration et invite les autres\nbailleurs de fonds à faire de même afin d’assurer le succès du processus de justice\ntransitionnelle au Kasaï-Central."},{"id":"a-hrc-54-76-p0068","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"68","seq":70,"section":"1. Suivi de la mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux salue la mise à disposition par le Gouverneur de la\nprovince du Kasaï-Central d’un bâtiment pour abriter le siège de la Commission provinciale\nvérité, justice et réconciliation au Kasaï-Central et l’encourage à lui allouer une dotation\nmensuelle suffisante pour son fonctionnement. Elle prend note de la signature d’un protocole\nd’accord portant création d’un cadre de concertation de partenariat entre le gouvernement\nprovincial du Kasaï-Central et la Commission."},{"id":"a-hrc-54-76-p0069","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"69","seq":71,"section":"1. Suivi de la mise en œuvre du processus de justice transitionnelle","text":"Dans le domaine du renforcement des capacités, l’Équipe d’experts internationaux\nnote qu’une formation initiale des commissaires a été organisée avec l’appui du BCNUDH,\ndu 23 au 27 janvier 2023, sur l’appropriation de leur mandat et le fonctionnement d’une\ncommission vérité, justice et réconciliation. L’Équipe d’experts internationaux a contribué à\ncette formation en assurant trois modules portant sur le partage d’expériences du\nfonctionnement des commissions vérité et justice, sur la réconciliation et les commissions\nvérité et justice, et sur la prise en compte de la dimension de genre dans le processus de\njustice transitionnelle."},{"id":"a-hrc-54-76-p0070","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"70","seq":72,"section":"1. Suivi de la mise en œuvre du processus de justice transitionnelle","text":"Les 24 et 25 juillet 2023, l’Équipe d’experts internationaux a participé à Kananga à\ndeux événements organisés conjointement par le BCNUDH et le gouvernement provincial\ndu Kasaï-Central. Le premier concernait l’atelier d’appropriation et de validation des textes\nde fonctionnement de la Commission provinciale vérité, justice et réconciliation au\nKasaï-Central, et le second, le lancement officiel des activités de la Commission. Ces deux\névénements se sont déroulés en présence du Ministre des droits humains, du Représentant\npermanent de la République démocratique du Congo auprès de l’Office des Nations Unies et\ndes autres organisations internationales à Genève, de représentants d’associations de\nvictimes, de certains bailleurs de fonds, et de représentants du système des Nations Unies en\nRépublique démocratique du Congo ainsi que d’organisations non gouvernementales\ninternationales. En marge de la cérémonie du lancement officiel, l’Équipe d’experts\ninternationaux a assisté à la signature de deux documents : l’un portant « accord de\ncoopération technique entre la Commission et le BCNUDH », l’autre relatif au « Protocole\nd’accord portant création d’un cadre de concertation entre le gouvernement provincial du\nKasaï-Central et la Commission ». L’Équipe d’experts internationaux salue ces initiatives."},{"id":"a-hrc-54-76-p0071","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"71","seq":73,"section":"1. Suivi de la mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux apprécie la mise à disposition par le\nHaut-Commissariat aux droits de l’homme d’un expert en justice transitionnelle au bureau\nde terrain de Kananga, pour appuyer le travail de la Commission provinciale vérité, justice\net réconciliation au Kasaï-Central. L’appui de cet expert a été significatif dans l’élaboration\net la validation des outils stratégiques et méthodologiques relatifs au fonctionnement de la\nCommission."},{"id":"a-hrc-54-76-p0072","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"72","seq":74,"section":"2. Mise en œuvre du processus de justice transitionnelle au niveau national","text":"L’Équipe d’experts internationaux relève qu’au niveau national, les initiatives de\njustice transitionnelle sont pilotées par le Ministère des droits humains et le Programme de\ndésarmement, de démobilisation, de relèvement communautaire et de stabilisation.\nLes structures de mise en œuvre du processus de justice transitionnelle"},{"id":"a-hrc-54-76-p0073","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"73","seq":75,"section":"2. Mise en œuvre du processus de justice transitionnelle au niveau national","text":"L’Équipe d’experts internationaux loue les efforts du Ministère des droits humains\nvisant à poursuivre les consultations populaires en donnant la possibilité aux populations, et\nen particulier aux victimes, d’exprimer leurs quêtes de vérité, de justice, de réparation et de\ngaranties de non-répétition dans le cadre de la justice transitionnelle. L’Équipe d’experts\ninternationaux a été informée de la poursuite, par le Ministère des droits humains, en\njuin 2023, des consultations populaires dans les provinces du Kasaï-Oriental, du Sankuru, de\nLomami et de Kinshasa. Elle encourage fortement le Gouvernement à poursuivre ces\nconsultations, et rappelle cependant que celles-ci doivent toujours être conformes aux normes\ninternationales en la matière."},{"id":"a-hrc-54-76-p0074","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"74","seq":76,"section":"2. Mise en œuvre du processus de justice transitionnelle au niveau national","text":"L’Équipe d’experts internationaux se félicite de l’élaboration du document de\npolitique nationale en matière de justice transitionnelle et encourage le Gouvernement à\nprocéder à sa mise en œuvre."},{"id":"a-hrc-54-76-p0075","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"75","seq":77,"section":"2. Mise en œuvre du processus de justice transitionnelle au niveau national","text":"Les 25 et 26 janvier 2023, l’Équipe d’experts internationaux a coorganisé avec le\nMinistère des droits humains, à Kinshasa, un atelier sur l’évaluation de la mise en œuvre de\nses recommandations formulées de 2018 à 2022, dans le cadre de son mandat. Cet atelier a\nréuni une cinquantaine de participants de diverses structures étatiques, de la société civile et\ndu corps diplomatique. Il a permis à l’Équipe d’experts internationaux de mesurer le niveau\nde mise en œuvre des recommandations et d’identifier les contraintes et défis qui demeurent."},{"id":"a-hrc-54-76-p0076","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"76","seq":78,"section":"2. Mise en œuvre du processus de justice transitionnelle au niveau national","text":"L’Équipe d’experts internationaux salue également le déploiement par le\nHaut-Commissariat aux droits de l’homme d’un fonctionnaire des droits de l’homme\nspécialiste en justice transitionnelle au sein du Ministère des droits humains. Sa mission est\nd’appuyer le Ministère dans la rédaction et l’adoption d’outils méthodologiques et\nstratégiques relatifs à la justice transitionnelle. Grâce à cet appui, le Ministère des droits\nhumains, en collaboration avec le BCNUDH, l’Équipe d’experts internationaux et l’Entité\ndes Nations Unies pour l’égalité des sexes et l’autonomisation des femmes (ONU-Femmes),\na organisé à Zongo, dans la province du Kongo-Central, une retraite d’écriture de son plan\nd’action stratégique en matière de justice transitionnelle. Le plan d’action issu de cette retraite\ndevrait être validé au cours d’un atelier qui doit réunir les ministères sectoriels, les membres\ndu corps diplomatique, les organisations internationales, les représentants de la société civile\net des victimes."},{"id":"a-hrc-54-76-p0077","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"77","seq":79,"section":"2. Mise en œuvre du processus de justice transitionnelle au niveau national","text":"L’Équipe d’experts internationaux félicite le Ministère des droits humains pour la\ntenue de cette retraite et l’encourage vivement à procéder à sa validation dans les meilleurs\ndélais, afin d’avoir une feuille de route pour la justice transitionnelle."},{"id":"a-hrc-54-76-p0078","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"78","seq":80,"section":"2. Mise en œuvre du processus de justice transitionnelle au niveau national","text":"L’Équipe d’experts internationaux invite les partenaires, y compris le BCNUDH, à\nsoutenir les efforts du Ministère des droits humains dans la mise en œuvre de la feuille de\nroute pour la justice transitionnelle après sa validation."},{"id":"a-hrc-54-76-p0079","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"79","seq":81,"section":"2. Mise en œuvre du processus de justice transitionnelle au niveau national","text":"L’Équipe d’experts internationaux souligne l’importance de multiplier, sur les plans\nnational et sous-régional, les initiatives visant à favoriser le retour à la paix dans les zones en\nconflit et à permettre aux communautés ayant manifesté le désir de recourir aux mécanismes\nde justice transitionnelle d’exprimer leurs besoins de vérité, de réparation, de justice et de\nréformes à travers les consultations populaires. Ces initiatives pourraient considérer le rôle à\njouer par les chefs coutumiers, les autorités religieuses, les associations de femmes et les\njeunes pour créer des portes d’entrée favorables à un dialogue sur la justice transitionnelle."},{"id":"a-hrc-54-76-p0080","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"80","seq":82,"section":"2. Mise en œuvre du processus de justice transitionnelle au niveau national","text":"L’Équipe d’experts internationaux prend note des efforts du Gouvernement pour\npromouvoir la paix et la restauration de l’autorité de l’État en mettant en place le Programme\nde désarmement, de démobilisation, de relèvement communautaire et de stabilisation. La\nstratégie nationale de mise en œuvre de ce programme met l’accent sur l’approche\ncommunautaire inclusive et la justice transitionnelle comme mécanismes de règlement des\nconflits, de réconciliation et de réparation des préjudices."},{"id":"a-hrc-54-76-p0081","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"81","seq":83,"section":"2. Mise en œuvre du processus de justice transitionnelle au niveau national","text":"L’Équipe d’experts internationaux se félicite des progrès accomplis par le Programme\nde désarmement, de démobilisation, de relèvement communautaire et de stabilisation,\nnotamment l’implantation de ses antennes provinciales et l’adoption des plans provinciaux.\nCependant, elle l’encourage à davantage collaborer avec les institutions nationales\nimpliquées dans le processus de justice transitionnelle."},{"id":"a-hrc-54-76-p0082","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"82","seq":84,"section":"2. Mise en œuvre du processus de justice transitionnelle au niveau national","text":"L’Équipe d’experts internationaux constate avec inquiétude que, bien que les plans\nopérationnels provinciaux aient connu un début de mise en œuvre, leur impact sur la paix et\nla sécurité demeure limité en raison de la persistance des attaques des groupes armés dans\nl’est du pays."},{"id":"a-hrc-54-76-p0083","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"83","seq":85,"section":"2. Mise en œuvre du processus de justice transitionnelle au niveau national","text":"Lors de sa deuxième visite, l’Équipe d’experts internationaux s’est entretenue avec le\nCoordonnateur du Programme de désarmement, de démobilisation, de relèvement\ncommunautaire et de stabilisation. À l’issue de cet entretien, elle a noté des avancées,\nnotamment la production d’outils stratégiques tels que la cartographie des conflits identifiant\nles groupes armés locaux et étrangers, l’élaboration d’un plan opérationnel provincial,\nl’identification des sites de désarmement et de démobilisation, et la sensibilisation des\npopulations. Toutefois, l’Équipe d’experts internationaux a pris note de quelques\ncontradictions entre les partenaires techniques et financiers et le Programme, notamment\ndans l’approche communautaire de réinsertion ou de prise en charge des démobilisés issus\ndes groupes armés."},{"id":"a-hrc-54-76-p0084","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"84","seq":86,"section":"2. Mise en œuvre du processus de justice transitionnelle au niveau national","text":"Relativement à la question de la collaboration entre les différentes structures chargées\nde mettre en œuvre le processus de justice transitionnelle en République démocratique du\nCongo, le Coordonnateur du Programme de désarmement, de démobilisation, de relèvement\ncommunautaire et de stabilisation a souligné l’existence de synergies entre le Programme et\nles ministères sectoriels dans le cadre du relèvement communautaire."},{"id":"a-hrc-54-76-p0085","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"85","seq":87,"section":"2. Mise en œuvre du processus de justice transitionnelle au niveau national","text":"L’Équipe d’experts internationaux a constaté une différence d’approche\nopérationnelle entre le Programme de désarmement, de démobilisation, de relèvement\ncommunautaire et de stabilisation et ses partenaires. Elle a noté que le Programme privilégiait\nune approche non judiciaire optant pour la resocialisation des ex-combattants, tandis que les\npartenaires y associaient le volet des poursuites judiciaires. Pour promouvoir le vivre\nensemble des populations, l’Équipe d’experts internationaux exhorte les autorités chargées\nde la mise en œuvre du Programme et les partenaires à établir un équilibre entre les poursuites\njudiciaires, qui garantissent le droit des victimes à la justice, et les stratégies de\nresocialisation, qui favorisent un climat d’apaisement au sein des communautés."},{"id":"a-hrc-54-76-p0086","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"86","seq":88,"section":"3. Défis de la mise en œuvre du processus de justice transitionnelle","text":"Les défis de la mise en œuvre du processus de justice transitionnelle demeurent\nnotamment la sensibilisation et la communication sur le processus ainsi que son appropriation\npar la population. L’Équipe d’experts internationaux note toutefois des évolutions\nconcernant : a) l’harmonisation des différents processus en cours, en vue d’obtenir une vision\nd’ensemble et de permettre leur mise en œuvre intégrée ; b) le financement du processus de\njustice transitionnelle ; c) la prise en compte de la dimension transfrontalière des conflits ;\nd) la question des réparations ; et e) la mise en œuvre de la justice transitionnelle dans un\ncontexte d’insécurité et de conflits intercommunautaires.\na)         L’harmonisation et la communication adéquate des différents processus en cours\ndans le cadre d’une vision d’ensemble et leur mise en œuvre intégrée"},{"id":"a-hrc-54-76-p0087","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"87","seq":89,"section":"3. Défis de la mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux avait déjà identifié dans son précédent rapport\nquelques pesanteurs associées à la mise en œuvre des initiatives de justice transitionnelle en\nRépublique démocratique du Congo, notamment la coordination, l’articulation et le\nfinancement de ces initiatives, ainsi que la stratégie de communication sur ces différentes\ninitiatives 14 . Lors d’une séance de travail avec le Coordonnateur du Programme de\ndésarmement, de démobilisation, de relèvement communautaire et de stabilisation le 22 mai\n2023, l’Équipe d’experts internationaux a pu constater des signaux positifs dans la\ncoordination entre les différentes institutions chargées de la justice transitionnelle. À ce sujet,\nelle a été informée du développement d’une synergie entre le Ministère du Plan et le\nProgramme pour le recours à une main-d’œuvre disponible parmi les bénéficiaires du\nProgramme, afin de favoriser leur insertion socioéconomique."},{"id":"a-hrc-54-76-p0088","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"88","seq":90,"section":"3. Défis de la mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux a néanmoins noté que l’unique cadre de\nconcertation entre le Programme de désarmement, de démobilisation, de relèvement\ncommunautaire et de stabilisation et le Ministère des droits humains était le comité de\npilotage, qui est un organe de gestion propre au Programme. Le Ministre des droits humains,\nqui a la mission d’harmoniser la justice transitionnelle au niveau national, n’a qu’un rôle\nd’observateur dans ce comité. Il existe donc des risques de chevauchement des initiatives, de\ndéperdition des ressources, de manque de cohérence dans l’action et de confusion dans\nl’esprit du public concernant les attributions et les rôles des différents acteurs."},{"id":"a-hrc-54-76-p0089","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"89","seq":91,"section":"3. Défis de la mise en œuvre du processus de justice transitionnelle","text":"À cet effet, l’Équipe d’experts internationaux soutient l’initiative du BCNUDH\nd’organiser un atelier de haut niveau entre la coordination nationale du Programme de\ndésarmement, de démobilisation, de relèvement communautaire et de stabilisation et le\nMinistère des droits humains.\nb)         Le financement du processus de justice transitionnelle"},{"id":"a-hrc-54-76-p0090","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"90","seq":92,"section":"3. Défis de la mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux reste préoccupée par le fait que le financement du\nprocessus dépend pour l’essentiel des aides extérieures. La nécessité d’un financement\nnational renforcé, seul à même d’assurer la crédibilité, la cohérence et la durabilité du\nprocessus, demeure."},{"id":"a-hrc-54-76-p0091","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"91","seq":93,"section":"3. Défis de la mise en œuvre du processus de justice transitionnelle","text":"Lors de sa deuxième visite, l’Équipe d’experts internationaux a soulevé la question\ndu financement lors des échanges avec le Président de l’Assemblée nationale et a noté\nl’engagement des parlementaires à prévoir un soutien financier pour le processus de justice\ntransitionnelle en République démocratique du Congo, et dans la province du Kasaï-Central\nen particulier."},{"id":"a-hrc-54-76-p0092","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"92","seq":94,"section":"3. Défis de la mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux encourage le Président de l’Assemblée nationale à\ntraduire cet engagement en actes concrets.\nc)         La prise en compte de la dimension transfrontalière des conflits"},{"id":"a-hrc-54-76-p0093","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"93","seq":95,"section":"3. Défis de la mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux reste préoccupée par la dimension transfrontalière\nou sous-régionale des conflits dans l’est de la République démocratique du Congo. Lors de\nsa réunion virtuelle avec l’Envoyé spécial du Secrétaire général pour la région des Grands\nLacs, elle a eu des discussions fructueuses en vue d’envisager la possibilité de prendre en\ncompte les dimensions de la justice transitionnelle dans les stratégies sous-régionales de\npromotion de la paix, de la sécurité et de la stabilité en République démocratique du Congo.\n14   Ibid., par. 64."},{"id":"a-hrc-54-76-p0094","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"94","seq":96,"section":"3. Défis de la mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux se félicite des échanges avec l’Envoyé spécial du\nSecrétaire général pour la région des Grands Lacs et a pris note de son souhait de formaliser\nune coopération institutionnelle entre le Haut-Commissariat aux droits de l’homme et le\nRéseau de coopération judiciaire de la région des Grands Lacs, afin de permettre à ce dernier\nde bénéficier de l’appui du Haut-Commissariat.\nd)        La question des réparations"},{"id":"a-hrc-54-76-p0095","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"95","seq":97,"section":"3. Défis de la mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux avait déjà relevé les difficultés auxquelles font face\nles victimes en matière de réparation dans son précédent rapport15."},{"id":"a-hrc-54-76-p0096","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"96","seq":98,"section":"3. Défis de la mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux note cependant que la réparation des victimes est\ndésormais encadrée juridiquement par la loi no 22/065 du 26 décembre 2022 fixant les\nprincipes fondamentaux relatifs à la protection et à la réparation des victimes de violences\nsexuelles liées aux conflits et des victimes des crimes contre la paix et la sécurité de\nl’humanité. Promulguée par le Président de la République, cette loi définit la vision du\nGouvernement en matière de réparation et promeut la création d’un programme de\nréparations administratives afin de répondre au problème persistant de non-paiement des\nréparations judiciaires. L’Équipe d’experts internationaux constate que le Gouvernement a\négalement institué par le décret no 22/38 du 6 décembre 2022 un établissement public chargé\nd’encadrer les victimes et les réparations à travers le Fonds national de réparation des\nvictimes des violences sexuelles liées aux conflits et d’autres crimes contre la paix et la\nsécurité de l’humanité en République Démocratique du Congo (FONAREV). Un décret\nmodifiant et complétant le décret susmentionné a été adopté en mai 2023."},{"id":"a-hrc-54-76-p0097","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"97","seq":99,"section":"3. Défis de la mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux souligne la nécessité, dans le cadre de la réparation\nnon judiciaire, de combiner les mesures cliniques, l’appui psychothérapeutique et les actions\nde réinsertion sociale pour permettre aux victimes de se prendre en charge et de retrouver\nleur dignité."},{"id":"a-hrc-54-76-p0098","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"98","seq":100,"section":"3. Défis de la mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux souligne la nécessité de considérer les réparations\ncollectives qui permettent de traiter les causes et les conséquences du conflit, telles que les\nécoles, les centres de santé ou les foyers polyvalents pour les jeunes et les victimes de\nviolences sexuelles.\ne)        La mise en œuvre de la justice transitionnelle dans un contexte d’insécurité\net de conflits intercommunautaires"},{"id":"a-hrc-54-76-p0099","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"99","seq":101,"section":"3. Défis de la mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux demeure préoccupée par le fait que le processus de\njustice transitionnelle se déroule dans un contexte de persistance de conflits anciens et\nd’émergence de nouveaux conflits intercommunautaires, notamment dans les provinces de\nMai-Ndombe, du Kwilu et du Kwango ainsi que dans la commune de Maluku de la province\nde Kinshasa, avec une augmentation des discours de haine."},{"id":"a-hrc-54-76-p0100","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"100","seq":102,"section":"3. Défis de la mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux s’inquiète des conséquences humanitaires des\nconflits qui ont cours notamment dans les provinces de Mai-Ndombe, du Kwilu et du\nKwango ainsi que dans la commune de Maluku de la province de Kinshasa."},{"id":"a-hrc-54-76-p0101","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"101","seq":103,"section":"3. Défis de la mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux exhorte le Gouvernement à considérer cette\nsituation fragilisant la protection des civils et rendant difficile la réponse humanitaire. Elle\ninvite les partenaires au développement et la communauté internationale à accompagner le\nGouvernement de la République démocratique du Congo par des actions urgentes et\nconcertées allant dans le sens de la restauration de la paix et de l’équilibre social."},{"id":"a-hrc-54-76-p0102","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"102","seq":104,"section":"3. Défis de la mise en œuvre du processus de justice transitionnelle","text":"À cet effet, l’Équipe d’experts internationaux a eu des échanges avec le Ministre des\ndroits humains, le 16 mai 2023, sur la situation sécuritaire en République démocratique du\nCongo. Elle se réjouit également du fait que la situation sécuritaire dans l’ouest du pays fait\nl’objet d’une attention particulière de la part du BCNUDH."},{"id":"a-hrc-54-76-p0103","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"103","seq":105,"section":"A. Conclusions","text":"L’Équipe d’experts internationaux a continué à bénéficier de la pleine\ncoopération, de la bonne volonté et de la disponibilité du Gouvernement pour mener à\nbien son mandat. Elle tient à lui exprimer sa gratitude."},{"id":"a-hrc-54-76-p0104","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"104","seq":106,"section":"A. Conclusions","text":"L’Équipe d’experts internationaux se félicite de la confiance, de la franchise et\nde la volonté de dialogue de la population, des chefs coutumiers, des autorités\nreligieuses, de la société civile et de la communauté internationale à Kinshasa et dans\nles provinces, qui ont partagé leurs expériences et leurs connaissances de la complexité\net des nuances de la situation en République démocratique du Congo. À cela s’ajoute le\nsoutien inestimable du BCNUDH, du système des Nations Unies et de la Mission de\nl’Organisation des Nations Unies pour la stabilisation en République démocratique du\nCongo, y compris les chefs de section et chefs de bureaux de terrain."},{"id":"a-hrc-54-76-p0105","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"105","seq":107,"section":"A. Conclusions","text":"L’Équipe d’experts internationaux observe que des recommandations issues de\nson précédent rapport ont commencé à être mises en œuvre."},{"id":"a-hrc-54-76-p0106","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"106","seq":108,"section":"A. Conclusions","text":"L’Équipe d’experts internationaux note à cet effet le recrutement de nouveaux\nmagistrats, dont une partie doit commencer sa formation initiale en août 2023. Ce\nrecrutement demeure insuffisant, par rapport aux besoins du pays. De plus, la\nformation initiale d’une durée prévue de trois mois devrait être suivie d’une formation\ncontinue étendue, au besoin, à tous les acteurs de la chaîne pénale."},{"id":"a-hrc-54-76-p0107","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"107","seq":109,"section":"A. Conclusions","text":"S’agissant de la justice juvénile, l’Équipe d’experts internationaux observe le\nmanque de magistrats spécialisés ainsi que de structures adéquates nécessaires à la\nréinsertion sociale des enfants auteurs ou victimes d’infractions. Il est indispensable de\npallier cette insuffisance."},{"id":"a-hrc-54-76-p0108","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"108","seq":110,"section":"A. Conclusions","text":"L’Équipe d’experts internationaux relève que l’insécurité croissante à l’intérieur\ndu pays compromet le déploiement des magistrats, accentuant ainsi l’absence de l’État\ndans certaines zones."},{"id":"a-hrc-54-76-p0109","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"109","seq":111,"section":"A. Conclusions","text":"Les progrès réalisés dans la province du Kasaï-Central confortent l’idée selon\nlaquelle l’approche complémentaire (niveau provincial et national) est la bonne, pourvu\nque la justice transitionnelle bénéficie d’un accompagnement suffisant de l’État et des\npartenaires. Cet exemple rendra crédible le processus et pourra convaincre les autres\nprovinces d’aller dans ce sens."},{"id":"a-hrc-54-76-p0110","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"110","seq":112,"section":"A. Conclusions","text":"L’une des faiblesses du processus de justice transitionnelle est l’insuffisance de\nla sensibilisation et de la communication, y compris dans la province du Kasaï-Central.\nCela pose le problème de son appropriation par les populations."},{"id":"a-hrc-54-76-p0111","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"111","seq":113,"section":"A. Conclusions","text":"Un manque d’harmonisation dans la mise en œuvre du processus de justice\ntransitionnelle a été constaté, y compris au niveau des partenaires d’appui. Or, pour\nqu’un processus de justice transitionnelle soit efficace et crédible, il faut qu’il y ait une\nharmonisation, une complémentarité et une cohérence des activités menées."},{"id":"a-hrc-54-76-p0112","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"112","seq":114,"section":"A. Conclusions","text":"La poursuite du processus de justice transitionnelle dans les zones en conflit est\npossible pourvu qu’il y ait des portes d’entrée devant conduire à un dialogue sur la\njustice transitionnelle et favoriser la cessation des hostilités. Cette démarche est\négalement possible même en période électorale."},{"id":"a-hrc-54-76-p0113","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"113","seq":115,"section":"A. Conclusions","text":"Toutes les initiatives de justice transitionnelle devraient intégrer une approche\nglobale incluant des mesures psychothérapeutiques pour faciliter la réinsertion\nsocioéconomique des victimes."},{"id":"a-hrc-54-76-p0114","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"114","seq":116,"section":"A. Conclusions","text":"Il est observé que l’entité de liaison des droits de l’homme créée par le décret\nno 09/35 du 12 août 2009 n’est toujours pas opérationnelle au niveau national."},{"id":"a-hrc-54-76-p0115","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"115","seq":117,"section":"A. Conclusions","text":"Les efforts consentis dans le cadre des initiatives sous-régionales sont très\nimportants et à saluer. Ces initiatives semblent principalement axées sur une réponse\ndiplomatique et sécuritaire. Il est indispensable qu’elles incorporent davantage la\ndimension des droits de l’homme et accordent une attention particulière aux mesures\njudiciaires et non judiciaires pour aboutir à une paix durable."},{"id":"a-hrc-54-76-p0116","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"116","seq":118,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux rappelle la nécessité de poursuivre la mise en\nœuvre des recommandations énoncées dans ses précédents rapports 16 . Elle réitère\nci-après certaines de ces recommandations et en formule de nouvelles."},{"id":"a-hrc-54-76-p0117","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"117","seq":119,"section":"1. Conceptualisation, articulation et stratégie de communication de la politique","text":"Afin de rendre visibles les efforts du Gouvernement et de faciliter\nl’appropriation du processus par la population, l’Équipe d’experts internationaux\nsouligne l’urgence d’une stratégie de communication appropriée sur la mise en œuvre\nde la justice transitionnelle et recommande au Gouvernement d’accorder une priorité\nà son élaboration."},{"id":"a-hrc-54-76-p0118","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"118","seq":120,"section":"1. Conceptualisation, articulation et stratégie de communication de la politique","text":"L’Équipe d’experts internationaux exhorte les autorités chargées de la mise en\nœuvre du Programme de désarmement, de démobilisation, de relèvement\ncommunautaire et de stabilisation à davantage collaborer avec les institutions\nnationales impliquées dans le processus de justice transitionnelle."},{"id":"a-hrc-54-76-p0119","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"119","seq":121,"section":"1. Conceptualisation, articulation et stratégie de communication de la politique","text":"L’Équipe d’experts internationaux invite le Gouvernement à poursuivre les\nconsultations populaires en veillant à leur conformité avec les normes internationales."},{"id":"a-hrc-54-76-p0120","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"120","seq":122,"section":"1. Conceptualisation, articulation et stratégie de communication de la politique","text":"L’Équipe d’experts internationaux invite le Ministère des droits humains à\nprocéder dans les meilleurs délais à la validation de son plan d’action en matière de\njustice transitionnelle."},{"id":"a-hrc-54-76-p0121","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"121","seq":123,"section":"1. Conceptualisation, articulation et stratégie de communication de la politique","text":"L’Équipe d’experts internationaux exhorte les autorités chargées de la mise en\nœuvre du Programme de désarmement, de démobilisation, de relèvement\ncommunautaire et de stabilisation et les partenaires à établir un équilibre entre, d’une\npart, les poursuites judiciaires, qui garantissent le droit des victimes à la justice et,\nd’autre part, les stratégies de resocialisation, qui favorisent un climat d’apaisement au\nsein des communautés."},{"id":"a-hrc-54-76-p0122","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"122","seq":124,"section":"2. Prévention de l’impunité","text":"L’Équipe d’experts internationaux recommande au Gouvernement de renforcer\nla formation initiale des magistrats par des formations continues, y compris dans le\ncadre d’une coopération Sud-Sud étendue si nécessaire aux autres acteurs judiciaires,\nnotamment les officiers de police judiciaire."},{"id":"a-hrc-54-76-p0123","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"123","seq":125,"section":"2. Prévention de l’impunité","text":"L’Équipe d’experts internationaux recommande au Conseil des droits de\nl’homme de maintenir la présence de l’équipe d’assistance technique et de renforcer ses\ncapacités par l’augmentation du nombre de ses membres et de leurs ressources,\ny compris des outils performants pouvant permettre la collecte des éléments de preuve\npour la justice et le travail de mémoire."},{"id":"a-hrc-54-76-p0124","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"124","seq":126,"section":"2. Prévention de l’impunité","text":"L’Équipe d’experts internationaux exhorte le Gouvernement et le Parlement à\nmettre en œuvre la feuille de route issue des travaux du colloque international sur les\nenjeux et défis de la médecine légale en République démocratique du Congo. Elle invite\nla communauté internationale à apporter tout son soutien à la République\ndémocratique du Congo en vue de la réalisation des objectifs de ce colloque."},{"id":"a-hrc-54-76-p0125","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"125","seq":127,"section":"2. Prévention de l’impunité","text":"L’Équipe d’experts internationaux recommande au Haut-Commissariat des\nNations Unies aux droits de l’homme de formaliser sa coopération institutionnelle avec\nle Réseau de coopération judiciaire de la région des Grands Lacs, afin de permettre à\nce dernier de bénéficier de l’appui du Haut-Commissariat."},{"id":"a-hrc-54-76-p0126","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"126","seq":128,"section":"3. Prise en compte des victimes dans toutes les phases du processus","text":"L’Équipe d’experts internationaux salue la création du FONAREV et invite le\nGouvernement à le rendre opérationnel dans les meilleurs délais."},{"id":"a-hrc-54-76-p0127","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"127","seq":129,"section":"3. Prise en compte des victimes dans toutes les phases du processus","text":"L’Équipe d’experts internationaux invite le Gouvernement à combiner, dans le\ncadre de la réparation non judiciaire, les mesures cliniques, l’appui\npsychothérapeutique et les actions de réinsertion sociale pour permettre aux victimes\nde se prendre en charge et de retrouver leur dignité."},{"id":"a-hrc-54-76-p0128","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"128","seq":130,"section":"4. Prévention des conflits et garanties de non-répétition","text":"L’Équipe d’experts internationaux recommande à nouveau au Gouvernement\nd’ajouter un plan de réforme de l’administration pour compléter les programmes\nactuels de réforme des secteurs sécuritaire et judiciaire, les trois réformes devant être\nmenées de front pour se renforcer mutuellement."},{"id":"a-hrc-54-76-p0129","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"129","seq":131,"section":"4. Prévention des conflits et garanties de non-répétition","text":"L’Équipe d’experts internationaux encourage le Gouvernement à mettre en\nplace un programme adéquat de formation de qualité pour ses cadres, en tenant compte\nnotamment du retrait progressif de la Mission de l’Organisation des Nations Unies pour\nla stabilisation en République démocratique du Congo et du besoin d’assurer la\ndurabilité des réformes en vue."},{"id":"a-hrc-54-76-p0130","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"130","seq":132,"section":"4. Prévention des conflits et garanties de non-répétition","text":"L’Équipe d’experts internationaux salue la prise en compte du caractère\ntransfrontalier des conflits et de l’insécurité par le processus de Nairobi. Elle\nrecommande aux différentes initiatives d’impliquer davantage la sous-région dans\nl’identification des causes des conflits et la prévention de leur répétition et, sans se\nlimiter aux seuls aspects politiques, diplomatiques et militaires, de renforcer la\ndimension de justice transitionnelle. Elle recommande également aux différents acteurs\nd’accroître leur coopération dans ce sens."},{"id":"a-hrc-54-76-p0131","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"131","seq":133,"section":"4. Prévention des conflits et garanties de non-répétition","text":"L’Équipe d’experts internationaux recommande aux différentes parties\nprenantes la mise en œuvre rapide des décisions, des recommandations et des\nconclusions issues des processus de Nairobi et de Luanda, et exhorte tous les groupes\narmés à un désarmement effectif. Elle réitère la nécessité de procéder au profilage des\nex-combattants."},{"id":"a-hrc-54-76-p0132","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"132","seq":134,"section":"4. Prévention des conflits et garanties de non-répétition","text":"L’Équipe d’experts internationaux recommande au Haut-Commissariat des\nNations Unies aux droits de l’homme de poursuivre ses efforts de renforcement des\ncapacités des Forces armées de la République démocratique du Congo dans les\ndomaines des droits de l’homme et du droit international humanitaire."},{"id":"a-hrc-54-76-p0133","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"133","seq":135,"section":"4. Prévention des conflits et garanties de non-répétition","text":"L’Équipe d’experts internationaux invite les partenaires au développement et la\ncommunauté internationale à accompagner le Gouvernement en prenant des actions\nurgentes et concertées allant dans le sens de la restauration de la paix et de l’équilibre\nsocial, afin de renforcer la protection des civils."},{"id":"a-hrc-54-76-p0134","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"134","seq":136,"section":"4. Prévention des conflits et garanties de non-répétition","text":"L’Équipe d’experts internationaux invite fortement le Gouvernement à rendre\nopérationnelle au niveau national l’entité de liaison des droits de l’homme en y intégrant\nla dimension de justice transitionnelle."},{"id":"a-hrc-54-76-p0135","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"135","seq":137,"section":"5. Financement public, privé et international du processus","text":"L’Équipe d’experts internationaux continue de déplorer la faiblesse des\nressources mises à disposition pour le processus de justice transitionnelle dans la région\ndu Kasaï, et réitère la nécessité d’un financement suffisant et durable de tous les volets\nde la justice transitionnelle."},{"id":"a-hrc-54-76-p0136","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"136","seq":138,"section":"5. Financement public, privé et international du processus","text":"Tout en saluant les partenariats noués entre la Commission provinciale vérité,\njustice et réconciliation au Kasaï-Central et le BCNUDH, l’Équipe d’experts\ninternationaux encourage les autres bailleurs de fonds à faire de même afin d’assurer\nde façon cohérente le succès du processus de justice transitionnelle dans la province du\nKasaï-Central."},{"id":"a-hrc-54-76-p0137","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"137","seq":139,"section":"5. Financement public, privé et international du processus","text":"L’Équipe d’experts internationaux exhorte à nouveau le Gouvernement à\nredoubler d’efforts pour assurer, aux niveaux provincial et national, le financement par\nle budget national de ses initiatives pour la justice transitionnelle et la réforme de l’État.\nCes efforts financiers renforceront la volonté politique réitérée par le Gouvernement,\nassureront la mise en œuvre immédiate et durable des projets de justice transitionnelle,\net encourageront une participation accrue à leur financement par la coopération\nbilatérale et multilatérale."},{"id":"a-hrc-54-76-p0138","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"138","seq":140,"section":"5. Financement public, privé et international du processus","text":"L’Équipe d’experts internationaux recommande au Gouvernement d’élaborer\nune politique qui organiserait la contribution des entreprises nationales comme\nmultinationales actives en République démocratique du Congo au financement des\ninitiatives de paix, de réconciliation, de stabilité et de développement durable."},{"id":"a-hrc-57-81-p0001","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"1","seq":0,"section":"I. Introduction","text":"In resolution 54/34 of 12 October 2022, the Human Rights Council renewed the\nmandate of the team of international experts on the Democratic Republic of the Congo and\nrequested the team to provide the necessary technical support to the Government in its\nimplementation of the national policy on transitional justice. The Council also requested the\nteam of international experts to submit its final report to the Council, in the framework of an\nenhanced interactive dialogue, at its fifty-seventh session, and to present an oral update at its\nfifty-fifth session. The present report is part of the implementation of the above-mentioned\nresolution."},{"id":"a-hrc-57-81-p0002","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"2","seq":1,"section":"I. Introduction","text":"In the resolution, the Human Rights Council requested the United Nations High\nCommissioner for Human Rights to continue providing technical assistance, including the\nnecessary forensic expertise, to the Government in order to support the judicial authorities in\ntheir investigations into allegations of human rights violations and abuses, including conflict-\nrelated sexual violence and serious violations of children's rights, with a view to bringing\nthose responsible to justice."},{"id":"a-hrc-57-81-p0003","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"3","seq":2,"section":"I. Introduction","text":"On 12 October 2023, the High Commissioner for Human Rights renewed the\nmandates of Marie-Th�r�se Keita-Bocoum (C�te d'Ivoire) and Bessol� Ren� Bagoro\n(Burkina Faso) as, respectively, chair and member of the team of international experts."},{"id":"a-hrc-57-81-p0004","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"4","seq":3,"section":"I. Introduction","text":"The team of international experts is supported by a secretariat comprising a\ncoordinator and a human rights officer specializing in transitional justice. In 2024, it made\ntwo field visits to the Democratic Republic of the Congo, from 24 to 30 March and 20 to\n30 July."},{"id":"a-hrc-57-81-p0005","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"5","seq":4,"section":"I. Introduction","text":"During these visits, the team of international experts met with a number of officials,\nincluding the Minister of State and the Minister of Justice and Keeper of the Seals; the\nMinister of Human Rights; the President of the National Human Rights Commission; the\nPermanent Secretary of the human rights liaison body; the members of the Commission on\nTruth, Justice and Reconciliation of Kasai Central Province; the focal point for transitional\njustice of the Disarmament, Demobilization, Community Recovery and Stabilization\nProgramme and the Special Representative of the Secretary-General for the Democratic\nRepublic of the Congo and the Head of MONUSCO; members of United Nations system\nentities; and members of the diplomatic corps accredited in the Democratic Republic of the\nCongo, including the Deputy Head of Mission of the Belgian Embassy and the Ambassador\nof Burundi. In its discussions with interlocutors, the team of international experts enquired\nabout progress made in the fight against impunity and the implementation of transitional\njustice."},{"id":"a-hrc-57-81-p0006","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"6","seq":5,"section":"I. Introduction","text":"On its second visit, the team of international experts took part in the inauguration of\nthe first forensic thanatology centre in the Democratic Republic of the Congo, in Bukavu,\nSouth Kivu Province, on 23 July 2024. On 24 and 25 July 2024, it took part in a workshop,\nin which all relevant actors also took part, to assess the implementation of the\nrecommendations contained in Human Rights Council resolution 54/34."},{"id":"a-hrc-57-81-p0007","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"7","seq":6,"section":"I. Introduction","text":"In accordance with Human Rights Council resolution 54/34, on 2 April 2024, the team\nof international experts gave an oral update on the situation in the Democratic Republic of\nthe Congo at the interactive dialogue held during the Council's fifty-fifth session."},{"id":"a-hrc-57-81-p0008","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"8","seq":7,"section":"I. Introduction","text":"The present report is submitted in accordance with Human Rights Council resolution\n54/34. It highlights the various activities undertaken by the team of international experts in\nfulfilment of its expanded mandate."},{"id":"a-hrc-57-81-p0009","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"9","seq":8,"section":"II. Mandate","text":"The mandate of the team of international experts was implemented against a backdrop\nof ongoing instability in the east of the country, owing to the expansion of the Mouvement\ndu 23 mars (M23), the persistent presence of several armed groups in the region and the\nhumanitarian crisis, and in the run-up to the general elections in December 2023."},{"id":"a-hrc-57-81-p0010","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"10","seq":9,"section":"II. Mandate","text":"The mandate was also implemented in parallel with the withdrawal of MONUSCO.\nIn addition, the financial situation of the United Nations had a negative impact on the\nfulfilment of the mandate of the team of international experts, forcing it to forgo several field\nvisits, including to Nairobi to continue the technical work begun with the Special Envoy of\nthe Secretary-General for the Great Lakes Region."},{"id":"a-hrc-57-81-p0011","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"11","seq":10,"section":"II. Mandate","text":"Notwithstanding this situation, the team of international experts was able to conduct\ntwo field visits to the Democratic Republic of the Congo and provide significant support to\nthe Government. The team of international experts would particularly like to thank the Office\nof the United Nations High Commissioner for Human Rights and the United Nations Joint\nHuman Rights Office in the Democratic Republic of the Congo (UNJHRO) for all their\nefforts to enable it to fulfil its mandate, especially for their mission support."},{"id":"a-hrc-57-81-p0012","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"12","seq":11,"section":"III. Cooperation between the team of international experts and","text":"Throughout its mandate, the team of international experts enjoyed direct and close\ncollaboration with the authorities of the Democratic Republic of the Congo, thus enabling it\nto carry out its work successfully."},{"id":"a-hrc-57-81-p0013","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"13","seq":12,"section":"III. Cooperation between the team of international experts and","text":"The team of international experts notes the establishment of a new government and\nthe appointment of new institutional representatives in May 2024, following the confirmation\nof the results of the presidential election on 9 January 2024, and their readiness to continue\nstrengthening the fight against impunity and respect for human rights."},{"id":"a-hrc-57-81-p0014","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"14","seq":13,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts remains concerned by the continued deterioration of\nthe security situation in the east of the country. The intensification of the conflict linked to\nthe M23 offensive, with the increased involvement of multiple actors, including countries in\nthe region,1 and the armed groups Wazalendo and Volontaires pour la d�fense de la patrie,\nhas led to serious human rights violations and abuses against civilians and a real risk of a\nregional conflict.2 The team of international experts notes that a two-week humanitarian truce\nwas announced in early July 2024, followed by a ceasefire agreement between the\nDemocratic Republic of the Congo and Rwanda, facilitated by the President of Angola and\nmade public on 31 July 2024.3"},{"id":"a-hrc-57-81-p0015","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"15","seq":14,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts is concerned that the withdrawal of MONUSCO\nfrom South Kivu Province, which was completed on 30 June 2024 at the request of the\nGovernment, has not been followed by a meaningful strengthening of the capacities of the\nCongolese armed and security forces, thus creating a security vacuum in certain areas and\nincreasing the vulnerability of the civilian population."},{"id":"a-hrc-57-81-p0016","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"16","seq":15,"section":"IV. Current security and humanitarian situation in the","text":"In North Kivu and Ituri Provinces, murderous attacks by the Allied Democratic\nForces, the Coop�rative pour le d�veloppement du Congo and various Mai-Mai armed groups\nhave adversely affected the human rights situation.4"},{"id":"a-hrc-57-81-p0017","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"17","seq":16,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts deplores the persistence of inter-community\nconflicts, particularly in the country's western provinces. In Mai-Ndombe Province, it notes\nthat despite the signing on 6 April 2024 of a deed of commitment by certain community\nleaders, in the presence of the President, to cease hostilities and move towards a peaceful\ndispute settlement, groups of armed Mobondo civilians remain active, as do military\noperations, heightening the vulnerability of civilian populations.5 It is concerned about the\nhumanitarian crisis faced by civilians, particularly displaced persons, in areas that are\ndifficult to access and poorly covered by humanitarian actors."},{"id":"a-hrc-57-81-p0018","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"18","seq":17,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts also deplores the outbreak of land-related\ninter-community conflict in Tshopo Province, between the Mbole and Lengola communities,\nwhich as has caused several deaths, massive population displacement and the destruction of\ndozens of homes.6"},{"id":"a-hrc-57-81-p0019","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"19","seq":18,"section":"IV. Current security and humanitarian situation in the","text":"On the humanitarian front, the team of international experts notes that the Democratic\nRepublic of the Congo is facing one of the world's largest displacement crises. The number\nof displaced people has risen sharply to 7.4 million, mainly in Ituri, North Kivu and South\nKivu Provinces.7"},{"id":"a-hrc-57-81-p0020","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"20","seq":19,"section":"IV. Current security and humanitarian situation in the","text":"The problem of how to access populations in need has become much more acute due\nto insecurity resulting from, among other things, attacks on humanitarian actors, some of\nwhich have been deadly,8 the absence or poor state of the road network, and administrative\nobstacles."},{"id":"a-hrc-57-81-p0021","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"21","seq":20,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts is concerned about the growing risk of armed-\nconflict-related sexual violence, especially with the intensification of armed violence in\nNorth Kivu Province. It noted cases of pregnancy resulting from rape.9"},{"id":"a-hrc-57-81-p0022","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"22","seq":21,"section":"V. Implementation of the mandate of the team of international","text":"The main purpose of the mandate of the team of international experts is to provide the\nGovernment with the technical support necessary to implement a national transitional justice\nprocess focused on the needs of victims and on strengthening the fight against impunity."},{"id":"a-hrc-57-81-p0023","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"23","seq":22,"section":"A. Fight against impunity","text":"With regard to the fight against impunity, the team of international experts continued\nto observe the administration of justice in the Democratic Republic of the Congo, including\nin emblematic legal cases, particularly those opened in connection with the crisis linked to\nthe Kamuina Nsapu militia, not to mention monitor the situation of victims."},{"id":"a-hrc-57-81-p0024","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"24","seq":23,"section":"1. Administration of justice in the Democratic Republic of the Congo","text":"The team of international experts notes with satisfaction the Government's efforts in\ncombating impunity, in particular its efforts to improve the administration of justice, both at\nthe judicial and prison levels."},{"id":"a-hrc-57-81-p0025","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"25","seq":24,"section":"1. Administration of justice in the Democratic Republic of the Congo","text":"On the judicial front, the team of international experts notes that the first half of the\n5,000 judges recruited in November 2022 was effectively trained in April 2024 and has been\ndeployed across the country. It welcomes the support of international partners, including\nUNJHRO, in the preparation and conduct of this training organized by the Supreme Council\nof Justice.\n5 UNJHRO, weekly note on the situation of human rights, 11�17 May 2024.\n6 UNJHRO, annual report on the situation of human rights, 1 January�31 December 2023; UNJHRO,\nmonthly analysis on the situation of human rights, January 2024; and UNJHRO, monthly analysis of\nthe situation of human rights, March 2024.\n7 MONUSCO, MONUSCO fact sheet (briefing to the Security Council), June 2024.\n8 Ibid. See also Office of the Humanitarian Coordinator in the Democratic Republic of the Congo, \"Le\nCoordonnateur humanitaire condamne l'attaque contre un convoi humanitaire et d�plore la mort de\ndeux travailleurs humanitaires � Butembo au Nord-Kivu\" (\"Humanitarian Coordinator condemns\nattack on humanitarian convoy and deplores death of two aid workers in Butembo, North Kivu\"),\npress release, 2 July 2024.\n9 UNJHRO, monthly analysis on the situation of human rights, February 2024."},{"id":"a-hrc-57-81-p0026","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"26","seq":25,"section":"1. Administration of justice in the Democratic Republic of the Congo","text":"The team of international experts congratulates the Government and the judicial\nauthorities on this important step forward, which is in line with a recommendation in its\nprevious report.10 It calls on the Government to continue the initial training of the other 2,500\njudges recruited in 2022, in order to meet the recruitment target set by the Government of\n10,000 magistrates by 2025."},{"id":"a-hrc-57-81-p0027","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"27","seq":26,"section":"1. Administration of justice in the Democratic Republic of the Congo","text":"The team of international experts invites the Government to continue its efforts to\nmake initial and in-service training, particularly in the investigation and prosecution of\ninternational crimes, systematic for members of the judiciary, including by building the\ncapacities of the National Judicial Training Institute and taking advantage of South-South\ncooperation where necessary. In addition, it stresses the need to deploy judges trained in the\njudicial response to serious offences, including conflict-related sexual violence, to the areas\nconcerned."},{"id":"a-hrc-57-81-p0028","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"28","seq":27,"section":"1. Administration of justice in the Democratic Republic of the Congo","text":"The team of international experts notes the predominant role of the military courts in\nthe judicial response to international crimes. It calls on the Government to undertake the\nreforms necessary to increase the involvement of civil courts, in line with international\nstandards and instruments."},{"id":"a-hrc-57-81-p0029","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"29","seq":28,"section":"1. Administration of justice in the Democratic Republic of the Congo","text":"On the prison front, the team of international experts welcomes the adoption\non 15 June 2023 of Act No. 23/028 on the fundamental principles of the prison system, and\ncalls for its full and effective implementation."},{"id":"a-hrc-57-81-p0030","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"30","seq":29,"section":"1. Administration of justice in the Democratic Republic of the Congo","text":"The team of international experts calls in particular for measures to be taken regarding\nthe rehabilitation and construction of detention centres and for the establishment of a\nfunctioning general directorate of prison administration to improve conditions of detention,\nreduce the mortality rate in prisons and ensure respect for prisoners' rights."},{"id":"a-hrc-57-81-p0031","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"31","seq":30,"section":"1. Administration of justice in the Democratic Republic of the Congo","text":"From 24 to 30 March 2024 in Kinshasa, the team of international experts met with the\nMinister of Human Rights, the Minister of State, the Minister of Justice and Keeper of the\nSeals, members of the previous Administration and with the President of the National Human\nRights Commission. At these various meetings, the team expressed its deep concern at the\nGovernment's decision to lift the moratorium on enforcement of the death penalty amid\ngrowing consensus about universal abolition of the death penalty."},{"id":"a-hrc-57-81-p0032","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"32","seq":31,"section":"1. Administration of justice in the Democratic Republic of the Congo","text":"In response to the concerns expressed by the team of international experts, the\nauthorities indicated that the reinstatement of the death penalty was a strategic measure aimed\nat restoring discipline within the army by, inter alia, preventing acts of treason."},{"id":"a-hrc-57-81-p0033","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"33","seq":32,"section":"1. Administration of justice in the Democratic Republic of the Congo","text":"Following these exchanges, the team of international experts was left with the strong\nimpression that the measure was due to circumstances and had been taken for dissuasive\npurposes but that it could nonetheless be implemented if a situation warranted it."},{"id":"a-hrc-57-81-p0034","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"34","seq":33,"section":"1. Administration of justice in the Democratic Republic of the Congo","text":"The team of international experts urged the authorities to reverse the decision to lift\nthe moratorium on enforcement of the death penalty, to ratify the Second Optional Protocol\nto the International Covenant on Civil and Political Rights, aiming at the abolition of the\ndeath penalty, and to complete the legislative process to abolish the death penalty in the\nDemocratic Republic of the Congo."},{"id":"a-hrc-57-81-p0035","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"35","seq":34,"section":"1. Administration of justice in the Democratic Republic of the Congo","text":"The establishment of a special criminal court was also raised during the discussions\nof the team of international experts with the Minister of Justice and the President of the\nNational Human Rights Commission. This matter has already been raised several times in\nexchanges between the team of international experts and some of its interlocutors during its\nrecent visits to the country. The team of international experts has taken due note."},{"id":"a-hrc-57-81-p0036","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"36","seq":35,"section":"2. Monitoring judicial cases","text":"The team of international experts is concerned about the lack of progress in the judicial\ncases concerning the crisis linked to the Kamuina Nsapu militia."},{"id":"a-hrc-57-81-p0037","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"37","seq":36,"section":"2. Monitoring judicial cases","text":"The team of international experts notes that, of the 16 emblematic cases opened in this\nconnection, 5 have not yet been investigated, 9 remain under investigation and 2 remain in\nthe trial phase, namely, the Mulombodi case and that of the assassination of the two\nUnited Nations experts, Zaida Catal�n and Michael Sharp."},{"id":"a-hrc-57-81-p0038","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"38","seq":37,"section":"2. Monitoring judicial cases","text":"The team of international experts notes that an appeal hearing continues before the\nMilitary High Court in the case of the assassination of the two United Nations experts. It\nfurther notes that investigations are ongoing in the Moyo Musuila case concerning the four\npeople who were accompanying the United Nations experts."},{"id":"a-hrc-57-81-p0039","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"39","seq":38,"section":"2. Monitoring judicial cases","text":"The team of international experts is concerned by the slow progress of these cases,\nespecially as four defendants have already died.11"},{"id":"a-hrc-57-81-p0040","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"40","seq":39,"section":"2. Monitoring judicial cases","text":"The team of international experts encourages the judicial authorities to continue these\nlegal proceedings in order to establish the truth, assign responsibility for the offences\ncommitted in Kasai-Central Province during the crisis linked to the Kamuina Nsapu militia\nand realize the victims' right to justice. The team invites the Government, with the support\nof its partners, to continue building the capacity of professionals in the criminal justice system\nto investigate and prosecute international crimes in order to speed up and strengthen the\njudicial response."},{"id":"a-hrc-57-81-p0041","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"41","seq":40,"section":"2. Monitoring judicial cases","text":"The team of international experts is concerned about the impact that the withdrawal\nof MONUSCO might have on the fight against impunity, for instance by slowing down or\neven hindering the judicial response. There is no doubt that the logistical support provided\nby MONUSCO is essential for successfully organizing investigative missions and mobile\ncourt hearings and for facilitating access to the judicial system for victims and witnesses."},{"id":"a-hrc-57-81-p0042","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"42","seq":41,"section":"2. Monitoring judicial cases","text":"In Kasai-Central Province, for example, the judicial authorities with which the team\nmet mentioned that the loss of the MONUSCO-led consultation framework to support\ninternational criminal justice had resulted in loss of support for the judicial authorities and\nhad had a negative impact on the judicial response, in the absence of an increase in the human,\ntechnical and logistical resources provided by the Government."},{"id":"a-hrc-57-81-p0043","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"43","seq":42,"section":"2. Monitoring judicial cases","text":"The team of international experts calls on the Government to strengthen its support to\nthe judicial authorities, particularly in provinces from which MONUSCO has already\nwithdrawn, and asks international partners to support these efforts as well as those of\nUnited Nations entities, including UNJHRO, aimed at strengthening the judicial response to\nserious violations and abuses of international human rights law and international\nhumanitarian law."},{"id":"a-hrc-57-81-p0044","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"44","seq":43,"section":"2. Monitoring judicial cases","text":"Notwithstanding the above-mentioned challenges, the team of international experts\ntakes note of the efforts made by the Government and the military justice system to combat\nimpunity through the adoption of certain judicial decisions."},{"id":"a-hrc-57-81-p0045","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"45","seq":44,"section":"2. Monitoring judicial cases","text":"In this regard, the team of international experts notes that, since October 2023,\n343 people � 38 officers of the Armed Forces of the Democratic Republic of the Congo,\n18 officers of the Congolese National Police, 223 members of armed groups and 64 civilians\n� have been convicted of offences related to violations of human rights and international\nhumanitarian law. Most of these convictions were handed down by military courts. For\nexample, in June 2024, the military court of South Kivu confirmed the conviction of three\nleaders of armed groups, who committed human rights violations, for environmental offences\nand crimes against humanity through forced pregnancy."},{"id":"a-hrc-57-81-p0046","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"46","seq":45,"section":"2. Monitoring judicial cases","text":"The team of international experts welcomes the significant contribution of the Office\nof the United Nations High Commissioner for Human Rights to supporting the judicial\nauthorities in the fight against impunity, thanks to the expertise in forensic medicine and\nforensic psychology shared by the technical assistance team deployed to UNJHRO."},{"id":"a-hrc-57-81-p0047","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"47","seq":46,"section":"2. Monitoring judicial cases","text":"The team of international experts also welcomes the progress made in implementing\nthe road map and recommendations under the Kinshasa Declaration adopted at the\ninternational symposium on the issues at stake and challenges in the field of forensic\nmedicine in the Democratic Republic of the Congo, held in Kinshasa in July 2023. It notes\nthat the University of Kinshasa, with technical and financial support from UNJHRO,\n11 A general prosecuted in the Mulombodi case and three defendants in the case of the assassination of\nthe two United Nations experts have died in custody.\norganized a workshop from 14 to 19 May 2024 on the preparation of skills and job profiles\nfor the establishment of a forensic medicine training programme in the country's universities.\nOn 31 May 2024, thanks to the advocacy and support of the technical assistance team, the\nCongolese College of Physicians sent to four doctors, including one woman, a letter of\nnotification officially awarding them the title of forensic doctor recognized by their peers\nand, by extension, by the State."},{"id":"a-hrc-57-81-p0048","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"48","seq":47,"section":"2. Monitoring judicial cases","text":"In Bukavu, South Kivu Province, the technical assistance team supported the\nconstruction and inauguration of a forensic medicine centre for the living in November 2023,\nand the equipping and operationalization of the first forensic thanatology centre in the\nDemocratic Republic of the Congo, inaugurated on 23 July 2024. The team of international\nexperts welcomes the establishment of a forensic medicine and thanatology centre in\nKananga, with support from the World Bank."},{"id":"a-hrc-57-81-p0049","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"49","seq":48,"section":"2. Monitoring judicial cases","text":"The team of international experts encourages the Government to continue its efforts\nto realize the road map and the recommendations contained in the Kinshasa Declaration, with\nexpert advice from the technical assistance team. This progress, anchored in a sustainable\napproach and focused on the development of national forensic expertise, goes some way\ntowards fulfilling one of the recommendations made in the previous report of the team of\ninternational experts."},{"id":"a-hrc-57-81-p0050","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"50","seq":49,"section":"2. Monitoring judicial cases","text":"The team of international experts invites all international partners to support the\nCongolese Government's efforts in this area with a view to improving criminal\ninvestigations, strengthening the fight against impunity and ensuring better access to justice\nfor victims."},{"id":"a-hrc-57-81-p0051","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"51","seq":50,"section":"3. Situation of victims","text":"The team of international experts notes with satisfaction that the concerns of victims\nhave been taken into account through the promulgation of Act No. 22/065 of 26 December\n2022 on the fundamental principles of protection and redress for victims of conflict-related\nsexual violence and victims of crimes against the peace and security of humankind, pursuant\nto which registration and legal fees have been abolished for victims of such offences."},{"id":"a-hrc-57-81-p0052","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"52","seq":51,"section":"3. Situation of victims","text":"The team of international experts notes that, on the basis of Act No. 22/065, victims\nwho had sued for damages in criminal proceedings had been exempted from legal fees in two\njudgments handed down in Kasai-Central and Ituri Provinces in August and December 2023,\nthus setting positive precedent."},{"id":"a-hrc-57-81-p0053","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"53","seq":52,"section":"3. Situation of victims","text":"The team of international experts encourages the State to widely disseminate the\nprovisions of Act No. 22/065 among judicial authorities and potential beneficiaries, to ensure\nthat all its provisions strengthening victims' access to justice and judicial reparations are\nsystematically invoked in all future proceedings."},{"id":"a-hrc-57-81-p0054","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"54","seq":53,"section":"3. Situation of victims","text":"The team of international experts welcomes the decision by the military judicial\nauthorities to request, under Act No. 22/065, that 120 victims undergo a medical and\npsychological assessment by the forensic psychology experts of the technical assistance team\nas part of the ongoing investigations in the Mulombodi and Nganza cases."},{"id":"a-hrc-57-81-p0055","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"55","seq":54,"section":"3. Situation of victims","text":"The team of international experts calls for a full medical and psychological assessment\nof victims taking part in legal proceedings to be systematically requested, at any point in the\nproceedings, such that psychological harm may be taken into account more effectively,\nincluding in the determination of reparation measures. It invites the Government to broaden\nthe legal basis for the judicial authorities to request such assessments, so that they can be\nused to support victims of serious human rights violations not covered under Act No. 22/065."},{"id":"a-hrc-57-81-p0056","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"56","seq":55,"section":"1. Monitoring the implementation of the transitional justice process in Kasai-Central","text":"The team of international experts notes with satisfaction the ongoing support provided\nto the Truth, Justice and Reconciliation Commission of Kasai-Central Province during its\nlaunch and preparatory phase. In particular, it welcomes the support provided by UNJHRO,\nwhich facilitated the renovation of the Commission's headquarters and made it possible for\nthe Office of the United Nations High Commissioner for Human Rights to continue providing\na transitional justice expert."},{"id":"a-hrc-57-81-p0057","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"57","seq":56,"section":"1. Monitoring the implementation of the transitional justice process in Kasai-Central","text":"The team of international experts appreciates the continued implementation of the\npartnership agreement between the Truth, Justice and Reconciliation Commission of Kasai-\nCentral Province and the non-governmental organization TRIAL International, as well as the\ndetermination expressed by the United Nations Entity for Gender Equality and the\nEmpowerment of Women (UN-Women) to boost its support to the Commission."},{"id":"a-hrc-57-81-p0058","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"58","seq":57,"section":"1. Monitoring the implementation of the transitional justice process in Kasai-Central","text":"The team of international experts notes that the enhanced synergies between itself and\nTRIAL International, UN-Women and UNJHRO enabled them to assist the Truth, Justice\nand Reconciliation Commission of Kasai-Central Province in developing, as early as\nNovember 2023, a technical partnership with 15 civil society organizations and the judicial\nauthorities based in Kananga and in finalizing the legal and strategic instruments regarding\nits operations in May 2024."},{"id":"a-hrc-57-81-p0059","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"59","seq":58,"section":"1. Monitoring the implementation of the transitional justice process in Kasai-Central","text":"The team of international experts invites the Commission's partners to establish a\ncooperation framework to strengthen their coordination and the complementarity of their\nsupport efforts. It also calls on the provincial government of Kasai-Central to support the\neffective operationalization of the consultation framework it established with the\nCommission on 25 July 2023."},{"id":"a-hrc-57-81-p0060","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"60","seq":59,"section":"1. Monitoring the implementation of the transitional justice process in Kasai-Central","text":"The team of international experts commends the Provincial Assembly of Kasai-\nCentral for renewing the mandate of the Commission on 18 July 2024. It calls on the\nprovincial government of Kasai-Central to promulgate the draft edict renewing the\nCommission's mandate for a further three years."},{"id":"a-hrc-57-81-p0061","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"61","seq":60,"section":"1. Monitoring the implementation of the transitional justice process in Kasai-Central","text":"The team of international experts encourages the Truth, Justice and Reconciliation\nCommission of Kasai-Central Province to complete the pilot phase of its investigations in the\ncity of Kananga as soon as possible, then expand its operations to the Province's five\nterritories."},{"id":"a-hrc-57-81-p0062","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"62","seq":61,"section":"1. Monitoring the implementation of the transitional justice process in Kasai-Central","text":"During its discussions with the commissioners, the team of international experts noted\nthe significant impact that the lack of State funding was having on the fulfilment of the\nmandate of the Truth, Justice and Reconciliation Commission of Kasai-Central Province."},{"id":"a-hrc-57-81-p0063","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"63","seq":62,"section":"1. Monitoring the implementation of the transitional justice process in Kasai-Central","text":"The team of international experts continues to encourage the Governor of Kasai-\nCentral Province to allocate the resources necessary for the Commission to plan and\neffectively launch its investigations, among other activities. It also invites the national\nGovernment to provide supplemental financial support to the Commission."},{"id":"a-hrc-57-81-p0064","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"64","seq":63,"section":"1. Monitoring the implementation of the transitional justice process in Kasai-Central","text":"The team of international experts welcomes the financial support provided by\ninternational partners, particularly UNJHRO, to the Truth, Justice and Reconciliation\nCommission of Kasai-Central Province. It notes especially the commitment of the\nPeacebuilding Fund to support the operations of the Commission over the next three years.\nThe team of international experts invites other donors to step up their support for the\ntransitional justice process in Kasai-Central Province."},{"id":"a-hrc-57-81-p0065","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"65","seq":64,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts welcomes the President's determination to place the\nkey objectives of transitional justice at the heart of the presidential programme for his second\nterm. It encourages the Government to take greater account of transitional justice in its\nprogramme of action for the period 2024�2028."},{"id":"a-hrc-57-81-p0066","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"66","seq":65,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts notes that the organization and holding of the 2023\ngeneral elections slowed the progress of the transitional justice process. It remains convinced\nthat the installation of the Government will further strengthen commitment to this process."},{"id":"a-hrc-57-81-p0067","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"67","seq":66,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts commends the Government's efforts to revitalize\nand operationalize the human rights liaison body, a government monitoring, warning and\nadvocacy mechanism in the area of human rights, including transitional justice."},{"id":"a-hrc-57-81-p0068","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"68","seq":67,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts welcomes the technical and financial support that it\nand UNJHRO provided for the first ordinary meeting of the human rights liaison body, held\non 16 November 2023, which marked the official launch of the body's activities and resulted\nin an amendment to Decree No. 09/35 of 12 August 2009 on the establishment, organization\nand functioning of the body to, inter alia, add monitoring of the transitional justice process\nto the its remit. The team encourages the Government to promulgate the amended decree and\ncontinue the operationalization of the body."},{"id":"a-hrc-57-81-p0069","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"69","seq":68,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts also welcomes the deployment by the Office of the\nUnited Nations High Commissioner for Human Rights of a human rights officer specializing\nin transitional justice within the Ministry of Human Rights to support the Ministry's\nimplementation of the transitional justice process."},{"id":"a-hrc-57-81-p0070","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"70","seq":69,"section":"2. Implementation of the transitional justice process at the national level","text":"This support enabled the Ministry of Human Rights, in collaboration with UNJHRO,\nthe team of international experts and UN-Women, to validate its strategic action plan for\nhuman rights and transitional justice in August 2023. The team of international experts invites\nthe Government and its partners to support the implementation of the strategic action plan."},{"id":"a-hrc-57-81-p0071","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"71","seq":70,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts notes with satisfaction that the National Reparations\nFund for Victims of Conflict-Related Sexual Violence and Other Crimes against the Peace\nand Security of Humankind in the Democratic Republic of the Congo (FONAREV) and the\nInter-Institutional Commission for Assistance to Victims and Support for Reforms (CIA-\nVAR), responsible for overseeing the development of reparations programmes by\nFONAREV, are now operational."},{"id":"a-hrc-57-81-p0072","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"72","seq":71,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts appreciates the collaboration among FONAREV,\nCIA-VAR and UNJHRO, which in May 2023 facilitated an exchange of expertise, in the\nframework of South-South cooperation, with experts from the Victims Trust Fund of the\nInternational Criminal Court and other international experts. It notes with satisfaction the\ndeepening of such cooperation during a study visit to C�te d'Ivoire by a FONAREV\ndelegation in June 2024, organized with support from UNJHRO."},{"id":"a-hrc-57-81-p0073","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"73","seq":72,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts welcomes the operational launch of the Special\nReparations and Compensation Fund for Victims of Illicit Activities by Uganda (FRIVAO),\nwhich is mandated to administer the reparations awarded by the International Court of Justice\nto Congolese victims of harm caused by Uganda during the armed conflict from August 1998\nto June 2003.12"},{"id":"a-hrc-57-81-p0074","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"74","seq":73,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts stresses that it is essential for ongoing reparations\nprojects to be implemented in a transparent manner to ensure that these transitional justice\ninitiatives effectively contribute to boosting the population's confidence in the State and\npromoting national reconciliation."},{"id":"a-hrc-57-81-p0075","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"75","seq":74,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts calls on FONAREV and FRIVAO, with the support\nof their respective lead ministries, to continue developing reparations programmes that are\nfocused on the needs of victims, facilitate access to different forms of individual and\ncollective reparations13 and promote the social reintegration of victims."},{"id":"a-hrc-57-81-p0076","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"76","seq":75,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts also calls on FONAREV and FRIVAO to work with\nUNJHRO and other international partners to strengthen experience-sharing initiatives in the\ncontext of South-South cooperation."},{"id":"a-hrc-57-81-p0077","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"77","seq":76,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts welcomes the determination of the Disarmament,\nDemobilization, Community Recovery and Stabilization Programme to foster synergies\nbetween it and ongoing transitional justice initiatives. It also welcomes the appointment by\nthe Programme of a transitional justice focal point and the organization in June 2024, with\nsupport from UNJHRO, of a workshop on the links between the Programme and transitional\njustice."},{"id":"a-hrc-57-81-p0078","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"78","seq":77,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts takes note of the development by the Disarmament,\nDemobilization, Community Recovery and Stabilization Programme of an initial proposal\nfor a screening procedure. Such a procedure would be essential to ensure that the Programme\ndoes not become a mechanism for promoting impunity and to strike a balance between\ncommunity reintegration strategies for former combatants and respect for victims' rights."},{"id":"a-hrc-57-81-p0079","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"79","seq":78,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts calls on the Government and its partners to step up\ntheir technical and financial support to accelerate the implementation of the Disarmament,\nDemobilization, Community Recovery and Stabilization Programme and the development of\nsynergies between the Programme and transitional justice initiatives at the national and\nsubregional levels."},{"id":"a-hrc-57-81-p0080","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"80","seq":79,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts notes with interest the intensification of official\ncommunications around transitional justice initiatives, including the celebration of the\nnational day of homage to victims of conflict-related sexual violence and to victims of crimes\nagainst the peace and security of humankind,14 commonly known as \"Genocost\"."},{"id":"a-hrc-57-81-p0081","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"81","seq":80,"section":"2. Implementation of the transitional justice process at the national level","text":"The team of international experts encourages the Government to increase\ncommunication and awareness-raising initiatives on transitional justice, in various local\nlanguages, that are focused on the needs and perspectives of victims and respect their dignity\nand the \"do no harm\" principle. This is essential to strengthen the impact of these initiatives\non all communities and to help victims take ownership of and participate in them."},{"id":"a-hrc-57-81-p0082","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"82","seq":81,"section":"3. Challenges in the implementation of the transitional justice process in the Democratic","text":"The team of international experts identified four major challenges concerning the\ntransitional justice process: (a) the lack of consistent and coordinated design and\nimplementation of transitional justice initiatives based on an overall vision focused on the\nneeds of victims; (b) the lack of sufficient effective funding to implement the transitional\njustice process; (c) the fact that transitional justice is being applied in a context of insecurity\nand inter-community conflicts; and (d) the growing impact of the cross-border dimension of\nconflicts.\n(a) Lack of consistent and coordinated design and implementation of transitional justice\ninitiatives based on an overall vision focused on the needs of victims"},{"id":"a-hrc-57-81-p0083","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"83","seq":82,"section":"3. Challenges in the implementation of the transitional justice process in the Democratic","text":"The team of international experts reiterates that weakness in the coordination of\ntransitional justice initiatives, at both national and provincial levels, is an obstacle to the\nrealization of a comprehensive transitional justice process that is focused on the needs of\nvictims and effectively contributes to peace, the strengthening of the rule of law, the\npromotion of reconciliation and the development of the country."},{"id":"a-hrc-57-81-p0084","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"84","seq":83,"section":"3. Challenges in the implementation of the transitional justice process in the Democratic","text":"The team of international experts notes that the draft national policy on transitional\njustice, aimed at defining the Government's vision and conceptual and institutional\nframework for transitional justice in the Democratic Republic of the Congo, which was\nsubmitted to the Ministry of Human Rights in January 2023, does not yet include the\nrecommendations arising from the national consultations on transitional justice organized by\nthe Ministry of Human Rights with support from UNJHRO."},{"id":"a-hrc-57-81-p0085","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"85","seq":84,"section":"3. Challenges in the implementation of the transitional justice process in the Democratic","text":"The team of international experts notes that the draft national policy does not at this\nstage include any reference to several ongoing transitional justice initiatives, in particular\nFONAREV, FRIVAO and the Disarmament, Demobilization, Community Recovery and\nStabilization Programme. It nonetheless notes with satisfaction the initiative of FONAREV\nand the Truth, Justice and Reconciliation Commission of Kasai-Central Province to work\n14 Democratic Republic of the Congo, Act No. 22/065 of 26 December 2022 on the fundamental\nprinciples of protection and redress for victims of conflict-related sexual violence and victims of\ncrimes against the peace and security of humankind, art. 28.\ntogether to establish a common consultation framework for harmonizing their approaches\nand ensuring the complementarity of their actions in Kasai-Central Province."},{"id":"a-hrc-57-81-p0086","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"86","seq":85,"section":"3. Challenges in the implementation of the transitional justice process in the Democratic","text":"The team of international experts is concerned, however, about the development of a\nnational policy on reparations, under the aegis of FONAREV and CIA-VAR, separately from\nthe process to finalize the national policy on transitional justice."},{"id":"a-hrc-57-81-p0087","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"87","seq":86,"section":"3. Challenges in the implementation of the transitional justice process in the Democratic","text":"The consistency, coordination and complementarity sought by the Government\namong the various ongoing transitional justice initiatives should be made explicit in the final\nversion of the national policy on transitional justice. Otherwise, there might be duplication\nof efforts, loss of resources and even obstacles to the fulfilment of the mandates of the various\ninstitutions already in operation."},{"id":"a-hrc-57-81-p0088","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"88","seq":87,"section":"3. Challenges in the implementation of the transitional justice process in the Democratic","text":"The national policy on transitional justice would enable the Government to establish\na single national framework, focused on the needs of victims, to continue the coordinated\nimplementation, based on a common vision, of all the pillars of transitional justice at the\nprovincial, national and subregional levels."},{"id":"a-hrc-57-81-p0089","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"89","seq":88,"section":"3. Challenges in the implementation of the transitional justice process in the Democratic","text":"The team of international experts reiterates its call to the Ministry of Human Rights\nto continue and conclude the national consultations on transitional justice, in compliance with\ninternational standards and instruments, and to publish and disseminate widely the results of\nthe consultations so that they may inform the final version of the national policy on\ntransitional justice. The team invites the Government to adopt the national policy on\ntransitional justice and collectively commit to its effective implementation, with the support\nof its technical and financial partners."},{"id":"a-hrc-57-81-p0090","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"90","seq":89,"section":"3. Challenges in the implementation of the transitional justice process in the Democratic","text":"The team of international experts notes the absence of a mechanism for cooperation\namong technical and financial partners providing support for the transitional justice process,\nat both the national and provincial levels. It calls for the establishment of such a mechanism\nto effectively coordinate support for the transitional justice process.\n(b) Lack of sufficient effective funding to implement the transitional justice process"},{"id":"a-hrc-57-81-p0091","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"91","seq":90,"section":"3. Challenges in the implementation of the transitional justice process in the Democratic","text":"The team of international experts welcomes the innovative approach developed under\nAct No. 22/065, thanks to which 11 per cent of mining royalties are now allocated to\nFONAREV reparation programmes. It invites the Government to adopt similar approaches\nto strengthen the private sector's contribution to the financing of all transitional justice\ninitiatives."},{"id":"a-hrc-57-81-p0092","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"92","seq":91,"section":"3. Challenges in the implementation of the transitional justice process in the Democratic","text":"The team of international experts notes the efforts of the Congolese Government to\nfinancially support FONAREV. However, it would like this support to be expanded to all\ntransitional justice initiatives currently under way. Such financial efforts would ensure\nnational ownership of the transitional justice process and encourage greater participation by\nbilateral and multilateral partners."},{"id":"a-hrc-57-81-p0093","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"93","seq":92,"section":"3. Challenges in the implementation of the transitional justice process in the Democratic","text":"The team of international experts notes the low level of mobilization of international\npartners for the financing of the transitional justice process and regrets that the current\nfinancial difficulties of the United Nations Secretariat have had an impact on the support\nprovided by the Office of the United Nations High Commissioner for Human Rights to the\ntransitional justice process, particularly with regard to the deployment of additional technical\nexperts."},{"id":"a-hrc-57-81-p0094","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"94","seq":93,"section":"3. Challenges in the implementation of the transitional justice process in the Democratic","text":"The team of international experts calls on the Office of the United Nations High\nCommissioner for Human Rights and international partners to step up their financial support\nfor the transitional justice process in the Democratic Republic of the Congo, in line with its\nprevious recommendations and requests by the Human Rights Council.\n(c) Applying transitional justice in a context of insecurity and inter-community conflicts"},{"id":"a-hrc-57-81-p0095","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"95","seq":94,"section":"3. Challenges in the implementation of the transitional justice process in the Democratic","text":"The team of international experts is concerned by the withdrawal of MONUSCO from\nSouth Kivu Province at a time when several provinces in the east of the country are facing\nsituations of armed conflict and inter-community strife."},{"id":"a-hrc-57-81-p0096","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"96","seq":95,"section":"3. Challenges in the implementation of the transitional justice process in the Democratic","text":"The team of international experts calls on the Government and the Security Council\nto consider the major challenges in terms of access, security and human rights protection that\nthe next stages of the withdrawal of MONUSCO might cause in the absence of deployment\nof sufficient trained national armed and security forces who respect international\nhumanitarian and human rights law.\n(d) Growing impact of the cross-border dimension of conflicts"},{"id":"a-hrc-57-81-p0097","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"97","seq":96,"section":"3. Challenges in the implementation of the transitional justice process in the Democratic","text":"The team of international experts observes with concern the worsening regional\ntensions due to the conflicts, particularly in the east of the country. It notes that prioritizing\nthe military approach taken thus far in response to security and humanitarian challenges\ncannot in itself bring about peace or meet the needs expressed by the population concerned."},{"id":"a-hrc-57-81-p0098","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"98","seq":97,"section":"3. Challenges in the implementation of the transitional justice process in the Democratic","text":"The team of international experts points out the need for the Government and all\nstakeholders to step up their involvement in the implementation of the Nairobi Process, under\nthe aegis of the East African Community, and the Luanda road map, under the auspices of\nthe African Union, and to incorporate in these processes a human rights-based approach\nthrough transitional justice to achieve lasting peace. It also invites the Government to\nstrengthen dialogue with countries in the region through other existing subregional\ncooperation initiatives."},{"id":"a-hrc-57-81-p0099","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"99","seq":98,"section":"3. Challenges in the implementation of the transitional justice process in the Democratic","text":"The team of international experts notes the importance for the Government of\nintensifying implementation of the Disarmament, Demobilization, Community Recovery and\nStabilization Programme. It stresses that a coherent, long-term strategy for the demobilization\nof armed groups, taking into account the impact of the establishment of the Armed Defense\nReserve, is needed to support the implementation of regional political processes."},{"id":"a-hrc-57-81-p0100","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"100","seq":99,"section":"3. Challenges in the implementation of the transitional justice process in the Democratic","text":"The team of international experts underscores the vital importance of strengthening\nregional judicial cooperation to intensify the fight against impunity for cross-border offences,\nincluding in relation to the illegal exploitation of natural resources. It commends the efforts\nof MONUSCO and the Special Envoy of the Secretary-General for the Great Lakes Region\nto build the capacities of the Great Lakes Judicial Cooperation Network and invites the Office\nof the United Nations High Commissioner for Human Rights to become more involved in\nthose efforts."},{"id":"a-hrc-57-81-p0101","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"101","seq":100,"section":"A. Conclusions","text":"The team of international experts welcomes the excellent cooperation by the\nauthorities of the Democratic Republic of the Congo and would like to express its deep\ngratitude to them. It also welcomes the essential support of UNJHRO, MONUSCO and\nthe entire United Nations system."},{"id":"a-hrc-57-81-p0102","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"102","seq":101,"section":"A. Conclusions","text":"The team of international experts notes that, since its last report, the security and\nhumanitarian situation in the country has deteriorated significantly. It welcomes the\nannouncement of a humanitarian truce and ceasefire in July 2024, and strongly hopes\nthat these will be swiftly implemented to address the extreme vulnerability of the\ncivilian population."},{"id":"a-hrc-57-81-p0103","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"103","seq":102,"section":"A. Conclusions","text":"The team of international experts regrets the limited progress, and even\nslowdown, in the fight against impunity and the development of a comprehensive\nnational transitional justice process focused on the needs of victims, due to differing\npolitical agendas, particularly regarding the electoral context and the installation of the\nnew Government."},{"id":"a-hrc-57-81-p0104","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"104","seq":103,"section":"A. Conclusions","text":"The team of international experts invites the Government to strengthen its\nsupport for the judicial response to serious violations and abuses of international\nhuman rights law and international humanitarian law, particularly conflict-related\nsexual violence. This must include reinforced deployment of the judicial authorities in\nthe country, as well as the strengthening of their technical and operational capacities,\nincluding the development of national expertise in forensic medicine and forensic\npsychology."},{"id":"a-hrc-57-81-p0105","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"105","seq":104,"section":"A. Conclusions","text":"The team of international experts reiterates the need for the Government to\nstrengthen coordination of and support to the national transitional justice process,\nincluding financial support, taking into account the history, context and needs of the\npopulation of each affected province, to ensure the coherence and participatory nature\nof the process and its effectiveness in promoting peace, reconciliation and development."},{"id":"a-hrc-57-81-p0106","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"106","seq":105,"section":"A. Conclusions","text":"The implementation of the national transitional justice process becomes essential\nin the context of the withdrawal of MONUSCO. In this regard, the entities of the\nUnited Nations system, particularly UNJHRO, whose resources must be increased,\nhave a key role to play in supporting the Government's efforts."},{"id":"a-hrc-57-81-p0107","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"107","seq":106,"section":"B. Recommendations","text":"The team of international experts recalls the need to pursue the implementation\nof the recommendations made in its previous reports. It reiterates some of these\nrecommendations and makes new ones."},{"id":"a-hrc-57-81-p0108","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"108","seq":107,"section":"1. Vision and coordination of transitional justice initiatives","text":"The team of international experts recommends that the Government maintain\ntransitional justice as a priority objective as part of a high-level, consistent and\ncomplementary basis for the realization of its programme of action for the period\n2024�2028."},{"id":"a-hrc-57-81-p0109","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"109","seq":108,"section":"1. Vision and coordination of transitional justice initiatives","text":"The team of international experts urges the Government to finalize and\nimplement the national policy on transitional justice, taking into account the results of\nnational consultations, so that the policy reflects the perspectives of victims and\ncommunities in the various provinces."},{"id":"a-hrc-57-81-p0110","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"110","seq":109,"section":"1. Vision and coordination of transitional justice initiatives","text":"The team of international experts invites the Government to promulgate as soon\nas possible the revised version of the decree establishing the human rights liaison body\nand urges it to ensure the body's effective functioning."},{"id":"a-hrc-57-81-p0111","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"111","seq":110,"section":"1. Vision and coordination of transitional justice initiatives","text":"The team of international experts urges the Disarmament, Demobilization,\nCommunity Recovery and Stabilization Programme to develop synergies between it\nand ongoing transitional justice initiatives, specifically by prioritizing the development\nof screening mechanisms and adopting a consistent demobilization strategy."},{"id":"a-hrc-57-81-p0112","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"112","seq":111,"section":"1. Vision and coordination of transitional justice initiatives","text":"The team of international experts invites international partners supporting the\ntransitional justice process to strengthen their coordination and complementarity at the\nnational and provincial levels by establishing a framework for cooperation and\nsupporting the implementation of the Government's strategic action plan."},{"id":"a-hrc-57-81-p0113","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"113","seq":112,"section":"2. Prevention of impunity","text":"The team of international experts once again calls on the Government to continue\nits efforts to provide appropriate initial and in-service training for judges, to build the\ncapacity of professionals in the criminal justice system to investigate and prosecute\ninternational crimes, and to assign judges trained in this field to the areas concerned."},{"id":"a-hrc-57-81-p0114","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"114","seq":113,"section":"2. Prevention of impunity","text":"The team of international experts urges the Government to undertake reforms\nto strengthen the capacity of the civil courts, so that they become more involved in the\nfight against impunity for international crimes."},{"id":"a-hrc-57-81-p0115","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"115","seq":114,"section":"2. Prevention of impunity","text":"The team of international experts recommends that the Government implement\nall the provisions of Act No. 23/028 on the fundamental principles of the prison system,\nadopted on 15 June 2023."},{"id":"a-hrc-57-81-p0116","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"116","seq":115,"section":"2. Prevention of impunity","text":"The team of international experts calls on the Government to reverse its decision\nto lift the moratorium on enforcement of the death penalty, and to pursue dialogue with\nits partners in order to find a solution that respects the fundamental rights and human\ndignity of all."},{"id":"a-hrc-57-81-p0117","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"117","seq":116,"section":"2. Prevention of impunity","text":"The team of international experts invites the Government to continue its efforts\nto implement the road map and the recommendations contained in the Kinshasa\nDeclaration resulting from the work of the international symposium on the issues at\nstake and challenges in the field of forensic medicine in the Democratic Republic of the\nCongo."},{"id":"a-hrc-57-81-p0118","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"118","seq":117,"section":"2. Prevention of impunity","text":"The team of international experts recommends that the Human Rights Council\nbuild the capacities of the technical assistance team by increasing its human and\ntechnical resources so that it may continue to strengthen national efforts to combat\nimpunity."},{"id":"a-hrc-57-81-p0119","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"119","seq":118,"section":"2. Prevention of impunity","text":"The team of international experts encourages the authorities of the Democratic\nRepublic of the Congo and the International Criminal Court to pursue and strengthen\ntheir cooperation."},{"id":"a-hrc-57-81-p0120","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"120","seq":119,"section":"3. Consideration of victims at all stages of the transitional justice process","text":"The team of international experts urges the Government to ensure the active,\neffective and secure participation of victims in the transitional justice process, including\nongoing national consultations on the matter."},{"id":"a-hrc-57-81-p0121","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"121","seq":120,"section":"3. Consideration of victims at all stages of the transitional justice process","text":"The team of international experts invites the Government to ensure that\ninformation on the measures set out in Act No. 22/065 of 26 December 2022 is widely\ndisseminated among the judicial authorities, victims and their representatives, so that\nvictims can avail themselves of the measures, thus strengthening their access to justice."},{"id":"a-hrc-57-81-p0122","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"122","seq":121,"section":"3. Consideration of victims at all stages of the transitional justice process","text":"The team of international experts calls on the judicial authorities to\nsystematically request medical and psychological assessments for victims of\ninternational crimes involved in legal proceedings, including by broadening the legal\nbasis for requesting such assessments."},{"id":"a-hrc-57-81-p0123","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"123","seq":122,"section":"3. Consideration of victims at all stages of the transitional justice process","text":"The team of international experts urges FONAREV and FRIVAO to coordinate\ntheir approaches, including with other transitional justice initiatives, under the\nsupervision of their respective lead ministries, to support the development of\ncomprehensive individual and collective reparations programmes focused on the needs\nof victims."},{"id":"a-hrc-57-81-p0124","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"124","seq":123,"section":"4. Conflict prevention and guarantees of non-repetition","text":"The team of international experts urges the Government to tackle the\nhumanitarian and protection crises and the resulting gross violations and abuses of\ninternational humanitarian and human rights law by taking all measures to end armed\nconflict. It recommends that the Government make it a priority to provide lasting\nsolutions based on human rights through transitional justice, including accountability\nfor the perpetrators of these violations and abuses."},{"id":"a-hrc-57-81-p0125","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"125","seq":124,"section":"4. Conflict prevention and guarantees of non-repetition","text":"The team of international experts reiterates its recommendation that the Office\nof the United Nations High Commissioner for Human Rights continue its efforts to\nstrengthen the capacities of the Armed Forces of the Democratic Republic of the Congo\nin the field of human rights and international humanitarian law, especially in the\ncontext of the withdrawal of MONUSCO."},{"id":"a-hrc-57-81-p0126","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"126","seq":125,"section":"4. Conflict prevention and guarantees of non-repetition","text":"The team of international experts calls on development partners and the\ninternational community to support the Government in facilitating civilians' access to\na humanitarian response adapted to their most pressing needs."},{"id":"a-hrc-57-81-p0127","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"127","seq":126,"section":"5. Public, private and international funding of the transitional justice process","text":"The team of international experts calls on the provincial government of Kasai-\nCentral to provide adequate financial, material and human resources to ensure the full\nimplementation of the mandate of the Truth, Justice and Reconciliation Commission of\nKasai-Central Province."},{"id":"a-hrc-57-81-p0128","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"128","seq":127,"section":"5. Public, private and international funding of the transitional justice process","text":"The team of international experts reiterates its call on the Government to ensure\nthat its transitional justice and State reform initiatives are funded from the national\nbudget at both the central and provincial levels."},{"id":"a-hrc-57-81-p0129","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"129","seq":128,"section":"5. Public, private and international funding of the transitional justice process","text":"The team of international experts invites the Government to continue developing\npolicy mechanisms to organize the contributions of national and multinational\ncompanies operating in the Democratic Republic of the Congo to the funding of peace,\nreconciliation, stability and sustainable development initiatives, modelled on the\npioneering initiative for the financing of FONAREV."},{"id":"a-hrc-57-81-p0130","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"130","seq":129,"section":"5. Public, private and international funding of the transitional justice process","text":"The team of international experts once again encourages donors to step up their\nsupport for the transitional justice process at the national and provincial levels in the\nDemocratic Republic of the Congo."},{"id":"a-hrc-57-81-p0131","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"131","seq":130,"section":"6. Subregional dimension of the transitional justice process","text":"The team of international experts urges the Government to support the\nresumption of the implementation of the Nairobi Process and the Luanda road map,\nincluding for the purpose of integrating a human rights-based approach through\ntransitional justice, with the aim of taking into account subregional dynamics in the\nsearch for the root causes of conflicts and the prevention of their recurrence."},{"id":"a-hrc-57-81-p0132","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"132","seq":131,"section":"6. Subregional dimension of the transitional justice process","text":"The team of international experts recommends that the Government strengthen\ndialogue with countries in the region through other existing subregional cooperation\ninitiatives, including to promote subregional transitional justice initiatives."},{"id":"a-hrc-57-81-p0133","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"133","seq":132,"section":"6. Subregional dimension of the transitional justice process","text":"The team of international experts reiterates its call for closer cooperation\nbetween the Special Envoy of the Secretary-General for the Great Lakes Region and\nthe Office of the United Nations High Commissioner for Human Rights to further\nsupport the Great Lakes Judicial Cooperation Network."},{"id":"a-hrc-60-83-u0000","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":null,"seq":0,"section":null,"text":"United Nations                                                                                   A/HRC/60/83\nGeneral Assembly                                                           Distr.: General\n20 August 2025\nEnglish\nOriginal: French","unnumbered":true},{"id":"a-hrc-60-83-u0001","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":null,"seq":1,"section":null,"text":"Human Rights Council\nSixtieth session\n8 September–3 October 2025\nAgenda items 2 and 10\nAnnual report of the United Nations High Commissioner\nfor Human Rights and reports of the Office of the\nHigh Commissioner and the Secretary-General\nTechnical assistance and capacity-building","unnumbered":true},{"id":"a-hrc-60-83-u0002","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":null,"seq":2,"section":null,"text":"Summary\nBy resolution 57/34 of 11 October 2024, the Human Rights Council renewed the\nmandate of the team of international experts on the Democratic Republic of the Congo and\nrequested the team to provide the necessary technical support to the Government in\nimplementing effectively its National Transitional Justice Policy. The Council requested the\nteam of international experts to submit its final report at its sixtieth session.\nThe mandate was carried out against a backdrop of continuing tensions between the\nDemocratic Republic of the Congo and Rwanda, a worsening security and humanitarian\nsituation in the east of the country, and the withdrawal of the United Nations Organization\nStabilization Mission in the Democratic Republic of the Congo.\nThe team of international experts carried out three field visits, enabling it to assess\nremaining challenges and the options to be explored to promote the fight against impunity\nand transitional justice at the provincial, national and subregional levels.\nLastly, the team of international experts offered its conclusions and made\nrecommendations with a view to strengthening current and future activities.","unnumbered":true},{"id":"a-hrc-60-83-u0003","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":null,"seq":3,"section":null,"text":" Reissued for technical reasons on 16 September 2025.\n** Agreement was reached to publish the present report after the standard publication date owing to\ncircumstances beyond the submitter’s control.","unnumbered":true},{"id":"a-hrc-60-83-p0001","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"1","seq":4,"section":"I. Introduction","text":"By resolution 57/34 of 11 October 2024, the Human Rights Council renewed the\nmandate of the team of international experts on the Democratic Republic of the Congo and\nrequested the team to provide the necessary technical support to the Government in\nimplementing effectively its National Transitional Justice Policy, in particular by taking\naccount of the cross-border nature of conflict and insecurity in the Great Lakes, identifying\nthe causes of conflict and preventing their recurrence, and designing and implementing\nmechanisms for transitional justice and the fight against impunity, and encouraged it to\nsupport the Government in this regard, in particular by proposing concrete measures. This\nmandate was reiterated in Council resolution S-37/1 of 7 February 2025."},{"id":"a-hrc-60-83-p0002","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"2","seq":5,"section":"I. Introduction","text":"The Council requested the team of international experts to submit its final report to\nthe Council, in the framework of an enhanced interactive dialogue, at its sixtieth session and\nto present it with an oral update at its fifty-eighth session."},{"id":"a-hrc-60-83-p0003","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"3","seq":6,"section":"I. Introduction","text":"In the same resolution, the Council requested the High Commissioner to continue to\nprovide the Government of the Democratic Republic of the Congo with technical assistance,\nincluding the necessary forensic expertise, to support the country’s judicial authorities in their\ninvestigations into allegations of serious human rights violations and abuses, including\nconflict-related sexual violence and grave violations of children’s rights, with a view to\nbringing the perpetrators to justice."},{"id":"a-hrc-60-83-p0004","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"4","seq":7,"section":"I. Introduction","text":"On 11 October 2024, the High Commissioner for Human Rights renewed the\nmandates of Marie-Thérèse Keita-Bocoum (Côte d’Ivoire) and Bessolé René Bagoro\n(Burkina Faso) as, respectively, chair and member of the team of international experts."},{"id":"a-hrc-60-83-p0005","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"5","seq":8,"section":"I. Introduction","text":"In carrying out its mandate, the team of international experts was supported by a\nsecretariat comprising a coordinator and a human rights officer specializing in transitional\njustice. It conducted three field visits to the Democratic Republic of the Congo.1"},{"id":"a-hrc-60-83-p0006","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"6","seq":9,"section":"I. Introduction","text":"During its visits, the team of international experts met with a number of Congolese\nofficials, 2 members of the diplomatic corps, 3 representatives of United Nations agencies,\nfunds and programmes,4 members of the panel of facilitators of the African mediation process\nfor peace in the Democratic Republic of the Congo, 5 established by the African Union,\ninternational non-governmental organizations, 6 the Kasai-Central Truth, Justice and\nReconciliation Commission and civil society. The team of international experts was briefed\non the progress made in the fight against impunity and the implementation of transitional\njustice, and it provided technical support to the authorities in these areas."},{"id":"a-hrc-60-83-p0007","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"7","seq":10,"section":"I. Introduction","text":"On 1 April 2025, the team of international experts presented its oral report during the\ninteractive dialogue held as part of the Council’s fifty-eighth session."},{"id":"a-hrc-60-83-p0008","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"8","seq":11,"section":"I. Introduction","text":"The present report is submitted by the team of international experts, in accordance\nwith Council resolution 57/34, adopted on 11 October 2024. It highlights the various\nactivities undertaken by the team of international experts in fulfilment of its expanded\nmandate."},{"id":"a-hrc-60-83-p0009","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"9","seq":12,"section":"II. Mandate","text":"The team of international experts carried out its mandate against a backdrop of\nworsening armed conflict in the east of the country,7 with the expansion of the Mouvement\ndu 23 mars (M23) and the Rwanda Defence Force into the North and South Kivu Provinces,\nwhich has had humanitarian and security-related consequences that are ongoing at the time\nof writing. However, a number of important peace initiatives give cause for hope. On 19 July\n2025, the Government of the Democratic Republic of the Congo and a delegation\nrepresenting the coalition of Alliance Fleuve Congo (AFC) and M23 signed a declaration of\nprinciples in Doha. On 27 June 2025, the Governments of the Democratic Republic of the\nCongo and of Rwanda signed a peace agreement in Washington, D.C., under the auspices of\nthe United States of America."},{"id":"a-hrc-60-83-p0010","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"10","seq":13,"section":"II. Mandate","text":"The team of international experts completed its mandate in October 2024 when the\nDemocratic Republic of the Congo was elected to the Human Rights Council for the period\n2025–2027. The Democratic Republic of the Congo supported 235 of the 284\nrecommendations made during the fourth cycle of the universal periodic review. 8 These are\nopportunities for the country to strengthen its commitment to human rights."},{"id":"a-hrc-60-83-p0011","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"11","seq":14,"section":"II. Mandate","text":"The mandate was carried out in parallel with the withdrawal of the United Nations\nOrganization Stabilization Mission in the Democratic Republic of the Congo (MONUSCO).\nThe financial situation of the United Nations has had a negative impact on the mandate of\nthe team of international experts, forcing it to forego several field visits to the country and\nthe subregion and several other activities relating to its mandate."},{"id":"a-hrc-60-83-p0012","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"12","seq":15,"section":"II. Mandate","text":"Nevertheless, the team of international experts conducted three visits to the\nDemocratic Republic of the Congo and provided significant support to the Government. The\nteam of international experts would like to thank in particular the United Nations Joint\nHuman Rights Office in the Democratic Republic of the Congo and MONUSCO for their\nsupport."},{"id":"a-hrc-60-83-p0013","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"13","seq":16,"section":"III. Cooperation between the team of international experts and","text":"The team of international experts thanks the authorities of the Democratic Republic\nof the Congo for their fruitful cooperation, which facilitated its work."},{"id":"a-hrc-60-83-p0014","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"14","seq":17,"section":"III. Cooperation between the team of international experts and","text":"The team of international experts particularly appreciated its exchanges with the\nhighest authorities of the State, which enabled it to provide support in relation to the crisis in\nthe east of the country, to comment on various aspects concerning its mandate and to obtain\n6 Avocats sans frontières, Impunity Watch, TRIAL International, Solidarité féminine pour la paix et le\ndéveloppement intégral (SOFEPADI) and Coalition nationale des groupes de victimes en République\ndémocratique du Congo.\n7 https://news.un.org/fr/story/2025/01/1152571.\n8 See A/HRC/58/6/Add.1.\nstrategic information for the implementation of its new mandate in order to formulate relevant\nrecommendations to stakeholders."},{"id":"a-hrc-60-83-p0015","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"15","seq":18,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts remains deeply concerned about the deteriorating\nsecurity situation in the east of the country following the offensive led by M23 and RDF in\nthe North Kivu and South Kivu Provinces. It deplores the victims of this offensive among\nthe civilian population, the Congolese army, MONUSCO peacekeepers and soldiers of the\nSouthern African Development Community Mission in the Democratic Republic of the\nCongo."},{"id":"a-hrc-60-83-p0016","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"16","seq":19,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts laments the consequences of this escalation of\nviolence, notably the escape of major war criminals, the destruction of courts, a rise in crime\nand an increase in cases of kidnapping and vigilante justice. In addition, threats have been\nmade against members of the judiciary, human rights defenders, journalists, traditional\nleaders, and victims and witnesses involved in trials for serious crimes. 9"},{"id":"a-hrc-60-83-p0017","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"17","seq":20,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts is concerned about the worsening humanitarian\ncrisis, which is causing major displacements of the population inside and outside the country.\nIt notes the serious violations of international humanitarian law and the forced displacement\nof thousands of people, the difficulties in providing basic social services and the obstacles to\nthe delivery of humanitarian aid in areas affected by the security crisis. It deplores the threats\nagainst health workers and the kidnappings to which they are subjected, as well as the attacks\non medical facilities, looting of medicine supplies and destruction of medical equipment in\nthe affected provinces. All of this severely restricts the population’s access to primary\nhealthcare and results in reduced support from humanitarian organizations."},{"id":"a-hrc-60-83-p0018","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"18","seq":21,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts deplores the persistence of inter-community\nconflicts in the provinces not affected by armed conflict. For instance, Mai-Ndombe Province\nis marked by inter-community conflict, with numerous victims among the Teke and Yaka\ncommunities, and by clashes between soldiers of the Armed Forces of the Democratic\nRepublic of the Congo and “Mobondo” groups. In Tshopo province, an ongoing\nintercommunity conflict between the Mbole and Lengola communities has led to massive\npopulation displacement."},{"id":"a-hrc-60-83-p0019","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"19","seq":22,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts is concerned about the increase in cases of sexual\nviolence, including in the context of community conflicts. It notes that women and girls,\nparticularly those who have been displaced, have been raped, and in many cases gang-raped,\nby members of M23, the Allied Democratic Forces and the Cooperative for the Development\nof the Congo (CODECO), in North Kivu and Ituri Provinces. The dire humanitarian situation,\nparticularly in the east of the country, has considerably increased the risk that displaced\nwomen and girls will experience insecurity, sexual exploitation and child marriage."},{"id":"a-hrc-60-83-p0020","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"20","seq":23,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts remains concerned about the security situation in\nIturi Province, where the Allied Democratic Forces continue to commit atrocities. Ituri\nremains the epicentre of the conflict between CODECO and the armed group Front populaire\nd’autodéfense en Ituri (FPAC), affecting the Lendu and Hema communities."},{"id":"a-hrc-60-83-p0021","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"21","seq":24,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts is also concerned about the creation of the armed\ngroup, Convention pour la révolution populaire, by Thomas Lubanga, who has already been\nconvicted by the International Criminal Court.10"},{"id":"a-hrc-60-83-p0022","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"22","seq":25,"section":"V. Implementation of the mandate of the team of international","text":"The mandate of the team of international experts is to provide the Government with\nthe technical support necessary to combat impunity and implement a transitional justice\nprocess focused on the needs of victims, while taking into account the subregional impact of\nthe crises in the Democratic Republic of the Congo."},{"id":"a-hrc-60-83-p0023","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"23","seq":26,"section":"A. Fight against impunity","text":"With regard to the fight against impunity, the team of international experts continued\nto observe the administration of justice, including in emblematic legal cases, particularly\nthose opened in connection with the crisis linked to the Kamuina Nsapu militia."},{"id":"a-hrc-60-83-p0024","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"24","seq":27,"section":"1. Administration of justice","text":"The team of international experts notes with satisfaction the Government’s efforts to\nimprove the administration of justice but is concerned about the impact of the crisis in the\neast of the country on the fight against impunity and the protection of victims, witnesses and\njudicial actors."},{"id":"a-hrc-60-83-p0025","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"25","seq":28,"section":"1. Administration of justice","text":"The team of international experts notes that the occupation of Goma and Bukavu has\nled to the destruction of the main judicial and penitentiary facilities 11 and to the disappearance\nof almost all case files, including those concerning serious crimes, including conflict-related\nsexual violence."},{"id":"a-hrc-60-83-p0026","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"26","seq":29,"section":"1. Administration of justice","text":"The team of international experts notes that, against this challenging backdrop,\nMONUSCO and the United Nations Joint Human Rights Office, with the support of\ninternational partners in Bukavu, have assisted the Government in digitizing the case files of\n10 persons convicted of international crimes and 10 alleged perpetrators of such crimes."},{"id":"a-hrc-60-83-p0027","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"27","seq":30,"section":"1. Administration of justice","text":"The team of international experts is concerned about the wave of insecurity which,\nfollowing the mass escape of prisoners from the central prisons of Goma, Bukavu, Uvira,\nKabare and Kalemie between January and March 2025, has hit the justice sector in the east\nof the country, resulting in numerous deaths, sexual violence and the flight of almost 200 war\ncriminals."},{"id":"a-hrc-60-83-p0028","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"28","seq":31,"section":"1. Administration of justice","text":"The team of international experts remains concerned about the security situation in\nprisons and the living and working conditions of prison staff. It reiterates its recommendation\nthat prison facilities should be made more secure and that prison staff should be better trained\nand remunerated."},{"id":"a-hrc-60-83-p0029","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"29","seq":32,"section":"1. Administration of justice","text":"Recent events in the east of the country have worsened the insecurity faced by judicial\nactors and led to an increase in impunity, seriously undermining the rule of law. The\nUnited Nations Joint Human Rights Office has received many requests for protection from\njudicial actors, victims, witnesses and human rights defenders who have been threatened with\nreprisals by former prisoners implicated in serious crimes or by members of armed groups.\nThe establishment, by AFC/M23, of a conflict arbitration court 12 replacing the State\nauthorities constitutes a serious infringement of the State’s sovereignty.\n11 In North Kivu Province, the courthouse in Goma was pillaged and ransacked and remains out of\noperation. Munzenze Central Prison was set on fire, causing the death of 141 women prisoners and 28\nyoung children. All the remaining prisoners escaped, including those charged with or convicted of\nwar crimes or crimes against humanity. However, it should be noted that a few days before the\ncoalition entered Goma, the prison authorities had transferred to Kinshasa certain prisoners who were\ndangerous or had been involved in serious crimes. In South Kivu Province, Bukavu Court of Appeal\nwas pillaged, its archives were destroyed and the offices of members of the judiciary were ransacked.\nSeveral district courts, in Uvira, Kalehe and Fizi, have ceased to operate on account of the continued\ninsecurity.\n12 https://kivumorningpost.com/2025/05/30/goma-lafc-m23-ouvre-un-tribunal-darbitrage-pour-les-\ndossiers-judiciaires-en-suspens/."},{"id":"a-hrc-60-83-p0030","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"30","seq":33,"section":"1. Administration of justice","text":"The team of international experts invites the Government to improve protection\nmeasures for members of the judiciary and other persons affected by the crisis and invites the\nSecurity Council to strengthen the mandate of MONUSCO in order to increase its capacity\nto support the Government in its efforts to secure national territory and restore the rule of\nlaw."},{"id":"a-hrc-60-83-p0031","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"31","seq":34,"section":"1. Administration of justice","text":"The team of international experts is concerned about the increase in the number of\nwomen and children being trafficked, including for the purposes of forced labour and sexual\nexploitation, due to the security situation in the east of the country. It calls on the Government\nto step up the fight against trafficking in women and children and to provide comprehensive\nsupport for victims."},{"id":"a-hrc-60-83-p0032","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"32","seq":35,"section":"1. Administration of justice","text":"The team of international experts notes that a national conference on justice on the\ntheme “Why is the Congolese justice system in such a poor state?” was held from 6 to\n16 November 2024. The event was attended by over 3,500 representatives of the justice\nsector, political, administrative and traditional authorities, the student population and\ninternational partners."},{"id":"a-hrc-60-83-p0033","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"33","seq":36,"section":"1. Administration of justice","text":"The team of international experts encourages the Government to take into account the\nwork and discussions arising from the national conference on justice when drawing up the\nnew national justice reform policy for the period 2026–2035 and to adopt a holistic approach\nto transitional justice based on the needs of victims in order to ensure complementarity\nbetween the national justice reform policy and the national transitional justice policy."},{"id":"a-hrc-60-83-p0034","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"34","seq":37,"section":"1. Administration of justice","text":"The team of international experts commends the Government on the two bills, the\ndraft decree and the draft order presented at the forty-fourth meeting of the Council of\nMinisters on 23 May 202513 in the context of the implementation of transitional justice, in\nparticular the bill amending and supplementing the Organic Act on the organization,\nfunctioning and powers of the ordinary courts and the bill on the fundamental principles of\ntransitional justice."},{"id":"a-hrc-60-83-p0035","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"35","seq":38,"section":"1. Administration of justice","text":"The team of international experts is pleased to note that its recommendation\nconcerning greater involvement of the civil courts in dealing with international crimes has\nbeen taken into consideration, with the possibility of adding military judges to the\ncomposition of the Court of Cassation and the courts of appeal and the proposed creation of\nspecial units to investigate crimes against the peace and security of humanity. The team of\ninternational experts strongly encourages the Government to adopt these two bills in order to\nbe able to implement these measures."},{"id":"a-hrc-60-83-p0036","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"36","seq":39,"section":"1. Administration of justice","text":"The team of international experts notes the appointment on 1 April 2025, by\npresidential order, of 2,500 members of the national legal service, the second cohort to be\nappointed from among the 5,000 persons recruited in November 2022. It encourages the\nSupreme Council of Justice to begin their initial training, with the support of international\npartners."},{"id":"a-hrc-60-83-p0037","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"37","seq":40,"section":"1. Administration of justice","text":"The team of international experts deplores the consequences of the mass escape in\nSeptember 2024 of nearly 1,300 inmates, including dangerous criminals, from Kinshasa\nPenitentiary and Re-education Centre (Makala Prison), which resulted in the deaths of\n131 inmates, including 3 women, and during which hundreds of people were injured and at\nleast 269 women were raped."},{"id":"a-hrc-60-83-p0038","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"38","seq":41,"section":"1. Administration of justice","text":"The team of international experts calls on the Government to take protective measures\nwith a view to establishing the facts, identifying those responsible, providing reparation to\nvictims and strengthening the technical and operational capacities of prison staff."},{"id":"a-hrc-60-83-p0039","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"39","seq":42,"section":"1. Administration of justice","text":"The team of international experts appreciates the rehabilitation efforts that have been\nmade, including the renovation of Kinshasa Penitentiary and Re-education Centre, and the\nlaunch of projects to improve prison food and to facilitate the reintegration of prisoners. Work\nis also under way to improve the conditions of detention in Luzumu Prison in Kongo Central\nProvince."},{"id":"a-hrc-60-83-p0040","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"40","seq":43,"section":"1. Administration of justice","text":"The team of international experts is concerned about the impact of the mpox epidemic,\nparticularly in prison environments on account of the crowded living conditions. It\nencourages the Government to continue its rehabilitation efforts and to take measures to\nrelieve prison overcrowding in order to improve conditions of detention."},{"id":"a-hrc-60-83-p0041","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"41","seq":44,"section":"2. Handling of emblematic legal cases","text":"The team of international experts remains concerned about the lack of progress in the\ncases concerning the crisis linked to the Kamuina Nsapu militia. It notes, however, that the\ncase of the murder of the two United Nations experts, Zaida Catalán and Michael Sharp,\nremains under appeal before the High Military Court in Kinshasa, while the case of the\nmurder of the four Congolese persons who were accompanying them has been at a standstill\nsince 2017."},{"id":"a-hrc-60-83-p0042","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"42","seq":45,"section":"2. Handling of emblematic legal cases","text":"Only 2 out of 22 emblematic cases have reached the trial stage, namely, the case of\nthe murder of the two United Nations experts and the Mulombodi case."},{"id":"a-hrc-60-83-p0043","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"43","seq":46,"section":"2. Handling of emblematic legal cases","text":"The team of international experts is concerned about the suspension, as of late May\n2024, following the death of one of the two defendants, of the first trial based on command\nresponsibility in the Democratic Republic of the Congo, involving a general of the Congolese\nNational Police and a general of the Armed Forces of the Democratic Republic of the Congo."},{"id":"a-hrc-60-83-p0044","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"44","seq":47,"section":"2. Handling of emblematic legal cases","text":"The team of international experts deplores the lack of progress in the Bana Mura case,\nwhich has been referred to the High Military Court with jurisdiction over two of the\ndefendants, namely, a deputy chief superintendent of the Congolese National Police and a\nsenator and former vice-governor of Kasai."},{"id":"a-hrc-60-83-p0045","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"45","seq":48,"section":"2. Handling of emblematic legal cases","text":"The team of international experts invites the judicial authorities to take the necessary\nsteps to complete these legal proceedings in order to establish the truth, assign responsibility\nfor the offences committed in Kasai and realize the victims’ right to justice and reparation."},{"id":"a-hrc-60-83-p0046","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"46","seq":49,"section":"2. Handling of emblematic legal cases","text":"The team of international experts encourages the Government to continue, with the\nsupport of its partners, building the capacity of professionals in the criminal justice system\nto investigate and prosecute international crimes, in order to speed up and strengthen the\njudicial response."},{"id":"a-hrc-60-83-p0047","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"47","seq":50,"section":"2. Handling of emblematic legal cases","text":"The team of international experts has taken note of the conviction, in Ituri Province,\nof Jean Deus Django Dyogo, a political and administrative authority of the State at the time\nof the events and a member of the Coopérative pour le développement du Congo armed\ngroup, and in South Kivu Province, of Donat Kwenga Omari, a former warlord, including, in\nthe latter case, the award of substantial compensation to the 399 victims who had sued for\ndamages in the proceedings."},{"id":"a-hrc-60-83-p0048","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"48","seq":51,"section":"2. Handling of emblematic legal cases","text":"The team of international experts also takes note of the conviction of 425 people, since\nOctober 2024, for crimes involving violations of human rights and international humanitarian\nlaw: 149 officers of the Armed Forces of the Democratic Republic of the Congo, 21 officers\nof the Congolese National Police, 25 members of armed groups and 230 civilians."},{"id":"a-hrc-60-83-p0049","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"49","seq":52,"section":"2. Handling of emblematic legal cases","text":"The team of international experts commends the Government and its partners on the\nefforts made to update provincial strategies for prioritizing the prosecution of serious crimes,\nwithin the framework of the United Nations joint programme to support justice reform in the\nDemocratic Republic of the Congo. This work, which was carried out recently in the\nProvinces of Ituri, North Kivu, South Kivu, Kasai and Kasai Central, has brought the number\nof priority case files to 88."},{"id":"a-hrc-60-83-p0050","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"50","seq":53,"section":"2. Handling of emblematic legal cases","text":"The team of international experts encourages the Government to adopt a national\nstrategy on the prioritization of prosecutions that would ensure consistency and\nharmonization at the highest level and strengthen judicial independence."},{"id":"a-hrc-60-83-p0051","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"51","seq":54,"section":"2. Handling of emblematic legal cases","text":"The team of international experts appreciates the significant contribution of the\ntechnical assistance team deployed to the United Nations Joint Human Rights Office to\nsupport the judicial authorities in the fight against impunity through the sharing of expertise\nin forensic medicine and forensic psychology."},{"id":"a-hrc-60-83-p0052","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"52","seq":55,"section":"2. Handling of emblematic legal cases","text":"The team of international experts welcomes the forensic examinations carried out in\nthe village of Diboko, in Kasai Province, where the United Nations Joint Human Rights\nOffice forensic team, at the request of the military courts, documented the remains of 115\nvictims who had been discovered in secret mass graves."},{"id":"a-hrc-60-83-p0053","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"53","seq":56,"section":"2. Handling of emblematic legal cases","text":"The team of international experts also welcomes the forensic anthropological\nexamination of the remains of 29 police officers who had disappeared in Malenga, which has\nprovided crucial insight into the crisis linked to the Kamuina Nsapu militia and has allowed\ntheir families and communities to move through the mourning process and the judicial\nauthorities to initiate proceedings."},{"id":"a-hrc-60-83-p0054","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"54","seq":57,"section":"2. Handling of emblematic legal cases","text":"The team of international experts welcomes the official handover of a full\npostgraduate and residency programme in forensic medicine to the Minister of Higher and\nUniversity Education on 14 May 2025. This handover of programmes supported by the\nUnited Nations Joint Human Rights Office forensic team is in line with one of the\nrecommendations made in its previous report."},{"id":"a-hrc-60-83-p0055","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"55","seq":58,"section":"2. Handling of emblematic legal cases","text":"The team of international experts notes that, in June 2025, the forensic team helped\nthe Lubumbashi judicial authorities to assess the injuries of seven victims who had been\nexposed to toxic substances released by an ore processing plant and to carry out an\naccountability analysis."},{"id":"a-hrc-60-83-p0056","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"56","seq":59,"section":"2. Handling of emblematic legal cases","text":"The team of international experts invites international partners to support the\nGovernment’s efforts in this area with a view to strengthening the fight against impunity and\nensuring better access to justice for victims."},{"id":"a-hrc-60-83-p0057","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"57","seq":60,"section":"3. Situation of victims","text":"The team of international experts notes that the crisis in the east of the country has led\nto the collapse of protection mechanisms and has disrupted the provision of psychological\nsupport and care."},{"id":"a-hrc-60-83-p0058","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"58","seq":61,"section":"3. Situation of victims","text":"The team of international experts has been informed that, given the scale of the crisis\nin the east of the country, a partnership agreement has been signed between the\nUnited Nations system and the National Reparations Fund for Victims of Conflict-Related\nSexual Violence and Other Crimes against the Peace and Security of Humanity in the\nDemocratic Republic of the Congo, with a view to ensuring that victims of violence linked\nto the armed conflict in the Provinces of North Kivu and South Kivu have access to justice\nand urgent provisional reparation."},{"id":"a-hrc-60-83-p0059","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"59","seq":62,"section":"3. Situation of victims","text":"The team of international experts notes with satisfaction that Act No. 22/065 of\n26 December 2022, on the fundamental principles of protection and redress for victims of\nconflict-related sexual violence and victims of crimes against the peace and security of\nhumanity, has enabled some 1,500 victims to benefit from the abolition of registration and\nlegal fees."},{"id":"a-hrc-60-83-p0060","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"60","seq":63,"section":"3. Situation of victims","text":"The team of international experts is pleased that the United Nations Joint Human\nRights Office has supported 836 victims of international crimes. It urges the Government to\nsystematize the provision of legal, judicial and psycholegal support to victims of serious\ncrimes."},{"id":"a-hrc-60-83-p0061","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"61","seq":64,"section":"3. Situation of victims","text":"The team of international experts welcomes the steps taken to build the capacities of\nseven national actors to conduct psychological assessments tailored to mass crimes and to\ndraft expert reports with a focus on the trans- and intergenerational dimensions of the\nphysical, emotional, psychological and social repercussions of the acts committed."},{"id":"a-hrc-60-83-p0062","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"62","seq":65,"section":"3. Situation of victims","text":"The team of international experts encourages the actors concerned to promote the\ntransfer of skills and the development of national psychological expertise in order to provide\nthe country with the human resources needed to carry out psychological assessments of\nvictims and witnesses during legal proceedings. The team of international experts invites the\nGovernment to broaden the legal basis on which assessments of this kind may be ordered by\nthe judicial authorities."},{"id":"a-hrc-60-83-p0063","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"63","seq":66,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes some interesting advances in transitional\njustice at the provincial and national levels, as well as encouraging initiatives at the regional\nlevel.\n1.         Monitoring of the implementation of the transitional justice process in Kasai Central\nProvince"},{"id":"a-hrc-60-83-p0064","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"64","seq":67,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the continuous support that has been\nprovided to the provincial Truth, Justice and Reconciliation Commission since the launch of\nthe operational phase of its activities. It welcomes the development and approval of\ndocuments and tools relating to the truth-seeking process in preparation for the phase that\nwill involve taking statements from victims and witnesses."},{"id":"a-hrc-60-83-p0065","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"65","seq":68,"section":"B. Implementation of the transitional justice process","text":"The team of international experts recalls that this phase is crucial to establishing the\ntruth and requires the implementation of a protection strategy to ensure the security of\nvictims, witnesses, Commission buildings and personnel, and data."},{"id":"a-hrc-60-83-p0066","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"66","seq":69,"section":"B. Implementation of the transitional justice process","text":"The team of international experts appreciates the support provided to the provincial\nTruth, Justice and Reconciliation Commission through collaboration with the European\nUnion, the United Nations Entity for Gender Equality and the Empowerment of Women\n(UN-Women) and TRIAL International. It also welcomes the support provided by the\nPeacebuilding Fund for the project to promote transitional justice for peacebuilding in the\nKasai and Kasai Central Provinces. It strongly encourages other partners to support the\nCommission."},{"id":"a-hrc-60-83-p0067","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"67","seq":70,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the strategic consultations between the\nNational Reparations Fund for Victims of Conflict-Related Sexual Violence and Other\nCrimes against the Peace and Security of Humanity in the Democratic Republic of the Congo\nand the provincial Truth, Justice and Reconciliation Commission, facilitated by the\nUnited Nations Joint Human Rights Office, which have enabled the two organizations to\ndiscuss their respective mandates and to identify opportunities for collaboration in the\nimplementation of two important pillars of transitional justice, namely truth-seeking and\nreparation for the victims of the crisis linked to the Kamuina Nsapu militia in Kasai Central\nProvince. The team of international experts welcomes this initiative, which is in line with one\nof its recommendations, and calls for this collaboration to be formalized."},{"id":"a-hrc-60-83-p0068","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"68","seq":71,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes that there has been a lack of communication\nconcerning the activities of the provincial Truth, Justice and Reconciliation Commission. It\ndeplores the insufficient funding of the Commission by the provincial and national\nauthorities."},{"id":"a-hrc-60-83-p0069","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"69","seq":72,"section":"B. Implementation of the transitional justice process","text":"The team of international experts reiterates its recommendation to the government of\nKasai Central Province to give concrete expression to its support for the provincial Truth,\nJustice and Reconciliation Commission and invites the Ministry of Human Rights to include\nthe Commission in its budget.\n2.         Monitoring of the implementation of the transitional justice process at the national\nlevel"},{"id":"a-hrc-60-83-p0070","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"70","seq":73,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the Head of State’s ongoing commitment\nto transitional justice and the progress made by the Government at the national level."},{"id":"a-hrc-60-83-p0071","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"71","seq":74,"section":"B. Implementation of the transitional justice process","text":"The team of international experts particularly commends the Government on the\nadoption by the Council of Ministers of a set of legal texts, including the draft national\ntransitional justice policy.14 This policy sets out a new, context-specific approach that takes\n14   The texts in question, which were introduced at the forty-fourth meeting of the Council of Ministers\non 23 May 2025, are as follows: the bill amending and supplementing Organic Act No. 13/011-B of\n11 April 2013 on the organization, functioning and powers of the ordinary courts; the bill on the\nfundamental principles of transitional justice; the draft decree on the implementation of Act\ninto account the conflict and post-conflict situations that coexist in the country and advocates\na decentralized approach to transitional justice."},{"id":"a-hrc-60-83-p0072","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"72","seq":75,"section":"B. Implementation of the transitional justice process","text":"The team of international experts encourages the Parliament to adopt these legal texts\nand the Government to facilitate their implementation, taking into account the concerns of\nvictims in line with international standards."},{"id":"a-hrc-60-83-p0073","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"73","seq":76,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes that the approval of the strategy for\nimplementing the right to reparation, at the round table held by the National Reparations\nFund for Victims of Conflict-Related Sexual Violence and Other Crimes against the Peace\nand Security of Humanity in the Democratic Republic of the Congo from 1 to 3 July 2025,\nconstitutes a significant development."},{"id":"a-hrc-60-83-p0074","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"74","seq":77,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes that the persons in charge of the Disarmament,\nDemobilization, Community Recovery and Stabilization Programme do not wish to include\nformer combatants in the disarmament, demobilization and reintegration process without\nprior vetting and wish to ensure that human rights are taken into account in the process."},{"id":"a-hrc-60-83-p0075","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"75","seq":78,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the action taken, with the participation of\nthe United Nations Joint Human Rights Office, in response to the recommendation in which\nit called for closer collaboration between the Disarmament, Demobilization, Community\nRecovery and Stabilization Programme and other national mechanisms."},{"id":"a-hrc-60-83-p0076","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"76","seq":79,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the rapprochement between the\nUnited Nations Joint Human Rights Office and the Special Fund to Compensate Victims of\nIllicit Acts Carried Out by Uganda and recommends that priority should be given to collective\nreparation in Tshopo Province and that this collaboration should be strengthened in the fields\nof communication, data security, forensic medicine, site security and victim protection."},{"id":"a-hrc-60-83-p0077","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"77","seq":80,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the adoption of the national transitional\njustice policy and particularly appreciates the appointment, by the Ministry of Human Rights,\nof a coordinator and two deputies to lead its implementation."},{"id":"a-hrc-60-83-p0078","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"78","seq":81,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes the organization of two workshops on\ntransitional justice, involving national and international actors, by the Inter-Institutional\nCommission for Assistance to Victims and Support for Reforms. These workshops were an\nopportunity to review the activities carried out, gather recommendations from the actors\nconcerned and establish a permanent consultation framework."},{"id":"a-hrc-60-83-p0079","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"79","seq":82,"section":"B. Implementation of the transitional justice process","text":"The team of international experts encourages all initiatives to promote the\ncoordination of the State bodies involved in the transitional justice process and welcomes the\nholding, on 9 June 2025, of the first round table organized jointly by the United Nations Joint\nHuman Rights Office and the Ministry of Human Rights, with the participation of technical\nand financial partners and civil society, with a view to setting up a framework for\nconsultations between relevant actors in the field of transitional justice."},{"id":"a-hrc-60-83-p0080","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"80","seq":83,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the enthusiasm and willingness of civil\nsociety to become more involved in the transitional justice process. The team notes the\nconcern of civil society that it is not sufficiently involved and invites the Government to\nincrease its involvement."},{"id":"a-hrc-60-83-p0081","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"81","seq":84,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes that the Government wishes to set up a steering\ncommittee for the establishment of a special criminal court in the Democratic Republic of\nthe Congo."},{"id":"a-hrc-60-83-p0082","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"82","seq":85,"section":"B. Implementation of the transitional justice process","text":"The team of international experts deplores the slow progress made in setting up the\nhuman rights liaison body. It recalls the importance of this body for promoting and ensuring\nNo. 22/065 of 26 December 2022 on the fundamental principles of protection and redress for victims\nof conflict-related sexual violence and victims of crimes against the peace and security of humanity;\nand the draft ministerial order setting out the procedures for maintaining the single consolidated list of\nvictims of conflict-related sexual violence and victims of crimes against the peace and security of\nhumanity.\nrespect for human rights in the Democratic Republic of the Congo and invites the\nGovernment to work towards ensuring that it is fully operational."},{"id":"a-hrc-60-83-p0083","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"83","seq":86,"section":"B. Implementation of the transitional justice process","text":"The team of international experts is concerned about the disappearance of certain sites\nwhere mass crimes have been committed, throughout the Democratic Republic of the Congo,\nand points out that truth-seeking mechanisms will be severely impacted by the disappearance\nof evidence and that the protection of these sites is essential for memorialization."},{"id":"a-hrc-60-83-p0084","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"84","seq":87,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the efforts of the United Nations Joint\nHuman Rights Office to promote a human rights economy, realize the right to development\nand protect human rights in relation to the extractive industries. It notes with satisfaction the\norganization by the United Nations Joint Human Rights Office of training sessions on these\ntopics for relevant actors and welcomes the holding of the twentieth Mining Week by the\nGovernment.15 It calls on the Government and international partners to continue their efforts\nto support this sector."},{"id":"a-hrc-60-83-p0085","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"85","seq":88,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts welcomes the progress made through regional\npolitical processes."},{"id":"a-hrc-60-83-p0086","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"86","seq":89,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts welcomes the appointment of Faure Gnassingbé,\nPresident of the Council of Togo, as Mediator of the African Union. He will be supported by\na panel of facilitators 16 in his efforts to resolve the ongoing conflict in the east of the\nDemocratic Republic of the Congo."},{"id":"a-hrc-60-83-p0087","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"87","seq":90,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts welcomes the peace agreement between the\nDemocratic Republic of the Congo and Rwanda that was signed on 27 June 2025 in\nWashington, D.C., under the auspices of the United States of America."},{"id":"a-hrc-60-83-p0088","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"88","seq":91,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts is pleased that this agreement builds on the progress\nmade through the Nairobi and Luanda processes and the mediation in Doha and hopes that it\nwill constitute a step towards peace, stability and sustainable development in the Great Lakes\nRegion."},{"id":"a-hrc-60-83-p0089","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"89","seq":92,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts regrets, however, that this agreement makes no\nreference to accountability or transitional justice, including the rights to truth, justice,\nreparation and guarantees of non-repetition, and that the other processes do not take these\nmatters into account either."},{"id":"a-hrc-60-83-p0090","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"90","seq":93,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts calls for transitional justice to be incorporated into\npeace negotiations, with emphasis on the participation of civil society and women’s\norganizations. It remains convinced that a regional approach to transitional justice is all the\nmore essential as the causes and consequences of regional crises are cross-cutting rather than\nexclusive to each State."},{"id":"a-hrc-60-83-p0091","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"91","seq":94,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts encourages the Governments of the subregion to\npromote the creation of mechanisms for intergenerational and community dialogue, with the\nsupport of the United Nations. The team also calls on them to build the capacities of civil\nsociety in the subregion to enable it to make a meaningful contribution to the various peace\nprocesses."},{"id":"a-hrc-60-83-p0092","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"92","seq":95,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts remains convinced that dialogue is the path to\nachieving peaceful coexistence, peace and stability in the subregion. It advocates for adopting\n15 Sessions for the provincial authorities, the security and defence forces, the National Human Rights\nCommission and civil society in Haut-Katanga and Lualaba Provinces, as well as a special session for\nstaff and managers of Tenke Fungurume Mining in Fungurume, Lualaba Province, on the right to\ndevelopment, the United Nations Guiding Principles on Business and Human Rights, corporate social\nresponsibility, social auditing and the Sustainable Development Goals.\n16 The panel of facilitators of the African mediation process for peace in the Democratic Republic of the\nCongo is composed of the following persons: Olusegun Obasanjo, former President of Nigeria; Uhuru\nKenyatta, former President of Kenya; Mokgweetsi Masisi, former President of Botswana; Catherine\nSamba-Panza, former President of the Central African Republic; and Sahle-Work Zewde, former\nPresident of Ethiopia.\nprinciples of cohabitation based on international law, respect for human rights and the\nstrengthening of the rule of law in the Great Lakes Region.\n4.        Challenges in the implementation of the transitional justice process in the Democratic\nRepublic of the Congo"},{"id":"a-hrc-60-83-p0093","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"93","seq":96,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts notes five major challenges in the implementation\nof the transitional justice process despite the progress made: (a) inclusive implementation of\nthe transitional justice policy, taking into account national consultations; (b) inadequate\ncoordination and harmonization of national transitional justice mechanisms; (c) the lack of\neffective communication and the need to foster ownership of the process at the provincial\nand national levels; (d) the financing of the process; and (e) the difficulty of implementing\ntransitional justice in the midst of a deepening crisis.\n(a)        Inclusive implementation of the transitional justice policy, taking into account national\nconsultations"},{"id":"a-hrc-60-83-p0094","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"94","seq":97,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts regrets that the Government was unable to complete\nnational consultations in all provinces prior to the adoption of the national transitional justice\npolicy and encourages it to continue these consultations in accordance with the established\nroad map and with the support of its technical and financial partners."},{"id":"a-hrc-60-83-p0095","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"95","seq":98,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts notes that the process of implementing a national\ntransitional justice policy must be inclusive and participatory if it is to be successful. The\nteam invites the Government to facilitate the participation of civil society and the main\nbeneficiaries, including victims.\n(b)        Inadequate coordination and harmonization of national transitional justice mechanisms"},{"id":"a-hrc-60-83-p0096","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"96","seq":99,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts notes that the various national bodies working in the\nfield of transitional justice were created to meet specific needs but operate in accordance with\na comprehensive approach based on the four pillars of transitional justice."},{"id":"a-hrc-60-83-p0097","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"97","seq":100,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts believes that the various strategies in the areas of\nreparation, truth-seeking, justice and guarantees of non-repetition pursued by the relevant\nmechanisms should be aligned with national policy to ensure that there is a shared vision and\nresources are used efficiently."},{"id":"a-hrc-60-83-p0098","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"98","seq":101,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts reaffirms that coordinating and harmonizing the\nwork of the national transitional justice mechanisms around a shared vision supported by the\ndraft national transitional justice policy will facilitate the implementation of the process and\nensure its effectiveness."},{"id":"a-hrc-60-83-p0099","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"99","seq":102,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts notes with satisfaction that a mechanism for the\ntechnical coordination and evaluation of the implementation of the various pillars of\ntransitional justice is provided for in the bill on the fundamental principles of transitional\njustice in the Democratic Republic of the Congo. This mechanism, which would be under the\nauthority of the President, should allow for greater synergy between the various transitional\njustice initiatives."},{"id":"a-hrc-60-83-p0100","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"100","seq":103,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts notes that the bill on the fundamental principles of\ntransitional justice in the Democratic Republic of the Congo17 provides for the establishment\nof a new national truth and reconciliation commission, which would be responsible for\ntruth-seeking and the promotion of reconciliation, peaceful cohabitation and a culture of\npeace, and whose operating procedures would be set out in a decree. The commission’s\nmandate would have both a national and a provincial component. The team of international\nexperts invites the Government to find ways of ensuring cooperation between the national\nmechanism and the provincial mechanisms.\n17   See article 10 of the bill on the fundamental principles of transitional justice in the Democratic\nRepublic of the Congo: “A national truth, justice, peace and reconciliation commission shall be\nestablished.”\n(c)   The lack of effective communication and the need to foster ownership of the process at the\nprovincial and national levels"},{"id":"a-hrc-60-83-p0101","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"101","seq":104,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts continues to deplore the inadequate communication\nabout the transitional justice process at the provincial and national levels."},{"id":"a-hrc-60-83-p0102","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"102","seq":105,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts points out that the lack of communication about the\nprovincial and national transitional justice process has a direct impact on the ownership of\nthe process by the populations who are supposed to benefit directly from it, and invites the\nGovernment to disseminate the national transitional justice policy to enable those populations\nto take ownership of it."},{"id":"a-hrc-60-83-p0103","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"103","seq":106,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts reaffirms the need for greater involvement of civil\nsociety, including organizations that defend the rights of vulnerable groups, especially\nwomen, children and Indigenous Peoples, to make the process more inclusive and to meet\npeople’s aspirations.\n(d)    The financing of the process"},{"id":"a-hrc-60-83-p0104","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"104","seq":107,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts appreciates the Government’s considerable efforts\nto financially support the National Reparations Fund for Victims of Conflict-Related Sexual\nViolence and Other Crimes against the Peace and Security of Humanity in the Democratic\nRepublic of the Congo. However, it would like this support to be extended to all transitional\njustice initiatives currently under way, including the Truth, Justice and Reconciliation\nCommission of Kasai Central Province. Financial support of this kind would promote\nnational ownership of the transitional justice process and encourage bilateral and multilateral\npartners to step up their participation."},{"id":"a-hrc-60-83-p0105","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"105","seq":108,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts notes the low level of mobilization of international\npartners for the financing of the transitional justice process. It deplores the fact that the\nworsening financial situation of the United Nations has considerably affected the support\nprovided by the Office of the United Nations High Commissioner for Human Rights\n(OHCHR), including the deployment of additional technical experts, and urges the Office to\nkeep in place those already deployed."},{"id":"a-hrc-60-83-p0106","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"106","seq":109,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts calls on the Government, OHCHR and international\npartners to better coordinate and strengthen their financial support for the transitional justice\nprocess and to explore other types of financial partnership.\n(e)   The difficulty of implementing transitional justice in the midst of a deepening crisis"},{"id":"a-hrc-60-83-p0107","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"107","seq":110,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts recognizes the difficulty of implementing a\ntransitional justice policy while some of the country’s provinces are occupied or affected by\nconflict."},{"id":"a-hrc-60-83-p0108","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"108","seq":111,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts notes with concern the persistence of regional\ntensions, particularly in the east of the country. It recalls that responding to security and\nhumanitarian challenges through a military approach alone cannot bring about lasting peace\nor meet the needs expressed by the populations affected."},{"id":"a-hrc-60-83-p0109","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"109","seq":112,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts notes that the Government needs to strengthen\ndialogue with all parties involved in the crisis in the east of the country, including\nneighbouring countries, and calls for commitments to be honoured and for all existing\nsubregional cooperation initiatives to be taken into consideration."},{"id":"a-hrc-60-83-p0110","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"110","seq":113,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts reaffirms the need to incorporate a human\nrights-based approach into these processes within the context of transitional justice in order\nto achieve lasting peace."},{"id":"a-hrc-60-83-p0111","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"111","seq":114,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts reiterates that it is important for the Government to\nspeed up the implementation of the Disarmament, Demobilization, Community Recovery\nand Stabilization Programme, in accordance with international standards, and to take into\naccount the regional dimension."},{"id":"a-hrc-60-83-p0112","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"112","seq":115,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts underscores the importance of strengthening\nregional judicial cooperation to intensify the fight against impunity for cross-border offences,\nincluding offences involving the illegal exploitation of natural resources. It welcomes the\nefforts of MONUSCO, OHCHR and the Office of the Special Envoy of the Secretary-General\nfor the Great Lakes Region to build the capacities of the Great Lakes Judicial Cooperation\nNetwork."},{"id":"a-hrc-60-83-p0113","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"113","seq":116,"section":"3. Design and implementation of transitional justice at the regional level","text":"The team of international experts remains concerned about the ongoing withdrawal of\nMONUSCO at a time when several provinces in the east of the country are facing situations\nof armed conflict and intercommunity strife. The team of international experts calls on the\nGovernment and the Security Council to consider the major challenges in terms of access,\nsecurity and human rights protection that this withdrawal might cause if it is not offset by the\ndeployment of sufficient troops belonging to the armed forces and the national security forces\nwho have receiving training on the rules of international human rights law and international\nhumanitarian law and who abide by those rules."},{"id":"a-hrc-60-83-p0114","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"114","seq":117,"section":"A. Conclusions","text":"The team of international experts is grateful to the Congolese authorities for\nengaging in positive and fruitful cooperation throughout its mandate. It commends\nthem on their collaborative approach and their efforts to implement transitional justice\nand combat impunity."},{"id":"a-hrc-60-83-p0115","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"115","seq":118,"section":"A. Conclusions","text":"The team of international experts is also grateful to the entire United Nations\nsystem, including MONUSCO and the Office of the Special Envoy of the\nSecretary-General for the Great Lakes Region, and the diplomatic community for their\ncontinued support and appreciates the receptiveness of civil society and national and\ninternational non-governmental organizations working to combat impunity and\npromote transitional justice. It is also grateful to the panel of facilitators of the African\nmediation process for peace in the Democratic Republic of the Congo for giving it the\nopportunity to discuss its mandate and the possibility of incorporating transitional\njustice into subregional peace initiatives."},{"id":"a-hrc-60-83-p0116","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"116","seq":119,"section":"A. Conclusions","text":"The team of international experts welcomes the progress made on the legislative\nand regulatory fronts and the adoption of the national transitional justice policy and\nhopes that this policy will meet the expectations of the Congolese people in terms of\njustice, reconciliation and lasting peace. It also appreciates the efforts made to\ncoordinate, harmonize and finance national transitional justice mechanisms."},{"id":"a-hrc-60-83-p0117","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"117","seq":120,"section":"A. Conclusions","text":"The team of international experts remains deeply concerned about the impact of\nthe crisis in the east of the country on the fight against impunity and is worried about\nthe lack of progress in legal cases, particularly the emblematic cases opened in\nconnection with the crisis linked to the Kamuina Nsapu militia in Kasai Central\nProvince. It fears that these delays within the judicial system, combined with the\nchallenges faced by the provincial Truth, Justice and Reconciliation Commission, will\nhave an impact on progress towards reconciliation and lasting peace in the province."},{"id":"a-hrc-60-83-p0118","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"118","seq":121,"section":"A. Conclusions","text":"The team of international experts welcomes all the initiatives undertaken since\nthe signing of the Peace, Security and Cooperation Framework for the Democratic\nRepublic of the Congo and the Region in Addis Ababa on 24 February 2013 with a view\nto resolving conflicts and achieving lasting peace, particularly in the east of the country.\nIt notes, moreover, that the escalation of the crisis in the east of the country proves that\npeace in this part of the country remains very fragile and that solutions can be found\nonly through the genuine shared commitment of actors in the subregion. In this context,\nit stresses the need to develop a regional approach to transitional justice, starting by\nexplicitly incorporating this theme into the regional peace processes of Addis Ababa,\nLuanda, Nairobi, Doha and Washington, D.C."},{"id":"a-hrc-60-83-p0119","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"119","seq":122,"section":"A. Conclusions","text":"The team of international experts draws the attention of the Congolese\nauthorities to the need to strengthen the judicial response to serious violations of human\nrights and international humanitarian law, with a focus on building the technical and\noperational capacities of judicial actors and developing national expertise in forensic\nmedicine and the provision of psychological support."},{"id":"a-hrc-60-83-p0120","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"120","seq":123,"section":"A. Conclusions","text":"The team of international experts calls on the Government once again to step up\nits coordination and its support, including financial support, for the national\ntransitional justice process, taking into account the history, circumstances and needs of\nthe affected populations, in order to ensure the coherence, participatory nature and\neffectiveness of the process and thus promote peace, reconciliation and development."},{"id":"a-hrc-60-83-p0121","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"121","seq":124,"section":"A. Conclusions","text":"The team of international experts calls for synergy between technical and\nfinancial partners. In view of the immense challenges facing the country, it also calls for\nan increase in the resources allocated to the United Nations Joint Human Rights Office\nto enable it to effectively support the fight against impunity and the transitional justice\nprocess that is under way and it stands ready to support the authorities in their search\nfor ways to achieve lasting peace."},{"id":"a-hrc-60-83-p0122","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"122","seq":125,"section":"B. Recommendations","text":"The team of international experts recalls that it is necessary to continue\nimplementing the recommendations made in its previous reports. It reiterates some of\nits recommendations and makes some new ones."},{"id":"a-hrc-60-83-p0123","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"123","seq":126,"section":"1. Prevention of impunity","text":"In view of the current impact of the crisis in the east of the country on the fight\nagainst impunity, the team of international experts urges the Government to take\nmeasures to preserve case files and to secure judicial and penitentiary facilities,\nincluding by digitizing files and ensuring the protection of victims, witnesses, human\nrights defenders and all those working in the criminal justice system. It invites\ninternational partners to support the Government in taking these measures."},{"id":"a-hrc-60-83-p0124","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"124","seq":127,"section":"1. Prevention of impunity","text":"The team of international experts recommends that the Human Rights Council\nbuild the capacities of the technical assistance team by maintaining and increasing its\nhuman and financial resources in order to avoid undermining efforts to combat\nimpunity. It recommends that the Government establish forensic medicine programmes\nat Congolese universities."},{"id":"a-hrc-60-83-p0125","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"125","seq":128,"section":"1. Prevention of impunity","text":"The team of international experts reiterates its call for the Government and the\nSupreme Council of Justice to continue their efforts to provide adequate initial and\nin-service training for members of the national legal service."},{"id":"a-hrc-60-83-p0126","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"126","seq":129,"section":"1. Prevention of impunity","text":"The team of international experts encourages the Government to continue\nbuilding the capacity of all those working in the criminal justice system to investigate\nand prosecute international crimes, and to increase the involvement of the civil courts.\nIt invites all international partners to support these efforts with a view to improving\ncriminal investigations, strengthening the fight against impunity and ensuring better\naccess to justice for victims."},{"id":"a-hrc-60-83-p0127","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"127","seq":130,"section":"1. Prevention of impunity","text":"The team of international experts invites the judicial authorities to take all the\nnecessary steps to complete the relevant legal proceedings in order to establish the truth,\nassign responsibility for the offences committed in Kasai and realize the victims’ right\nto justice and reparation."},{"id":"a-hrc-60-83-p0128","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"128","seq":131,"section":"1. Prevention of impunity","text":"The team of international experts encourages the Government to give further\nthought to setting up a special court or mixed chambers, taking into account the\nsubregional dimension of the crisis, and to continue engaging in regional judicial\ncooperation."},{"id":"a-hrc-60-83-p0129","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"129","seq":132,"section":"1. Prevention of impunity","text":"The team of international experts remains concerned about the lifting of the\nmoratorium on the death penalty and calls on the Government to reconsider its\ndecision."},{"id":"a-hrc-60-83-p0130","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"130","seq":133,"section":"2. Vision and coordination of transitional justice initiatives","text":"The team of international experts invites the United Nations Joint Human Rights\nOffice to help the authorities, international partners and stakeholders to organize\nthemselves in order to better coordinate and finance the implementation of the\ntransitional justice strategy and to enable the population to take ownership of the\nstrategy."},{"id":"a-hrc-60-83-p0131","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"131","seq":134,"section":"2. Vision and coordination of transitional justice initiatives","text":"The team of international experts encourages the Government to coordinate the\nvarious strategies relating to reparation, truth-seeking, justice and guarantees of\nnon-repetition around a shared vision in order to promote the implementation of the\nnational transitional justice policy and the efficient use of resources."},{"id":"a-hrc-60-83-p0132","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"132","seq":135,"section":"2. Vision and coordination of transitional justice initiatives","text":"The team of international experts calls on the national and international actors\ninvolved in the transitional justice process to act in synergy and coordinate their\nresources and recommends that the National Reparations Fund for Victims of\nConflict-Related Sexual Violence and Other Crimes against the Peace and Security of\nHumanity in the Democratic Republic of the Congo and the provincial Truth, Justice\nand Reconciliation Commission formalize their collaboration with a view to better\naligning their approaches and ensuring the complementarity of their actions in Kasai\nCentral Province."},{"id":"a-hrc-60-83-p0133","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"133","seq":136,"section":"2. Vision and coordination of transitional justice initiatives","text":"The team of international experts encourages international partners supporting\nthe transitional justice process to strengthen the coordination and complementarity of\ntheir actions at the national and provincial levels and to implement the consultation\nframework established at the round table of 9 June 2025."},{"id":"a-hrc-60-83-p0134","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"134","seq":137,"section":"2. Vision and coordination of transitional justice initiatives","text":"The team of international experts invites the Government to redouble its efforts\nto ensure that the human rights liaison body is fully operational."},{"id":"a-hrc-60-83-p0135","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"135","seq":138,"section":"3. Consideration of victims at all stages of the process","text":"The team of international experts encourages the Parliament to adopt the legal\ninstruments on transitional justice presented at the forty-fourth meeting of the Council\nof Ministers on 23 May 2025."},{"id":"a-hrc-60-83-p0136","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"136","seq":139,"section":"3. Consideration of victims at all stages of the process","text":"It encourages the Government to facilitate the implementation of these\ninstruments and to ensure the effective and secure participation of victims, civil society\nand religious and traditional authorities in the transitional justice process, including\nduring national consultations. It also encourages the Government to ensure data\nsecurity."},{"id":"a-hrc-60-83-p0137","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"137","seq":140,"section":"3. Consideration of victims at all stages of the process","text":"The team of international experts reiterates its call for the judicial authorities to\nsystematically request medical and psychological assessments of victims of international\ncrimes involved in legal proceedings, including by broadening the legal basis for\nrequesting such assessments."},{"id":"a-hrc-60-83-p0138","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"138","seq":141,"section":"3. Consideration of victims at all stages of the process","text":"The team of international experts encourages the relevant actors to promote the\ntransfer of skills and the development of national psychological expertise in order to\nprovide the country with the human resources needed to carry out psychological\nassessments of and provide psychotherapy to victims and witnesses."},{"id":"a-hrc-60-83-p0139","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"139","seq":142,"section":"4. Conflict prevention and guarantees of non-repetition","text":"The team of international experts encourages the Disarmament, Demobilization,\nCommunity Recovery and Stabilization Programme to continue developing synergies\nbetween the Programme and ongoing transitional justice initiatives, specifically by\nprioritizing the development of screening mechanisms and adopting a consistent\ndemobilization strategy, including in the implementation of the agreement signed in\nWashington, D.C."},{"id":"a-hrc-60-83-p0140","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"140","seq":143,"section":"4. Conflict prevention and guarantees of non-repetition","text":"The team of international experts calls on the Government and international\npartners to continue their efforts to support the promotion of a human rights economy,\nthe realization of the right to development and the protection of human rights in\nrelation to the extractive industries."},{"id":"a-hrc-60-83-p0141","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"141","seq":144,"section":"5. Public, private and international funding of the transitional justice process","text":"The team of international experts once again urges the Government and the\nprovincial government of Kasai Central to provide the provincial Truth, Justice and\nReconciliation Commission with adequate financial, material and human resources to\nenable it to fully discharge its mandate."},{"id":"a-hrc-60-83-p0142","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"142","seq":145,"section":"5. Public, private and international funding of the transitional justice process","text":"The team of international experts calls on the Government, OHCHR and\ninternational partners to better coordinate and strengthen their financial support for\nthe national transitional justice process and to explore other types of financial\npartnership."},{"id":"a-hrc-60-83-p0143","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"143","seq":146,"section":"6. Subregional dimension of the transitional justice process","text":"The team of international experts calls for transitional justice to be incorporated\ninto peace negotiations and underscores the importance of the participation of civil\nsociety and women’s organizations."},{"id":"a-hrc-60-83-p0144","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"144","seq":147,"section":"6. Subregional dimension of the transitional justice process","text":"The team of international experts notes that the Government needs to strengthen\ndialogue with all parties involved in the crisis in the east of the country, including\nneighbouring countries, and calls for commitments to be honoured and for all existing\nsubregional cooperation initiatives to be taken into consideration."},{"id":"a-hrc-60-83-p0145","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"145","seq":148,"section":"6. Subregional dimension of the transitional justice process","text":"The team of international experts encourages the Special Envoy of the\nSecretary-General for the Great Lakes Region and OHCHR to step up their\ncooperation in order to further support the Great Lakes Judicial Cooperation Network."}]});